// src/lexer.lang - Lexer for self-hosting compiler
// Tokenizes source code into a stream of tokens

// ============================================================
// Token Types (constants)
// ============================================================

// Special
pub var TOKEN_EOF i64 = 0;
pub var TOKEN_ERROR i64 = 1;

// Literals
var TOKEN_IDENT i64 = 2;
var TOKEN_NUMBER i64 = 3;
var TOKEN_STRING i64 = 4;

// Keywords
pub var TOKEN_FUNC i64 = 5;
pub var TOKEN_VAR i64 = 6;
pub var TOKEN_STRUCT i64 = 7;
var TOKEN_IF i64 = 8;
var TOKEN_ELSE i64 = 9;
var TOKEN_WHILE i64 = 10;
var TOKEN_RETURN i64 = 11;
var TOKEN_TRUE i64 = 12;
var TOKEN_FALSE i64 = 13;
var TOKEN_NIL i64 = 14;

// Type keywords
var TOKEN_I8 i64 = 15;
var TOKEN_I16 i64 = 16;
var TOKEN_I32 i64 = 17;
var TOKEN_I64 i64 = 18;
var TOKEN_U8 i64 = 19;
var TOKEN_U16 i64 = 20;
var TOKEN_U32 i64 = 21;
var TOKEN_U64 i64 = 22;
var TOKEN_BOOL i64 = 23;
var TOKEN_VOID i64 = 24;

// Operators
var TOKEN_PLUS i64 = 25;      // +
var TOKEN_MINUS i64 = 26;     // -
var TOKEN_STAR i64 = 27;      // *
var TOKEN_SLASH i64 = 28;     // /
var TOKEN_PERCENT i64 = 29;   // %
var TOKEN_AMP i64 = 30;       // &
var TOKEN_BANG i64 = 31;      // !
var TOKEN_EQ i64 = 32;        // =
var TOKEN_EQEQ i64 = 33;      // ==
var TOKEN_BANGEQ i64 = 34;    // !=
var TOKEN_LT i64 = 35;        // <
var TOKEN_GT i64 = 36;        // >
var TOKEN_LTEQ i64 = 37;      // <=
var TOKEN_GTEQ i64 = 38;      // >=
var TOKEN_AMPAMP i64 = 39;    // &&
var TOKEN_PIPEPIPE i64 = 40;  // ||

// Punctuation
var TOKEN_LPAREN i64 = 41;    // (
var TOKEN_RPAREN i64 = 42;    // )
var TOKEN_LBRACE i64 = 43;    // {
var TOKEN_RBRACE i64 = 44;    // }
var TOKEN_LBRACKET i64 = 45;  // [
var TOKEN_RBRACKET i64 = 46;  // ]
var TOKEN_COMMA i64 = 47;     // ,
var TOKEN_SEMICOLON i64 = 48; // ;
var TOKEN_DOT i64 = 49;       // .
var TOKEN_COLON i64 = 50;     // :
var TOKEN_COLONEQ i64 = 51;   // :=

// Macro tokens
pub var TOKEN_MACRO i64 = 52;         // 'macro' keyword
var TOKEN_DOLLAR_LBRACE i64 = 53; // ${ (quote start)
var TOKEN_DOLLAR i64 = 54;        // $ (unquote)
var TOKEN_DOLLAR_AT i64 = 55;     // $@ (unquote string as identifier)

// Reader macro tokens
pub var TOKEN_IMPORT i64 = 56;        // 'import' keyword
pub var TOKEN_READER i64 = 57;        // 'reader' keyword
var TOKEN_READER_MACRO i64 = 58;  // #name{...} reader macro invocation
pub var TOKEN_INCLUDE i64 = 59;       // 'include' keyword

// Bitwise operators
var TOKEN_PIPE i64 = 60;          // |
var TOKEN_CARET i64 = 61;         // ^
var TOKEN_LTLT i64 = 62;          // <<
var TOKEN_GTGT i64 = 63;          // >>

// Compound assignment
var TOKEN_PLUSEQ i64 = 64;        // +=
var TOKEN_MINUSEQ i64 = 65;       // -=
var TOKEN_STAREQ i64 = 66;        // *=
var TOKEN_SLASHEQ i64 = 67;       // /=
var TOKEN_PERCENTEQ i64 = 68;     // %=

// Loop control
var TOKEN_BREAK i64 = 69;         // break
var TOKEN_CONTINUE i64 = 70;      // continue

// Let expression tokens
var TOKEN_LET i64 = 71;           // let
var TOKEN_IN i64 = 72;            // in

// Function type token
var TOKEN_FN i64 = 73;            // fn (for function pointer types)

// Sum types
pub var TOKEN_ENUM i64 = 74;          // enum
var TOKEN_MATCH i64 = 75;         // match
var TOKEN_ARROW i64 = 76;         // => (fat arrow for match arms)

// Algebraic effects
pub var TOKEN_EFFECT i64 = 77;        // effect
var TOKEN_PERFORM i64 = 78;       // perform
var TOKEN_HANDLE i64 = 79;        // handle
var TOKEN_WITH i64 = 80;          // with
var TOKEN_RESUME i64 = 81;        // resume

// Closure type
var TOKEN_CLOSURE i64 = 82;       // closure (for closure type)

// FFI
var TOKEN_EXTERN i64 = 83;        // extern (external function declaration)

// Module system
var TOKEN_REQUIRE i64 = 84;       // require (module dependency reference)

// Visibility
var TOKEN_PUB i64 = 85;           // pub (public visibility modifier)

// Floating point types
var TOKEN_F32 i64 = 86;           // f32
var TOKEN_F64 i64 = 87;           // f64
var TOKEN_FLOAT i64 = 88;         // float literal (contains decimal point)

// Type conversion
var TOKEN_CAST i64 = 89;          // cast (type conversion)
var TOKEN_BITCAST i64 = 90;       // bitcast (reinterpret bits)

// ============================================================
// Token struct
// ============================================================

struct Token {
    type_tok i64;
    lexeme *u8;
    lexeme_len i64;
    line i64;
    col i64;
    content *u8;      // For reader macros: content between braces
    content_len i64;  // For reader macros: length of content
}

// Accessor functions for backward compatibility
// These cast *u8 to *Token and use field access

pub func tok_type(tok *u8) i64 {
    var t *Token = tok;
    return t.type_tok;
}

func tok_set_type(tok *u8, typ i64) void {
    var t *Token = tok;
    t.type_tok = typ;
}

pub func tok_lexeme(tok *u8) *u8 {
    var t *Token = tok;
    return t.lexeme;
}

func tok_set_lexeme(tok *u8, ptr *u8) void {
    var t *Token = tok;
    t.lexeme = ptr;
}

pub func tok_lexeme_len(tok *u8) i64 {
    var t *Token = tok;
    return t.lexeme_len;
}

func tok_set_lexeme_len(tok *u8, len i64) void {
    var t *Token = tok;
    t.lexeme_len = len;
}

pub func tok_line(tok *u8) i64 {
    var t *Token = tok;
    return t.line;
}

func tok_set_line(tok *u8, ln i64) void {
    var t *Token = tok;
    t.line = ln;
}

pub func tok_col(tok *u8) i64 {
    var t *Token = tok;
    return t.col;
}

func tok_set_col(tok *u8, c i64) void {
    var t *Token = tok;
    t.col = c;
}

pub func tok_content(tok *u8) *u8 {
    var t *Token = tok;
    return t.content;
}

func tok_set_content(tok *u8, ptr *u8) void {
    var t *Token = tok;
    t.content = ptr;
}

pub func tok_content_len(tok *u8) i64 {
    var t *Token = tok;
    return t.content_len;
}

func tok_set_content_len(tok *u8, len i64) void {
    var t *Token = tok;
    t.content_len = len;
}

func tok_alloc() *u8 {
    return alloc(56);  // 7 fields * 8 bytes
}

// ============================================================
// Lexer state (global)
// ============================================================

var lex_source *u8 = nil;
var lex_source_len i64 = 0;
var lex_start i64 = 0;
var lex_current i64 = 0;
var lex_line i64 = 1;
var lex_col i64 = 1;
var lex_start_col i64 = 1;

pub func lexer_init(source *u8) void {
    lex_source = source;
    lex_source_len = strlen(source);
    lex_start = 0;
    lex_current = 0;
    lex_line = 1;
    lex_col = 1;
    lex_start_col = 1;
}

// ============================================================
// Character helpers
// ============================================================

func is_alpha(c u8) bool {
    if c >= 97 {  // 'a'
        if c <= 122 {  // 'z'
            return true;
        }
    }
    if c >= 65 {  // 'A'
        if c <= 90 {  // 'Z'
            return true;
        }
    }
    if c == 95 {  // '_'
        return true;
    }
    return false;
}

func is_digit(c u8) bool {
    if c >= 48 {  // '0'
        if c <= 57 {  // '9'
            return true;
        }
    }
    return false;
}

func is_alphanumeric(c u8) bool {
    return is_alpha(c) || is_digit(c);
}

// ============================================================
// Lexer helpers
// ============================================================

func lex_is_at_end() bool {
    return lex_current >= lex_source_len;
}

func lex_peek() u8 {
    if lex_is_at_end() {
        return 0;
    }
    return *(lex_source + lex_current);
}

func lex_peek_next() u8 {
    if lex_current + 1 >= lex_source_len {
        return 0;
    }
    return *(lex_source + lex_current + 1);
}

func lex_advance() u8 {
    var c u8 = *(lex_source + lex_current);
    lex_current = lex_current + 1;
    lex_col = lex_col + 1;
    return c;
}

func lex_match(expected u8) bool {
    if lex_is_at_end() {
        return false;
    }
    if *(lex_source + lex_current) != expected {
        return false;
    }
    lex_current = lex_current + 1;
    lex_col = lex_col + 1;
    return true;
}

// ============================================================
// Token creation
// ============================================================

func make_token(tok_type i64) *u8 {
    var tok *u8 = tok_alloc();
    tok_set_type(tok, tok_type);
    tok_set_lexeme(tok, lex_source + lex_start);
    tok_set_lexeme_len(tok, lex_current - lex_start);
    tok_set_line(tok, lex_line);
    tok_set_col(tok, lex_start_col);
    return tok;
}

func error_token(msg *u8) *u8 {
    var tok *u8 = tok_alloc();
    tok_set_type(tok, TOKEN_ERROR);
    tok_set_lexeme(tok, msg);
    tok_set_lexeme_len(tok, strlen(msg));
    tok_set_line(tok, lex_line);
    tok_set_col(tok, lex_start_col);
    return tok;
}

// ============================================================
// Skip whitespace and comments
// ============================================================

func skip_block_comment() void {
    lex_advance();  // consume /
    lex_advance();  // consume *
    while !lex_is_at_end() {
        if lex_peek() == 42 {
            if lex_peek_next() == 47 {
                lex_advance();  // consume *
                lex_advance();  // consume /
                return;
            }
        }
        if lex_peek() == 10 { lex_line = lex_line + 1; lex_col = 0; }
        lex_advance();
    }
}

func skip_whitespace() void {
    var done i64 = 0;
    while done == 0 {
        if lex_is_at_end() {
            done = 1;
        } else {
            var c u8 = lex_peek();

            if c == 32 || c == 9 || c == 13 {  // space, tab, CR
                lex_advance();
            } else if c == 10 {  // newline
                lex_line = lex_line + 1;
                lex_col = 0;
                lex_advance();
            } else if c == 47 {  // '/'
                if lex_peek_next() == 47 {  // '//' line comment
                    while !lex_is_at_end() && lex_peek() != 10 {
                        lex_advance();
                    }
                } else if lex_peek_next() == 42 {  // '/*' block comment
                    skip_block_comment();
                } else {
                    done = 1;
                }
            } else {
                done = 1;
            }
        }
    }
}

// ============================================================
// Keyword lookup
// ============================================================

// Dispatch by byte length before reading the prefix or keyword suffix.
func check_keyword() i64 {
    var len i64 = lex_current - lex_start;
    var text *u8 = lex_source + lex_start;
    if len == 2 {
        if *text == 102 {  // f
            if *(text + 1) == 110 { return TOKEN_FN; }  // fn
        }
        if *text == 105 {  // i
            if *(text + 1) == 102 { return TOKEN_IF; }  // if
            if *(text + 1) == 110 { return TOKEN_IN; }  // in
            if *(text + 1) == 56 { return TOKEN_I8; }  // i8
        }
        if *text == 117 {  // u
            if *(text + 1) == 56 { return TOKEN_U8; }  // u8
        }
    }
    if len == 3 {
        if *text == 102 {  // f
            if *(text + 1) == 51 && *(text + 2) == 50 { return TOKEN_F32; }  // f32
            if *(text + 1) == 54 && *(text + 2) == 52 { return TOKEN_F64; }  // f64
        }
        if *text == 105 {  // i
            if *(text + 1) == 49 && *(text + 2) == 54 { return TOKEN_I16; }  // i16
            if *(text + 1) == 51 && *(text + 2) == 50 { return TOKEN_I32; }  // i32
            if *(text + 1) == 54 && *(text + 2) == 52 { return TOKEN_I64; }  // i64
        }
        if *text == 108 {  // l
            if *(text + 1) == 101 && *(text + 2) == 116 { return TOKEN_LET; }  // let
        }
        if *text == 110 {  // n
            if *(text + 1) == 105 && *(text + 2) == 108 { return TOKEN_NIL; }  // nil
        }
        if *text == 112 {  // p
            if *(text + 1) == 117 && *(text + 2) == 98 { return TOKEN_PUB; }  // pub
        }
        if *text == 117 {  // u
            if *(text + 1) == 49 && *(text + 2) == 54 { return TOKEN_U16; }  // u16
            if *(text + 1) == 51 && *(text + 2) == 50 { return TOKEN_U32; }  // u32
            if *(text + 1) == 54 && *(text + 2) == 52 { return TOKEN_U64; }  // u64
        }
        if *text == 118 {  // v
            if *(text + 1) == 97 && *(text + 2) == 114 { return TOKEN_VAR; }  // var
        }
    }
    if len == 4 {
        if *text == 98 {  // b
            if *(text + 1) == 111 && *(text + 2) == 111 && *(text + 3) == 108 { return TOKEN_BOOL; }  // bool
        }
        if *text == 99 {  // c
            if *(text + 1) == 97 && *(text + 2) == 115 && *(text + 3) == 116 { return TOKEN_CAST; }  // cast
        }
        if *text == 101 {  // e
            if *(text + 1) == 108 && *(text + 2) == 115 && *(text + 3) == 101 { return TOKEN_ELSE; }  // else
            if *(text + 1) == 110 && *(text + 2) == 117 && *(text + 3) == 109 { return TOKEN_ENUM; }  // enum
        }
        if *text == 102 {  // f
            if *(text + 1) == 117 && *(text + 2) == 110 && *(text + 3) == 99 { return TOKEN_FUNC; }  // func
        }
        if *text == 116 {  // t
            if *(text + 1) == 114 && *(text + 2) == 117 && *(text + 3) == 101 { return TOKEN_TRUE; }  // true
        }
        if *text == 118 {  // v
            if *(text + 1) == 111 && *(text + 2) == 105 && *(text + 3) == 100 { return TOKEN_VOID; }  // void
        }
        if *text == 119 {  // w
            if *(text + 1) == 105 && *(text + 2) == 116 && *(text + 3) == 104 { return TOKEN_WITH; }  // with
        }
    }
    if len == 5 {
        if *text == 98 {  // b
            if *(text + 1) == 114 && *(text + 2) == 101 && *(text + 3) == 97 && *(text + 4) == 107 { return TOKEN_BREAK; }  // break
        }
        if *text == 102 {  // f
            if *(text + 1) == 97 && *(text + 2) == 108 && *(text + 3) == 115 && *(text + 4) == 101 { return TOKEN_FALSE; }  // false
        }
        if *text == 109 {  // m
            if *(text + 1) == 97 && *(text + 2) == 99 && *(text + 3) == 114 && *(text + 4) == 111 { return TOKEN_MACRO; }  // macro
            if *(text + 1) == 97 && *(text + 2) == 116 && *(text + 3) == 99 && *(text + 4) == 104 { return TOKEN_MATCH; }  // match
        }
        if *text == 119 {  // w
            if *(text + 1) == 104 && *(text + 2) == 105 && *(text + 3) == 108 && *(text + 4) == 101 { return TOKEN_WHILE; }  // while
        }
    }
    if len == 6 {
        if *text == 101 {  // e
            if *(text + 1) == 102 && *(text + 2) == 102 && *(text + 3) == 101 && *(text + 4) == 99 && *(text + 5) == 116 { return TOKEN_EFFECT; }  // effect
            if *(text + 1) == 120 && *(text + 2) == 116 && *(text + 3) == 101 && *(text + 4) == 114 && *(text + 5) == 110 { return TOKEN_EXTERN; }  // extern
        }
        if *text == 104 {  // h
            if *(text + 1) == 97 && *(text + 2) == 110 && *(text + 3) == 100 && *(text + 4) == 108 && *(text + 5) == 101 { return TOKEN_HANDLE; }  // handle
        }
        if *text == 105 {  // i
            if *(text + 1) == 109 && *(text + 2) == 112 && *(text + 3) == 111 && *(text + 4) == 114 && *(text + 5) == 116 { return TOKEN_IMPORT; }  // import
        }
        if *text == 114 {  // r
            if *(text + 1) == 101 && *(text + 2) == 97 && *(text + 3) == 100 && *(text + 4) == 101 && *(text + 5) == 114 { return TOKEN_READER; }  // reader
            if *(text + 1) == 101 && *(text + 2) == 116 && *(text + 3) == 117 && *(text + 4) == 114 && *(text + 5) == 110 { return TOKEN_RETURN; }  // return
            if *(text + 1) == 101 && *(text + 2) == 115 && *(text + 3) == 117 && *(text + 4) == 109 && *(text + 5) == 101 { return TOKEN_RESUME; }  // resume
        }
        if *text == 115 {  // s
            if *(text + 1) == 116 && *(text + 2) == 114 && *(text + 3) == 117 && *(text + 4) == 99 && *(text + 5) == 116 { return TOKEN_STRUCT; }  // struct
        }
    }
    if len == 7 {
        if *text == 98 {  // b
            if *(text + 1) == 105 && *(text + 2) == 116 && *(text + 3) == 99 && *(text + 4) == 97 && *(text + 5) == 115 && *(text + 6) == 116 { return TOKEN_BITCAST; }  // bitcast
        }
        if *text == 99 {  // c
            if *(text + 1) == 108 && *(text + 2) == 111 && *(text + 3) == 115 && *(text + 4) == 117 && *(text + 5) == 114 && *(text + 6) == 101 { return TOKEN_CLOSURE; }  // closure
        }
        if *text == 105 {  // i
            if *(text + 1) == 110 && *(text + 2) == 99 && *(text + 3) == 108 && *(text + 4) == 117 && *(text + 5) == 100 && *(text + 6) == 101 { return TOKEN_INCLUDE; }  // include
        }
        if *text == 112 {  // p
            if *(text + 1) == 101 && *(text + 2) == 114 && *(text + 3) == 102 && *(text + 4) == 111 && *(text + 5) == 114 && *(text + 6) == 109 { return TOKEN_PERFORM; }  // perform
        }
        if *text == 114 {  // r
            if *(text + 1) == 101 && *(text + 2) == 113 && *(text + 3) == 117 && *(text + 4) == 105 && *(text + 5) == 114 && *(text + 6) == 101 { return TOKEN_REQUIRE; }  // require
        }
    }
    if len == 8 {
        if *text == 99 {  // c
            if *(text + 1) == 111 && *(text + 2) == 110 && *(text + 3) == 116 && *(text + 4) == 105 && *(text + 5) == 110 && *(text + 6) == 117 && *(text + 7) == 101 { return TOKEN_CONTINUE; }  // continue
        }
    }
    return TOKEN_IDENT;
}

// ============================================================
// Scan specific token types
// ============================================================

func scan_identifier() *u8 {
    while is_alphanumeric(lex_peek()) {
        lex_advance();
    }
    return make_token(check_keyword());
}

func scan_number() *u8 {
    while is_digit(lex_peek()) {
        lex_advance();
    }

    // Check for decimal point (float literal)
    // Only if followed by a digit (not method call like 1.to_string())
    if lex_peek() == 46 {  // '.'
        if is_digit(lex_peek_next()) {
            lex_advance();  // consume '.'
            while is_digit(lex_peek()) {
                lex_advance();
            }
            return make_token(TOKEN_FLOAT);
        }
    }

    return make_token(TOKEN_NUMBER);
}

func scan_string() *u8 {
    while !lex_is_at_end() && lex_peek() != 34 {  // '"'
        if lex_peek() == 10 {  // newline
            lex_line = lex_line + 1;
            lex_col = 0;
        }
        if lex_peek() == 92 && lex_peek_next() != 0 {  // backslash escape
            lex_advance();  // consume backslash
        }
        lex_advance();
    }

    if lex_is_at_end() {
        return error_token("unterminated string");
    }

    lex_advance();  // closing quote
    return make_token(TOKEN_STRING);
}

// Scan character literal: 'A' or '\n'
// Returns TOKEN_NUMBER with the character value as lexeme
func scan_char() *u8 {
    // We've already consumed opening quote
    if lex_is_at_end() {
        return error_token("unterminated character literal");
    }

    var c u8 = lex_advance();
    var value i64 = 0;

    if c == 92 {  // backslash - escape sequence
        if lex_is_at_end() {
            return error_token("unterminated escape in character literal");
        }
        var esc u8 = lex_advance();
        if esc == 110 { value = 10; }       // \n -> newline
        else if esc == 116 { value = 9; }   // \t -> tab
        else if esc == 114 { value = 13; }  // \r -> carriage return
        else if esc == 48 { value = 0; }    // \0 -> null
        else if esc == 92 { value = 92; }   // \\ -> backslash
        else if esc == 39 { value = 39; }   // \' -> single quote
        else if esc == 34 { value = 34; }   // \" -> double quote
        else {
            return error_token("unknown escape sequence");
        }
    } else {
        value = c;
    }

    // Expect closing quote
    if lex_is_at_end() || lex_peek() != 39 {
        return error_token("unterminated character literal");
    }
    lex_advance();  // consume closing quote

    // Convert value to string and create NUMBER token
    var buf *u8 = alloc(16);
    var len i64 = itoa(value, buf);

    var tok *u8 = tok_alloc();
    tok_set_type(tok, TOKEN_NUMBER);
    tok_set_lexeme(tok, buf);
    tok_set_lexeme_len(tok, len);
    tok_set_line(tok, lex_line);
    tok_set_col(tok, lex_start_col);
    return tok;
}

// Scan reader macro: #name{content}
// Returns token with:
//   - lexeme = reader name
//   - content = text between balanced braces, or exactly N bytes in #name[N]{...}
func reader_character_width() i64 {
    // A quoted identifier is a complete single-quoted token as well. Keep its
    // closing quote from being mistaken for the start of a character literal.
    var end i64 = lex_current + 1;
    while end < lex_source_len && is_alphanumeric(*(lex_source + end)) { end = end + 1; }
    if end > lex_current + 1 && end < lex_source_len && *(lex_source + end) == 39 {
        return end - lex_current + 1;
    }
    // A lone quote belongs to the reader.
    if lex_current + 2 < lex_source_len &&
       *(lex_source + lex_current + 2) == 39 && lex_peek_next() != 92 { return 3; }
    if lex_peek_next() == 92 && lex_current + 3 < lex_source_len &&
       *(lex_source + lex_current + 3) == 39 { return 4; }
    return 1;
}

func scan_reader_macro() *u8 {
    // We've already consumed '#', now read the name
    var name_start i64 = lex_current;

    // Read identifier (the reader macro name)
    if !is_alpha(lex_peek()) {
        return error_token("expected identifier after '#'");
    }
    while is_alphanumeric(lex_peek()) {
        lex_advance();
    }
    var name_end i64 = lex_current;
    var name_len i64 = name_end - name_start;

    // A byte-counted body transports foreign source without interpreting its
    // comments, quotes or delimiters. Bound decimal accumulation by input size.
    var content_size i64 = -1;
    var digit i64 = 0;
    if lex_peek() == 91 {  // '['
        lex_advance();
        if !is_digit(lex_peek()) { return error_token("expected reader byte count"); }
        content_size = 0;
        while is_digit(lex_peek()) {
            digit = lex_peek() - 48;
            if content_size > (lex_source_len - digit) / 10 {
                return error_token("reader byte count exceeds input");
            }
            content_size = content_size * 10 + digit;
            lex_advance();
        }
        if lex_peek() != 93 { return error_token("expected ']' after reader byte count"); }
        lex_advance();
    }

    // Expect '{'
    if lex_peek() != 123 {  // '{'
        return error_token("expected '{' after reader macro name");
    }
    lex_advance();  // consume '{'

    // Read balanced content
    var reader_start_line i64 = lex_line;
    var content_start i64 = lex_current;
    var brace_depth i64 = 1;
    // Keep loop storage in the entry block for large source packages, including
    // compilers linked without aggressive alloca promotion.
    var c u8 = 0;
    var width i64 = 0;

    if content_size >= 0 {
        if content_size >= lex_source_len - lex_current {
            return error_token("reader byte count exceeds input");
        }
        while lex_current - content_start < content_size {
            if lex_peek() == 10 { lex_line = lex_line + 1; lex_col = 0; }
            lex_advance();
        }
        if lex_peek() != 125 { return error_token("expected '}' after counted reader body"); }
        brace_depth = 0;
    }

    // Short-circuit expressions can also allocate temporaries at their use
    // site. Keep them out of this byte loop so unoptimized scans stay bounded.
    while !lex_is_at_end() {
        if brace_depth == 0 { break; }
        c = lex_peek();

        // Slash bytes belong to the reader, including URLs and comment-like
        // text. Only the explicit counted form bypasses brace balancing.
        if c == 39 {
            width = reader_character_width();
            while width > 0 { lex_advance(); width = width - 1; }
        } else if c == 123 {  // '{'
            brace_depth = brace_depth + 1;
            lex_advance();
        } else if c == 125 {  // '}'
            brace_depth = brace_depth - 1;
            if brace_depth > 0 {
                lex_advance();
            }
        } else if c == 34 {  // '"' - skip strings to not count braces inside
            lex_advance();  // consume opening quote
            while !lex_is_at_end() {
                if lex_peek() == 34 { break; }
                if lex_peek() == 92 {  // escape
                    if lex_peek_next() != 0 { lex_advance(); }
                }
                if lex_peek() == 10 {
                    lex_line = lex_line + 1;
                    lex_col = 0;
                }
                lex_advance();
            }
            if !lex_is_at_end() {
                lex_advance();  // consume closing quote
            }
        } else if c == 10 {  // newline
            lex_line = lex_line + 1;
            lex_col = 0;
            lex_advance();
        } else {
            lex_advance();
        }
    }

    if brace_depth != 0 {
        return error_token("unterminated reader macro content");
    }

    var content_end i64 = lex_current;
    lex_advance();  // consume closing '}'

    // Create token
    var tok *u8 = tok_alloc();
    tok_set_type(tok, TOKEN_READER_MACRO);
    tok_set_lexeme(tok, lex_source + name_start);
    tok_set_lexeme_len(tok, name_len);
    tok_set_line(tok, reader_start_line);
    tok_set_col(tok, lex_start_col);
    tok_set_content(tok, lex_source + content_start);
    tok_set_content_len(tok, content_end - content_start);

    return tok;
}

// ============================================================
// Main scan function
// ============================================================

pub func scan_token() *u8 {
    skip_whitespace();
    lex_start = lex_current;
    lex_start_col = lex_col;

    if lex_is_at_end() {
        return make_token(TOKEN_EOF);
    }

    var c u8 = lex_advance();

    if is_alpha(c) {
        return scan_identifier();
    }
    if is_digit(c) {
        return scan_number();
    }

    // Single-char tokens
    if c == 40 { return make_token(TOKEN_LPAREN); }    // '('
    if c == 41 { return make_token(TOKEN_RPAREN); }    // ')'
    if c == 123 { return make_token(TOKEN_LBRACE); }   // '{'
    if c == 125 { return make_token(TOKEN_RBRACE); }   // '}'
    if c == 91 { return make_token(TOKEN_LBRACKET); }  // '['
    if c == 93 { return make_token(TOKEN_RBRACKET); }  // ']'
    if c == 44 { return make_token(TOKEN_COMMA); }     // ','
    if c == 59 { return make_token(TOKEN_SEMICOLON); } // ';'
    if c == 46 { return make_token(TOKEN_DOT); }       // '.'
    if c == 43 {  // '+'
        if lex_match(61) { return make_token(TOKEN_PLUSEQ); }  // '+='
        return make_token(TOKEN_PLUS);
    }
    if c == 45 {  // '-'
        if lex_match(61) { return make_token(TOKEN_MINUSEQ); }  // '-='
        return make_token(TOKEN_MINUS);
    }
    if c == 42 {  // '*'
        if lex_match(61) { return make_token(TOKEN_STAREQ); }  // '*='
        return make_token(TOKEN_STAR);
    }
    if c == 47 {  // '/'
        if lex_match(61) { return make_token(TOKEN_SLASHEQ); }  // '/='
        return make_token(TOKEN_SLASH);
    }
    if c == 37 {  // '%'
        if lex_match(61) { return make_token(TOKEN_PERCENTEQ); }  // '%='
        return make_token(TOKEN_PERCENT);
    }

    // Two-char tokens
    if c == 38 {  // '&'
        if lex_match(38) { return make_token(TOKEN_AMPAMP); }  // '&&'
        return make_token(TOKEN_AMP);
    }
    if c == 124 {  // '|'
        if lex_match(124) { return make_token(TOKEN_PIPEPIPE); }  // '||'
        return make_token(TOKEN_PIPE);  // bitwise or
    }
    if c == 94 {  // '^'
        return make_token(TOKEN_CARET);  // bitwise xor
    }
    if c == 33 {  // '!'
        if lex_match(61) { return make_token(TOKEN_BANGEQ); }  // '!='
        return make_token(TOKEN_BANG);
    }
    if c == 61 {  // '='
        if lex_match(62) { return make_token(TOKEN_ARROW); }  // '=>'
        if lex_match(61) { return make_token(TOKEN_EQEQ); }  // '=='
        return make_token(TOKEN_EQ);
    }
    if c == 60 {  // '<'
        if lex_match(60) { return make_token(TOKEN_LTLT); }   // '<<'
        if lex_match(61) { return make_token(TOKEN_LTEQ); }   // '<='
        return make_token(TOKEN_LT);
    }
    if c == 62 {  // '>'
        if lex_match(62) { return make_token(TOKEN_GTGT); }   // '>>'
        if lex_match(61) { return make_token(TOKEN_GTEQ); }   // '>='
        return make_token(TOKEN_GT);
    }
    if c == 58 {  // ':'
        if lex_match(61) { return make_token(TOKEN_COLONEQ); }  // ':='
        return make_token(TOKEN_COLON);
    }
    if c == 36 {  // '$'
        if lex_match(123) { return make_token(TOKEN_DOLLAR_LBRACE); }  // '${'
        if lex_match(64) { return make_token(TOKEN_DOLLAR_AT); }       // '$@'
        return make_token(TOKEN_DOLLAR);
    }
    if c == 35 {  // '#' - reader macro
        return scan_reader_macro();
    }
    if c == 34 {  // '"'
        return scan_string();
    }
    if c == 39 {  // '\''
        return scan_char();
    }

    return error_token("unexpected character");
}

