    print(" '");
    print_n(tok_lexeme(tok), tok_lexeme_len(tok));
    println("'");
}

src/node_origin_host.lang:
// A native compiler may lazily attach origins to nodes received from a reader.
var node_origin_missing fn(*u8) void = nil;

func node_origin_resolve_missing(node *u8) i64 {
    if node == nil || node_origin_missing == nil { return -1; }
    node_origin_missing(node);
    return phase_node_index_find(node);
}

src/numeric_types.lang:
// Widths of the exact core numeric types.
func numeric_bits(name *u8) i64 {
    if streq(name, "i8") || streq(name, "u8") { return 8; }
    if streq(name, "i16") || streq(name, "u16") { return 16; }
    if streq(name, "i32") || streq(name, "u32") || streq(name, "f32") { return 32; }
    if streq(name, "i64") || streq(name, "u64") || streq(name, "f64") { return 64; }
    return 0;
}

