// Strip surrounding quotes from a string literal and process escape sequences
// Input: "hello\nworld" (with quotes, 14 chars)
// Output: hello<newline>world (raw, 11 chars)
func parse_string_literal(quoted *u8, quoted_len i64) *u8 {
    var buf *u8 = alloc(quoted_len + 1);
    var out i64 = 0;
    var i i64 = 1;  // Skip opening quote

    while i < quoted_len - 1 {  // Stop before closing quote
        var c u8 = *(quoted + i);
        if c == '\\' && i + 1 < quoted_len - 1 {
            var next u8 = *(quoted + i + 1);
            if next == 'n' { *(buf + out) = '\n'; out = out + 1; i = i + 2; }
            else if next == 't' { *(buf + out) = '\t'; out = out + 1; i = i + 2; }
            else if next == 'r' { *(buf + out) = '\r'; out = out + 1; i = i + 2; }
            else if next == '0' { *(buf + out) = 0; out = out + 1; i = i + 2; }
            else if next == '"' { *(buf + out) = '"'; out = out + 1; i = i + 2; }
            else if next == '\\' { *(buf + out) = '\\'; out = out + 1; i = i + 2; }
            else { *(buf + out) = c; out = out + 1; i = i + 1; }
        } else {
            *(buf + out) = c;
            out = out + 1;
            i = i + 1;
        }
    }
    *(buf + out) = 0;
    return buf;
}

func parse_string_literal_len(quoted *u8, quoted_len i64) i64 {
    // Calculate length of processed string
    var out i64 = 0;
    var i i64 = 1;  // Skip opening quote

    while i < quoted_len - 1 {  // Stop before closing quote
        var c u8 = *(quoted + i);
        if c == '\\' && i + 1 < quoted_len - 1 {
            var next u8 = *(quoted + i + 1);
            if next == 'n' || next == 't' || next == 'r' || next == '0' || next == '"' || next == '\\' {
                out = out + 1;
                i = i + 2;
            } else {
                out = out + 1;
                i = i + 1;
            }
        } else {
            out = out + 1;
            i = i + 1;
        }
    }
    return out;
}

