// The Lang frontend owns the relation between an inline reader's invocation
// origin and its content slice. Backends consume this offset without knowing
// the host syntax. CLI custom-source invocations already index the whole file.
pub func reader_expr_source_start(node *u8) i64 {
    var origin *PhaseOrigin = phase_origin_get(node_origin_id(node));
    if origin == nil { return 0 - 1; }
    var source *PhaseSource = phase_source_get(origin.source);
    var start i64 = origin.start;
    // Current inline-reader origins cover the content itself. Verify the bytes
    // before treating the offset as a slice of the containing source.
    var content *u8 = reader_expr_content(node);
    var len i64 = reader_expr_content_len(node);
    if start <= source.len && len <= source.len - start && origin.end == start + len {
        var i i64 = 0;
        while i < len && *(source.text + start + i) == *(content + i) { i = i + 1; }
        if i == len { return start; }
    }
    if start >= source.len || *(source.text + start) != '#' { return 0 - 1; }
    while start < source.len && *(source.text + start) != '{' { start = start + 1; }
    if start >= source.len { return 0 - 1; }
    return start + 1;
}

