// ============================================================

var parse_tokens *u8 = nil;      // vec of token pointers
var parse_current i64 = 0;
pub var parse_error_count i64 = 0;  // v2
var parse_source_name *u8 = nil;
var parse_max_errors i64 = 10;   // Stop after this many errors

// Source provenance stays out of the stable AST layout. This side table lets
// parsed and reader-generated declarations carry useful diagnostic context
// without changing the S-expression ABI or every AST node allocation.
// Entry: [node:8][source_name:8][line:8][column:8][start:8][end:8]
// start/end are byte offsets into reader source, or -1 for ordinary Lang nodes.
var node_origins *u8 = nil;
var node_origin_count i64 = 0;
var node_origin_capacity i64 = 0;

func node_set_origin_full(node *u8, source_name *u8, line i64, column i64,
                          start i64, end i64) void {
    if node == nil || source_name == nil || *source_name == 0 {
        return;
    }
    if node_origin_count >= phase_node_limit() { phase_node_error("origin-budget", source_name); }
    if node_origin_count >= node_origin_capacity {
        var capacity i64 = node_origin_capacity * 2;
        if capacity == 0 { capacity = 256; }
        if capacity > phase_node_limit() { capacity = phase_node_limit(); }
        phase_charge(capacity * 56);
        var storage *u8 = alloc(capacity * 56);
        if node_origin_count > 0 { memcpy(storage, node_origins, node_origin_count * 56); }
        node_origins = storage; node_origin_capacity = capacity;
    }
    var entry *u8 = node_origins + (node_origin_count * 56);
    var node_slot **u8 = entry;
    *node_slot = node;
    var source_slot **u8 = entry + 8;
    *source_slot = source_name;
    var line_slot *i64 = entry + 16;
    *line_slot = line;
    var column_slot *i64 = entry + 24;
    *column_slot = column;
    var start_slot *i64 = entry + 32;
    *start_slot = start;
    var end_slot *i64 = entry + 40;
    *end_slot = end;
    var source_id i64 = phase_origin_source_id(source_name);
    if source_id == 0 { phase_error("missing-source", source_name); }
    var source_record *PhaseSource = phase_source_get(source_id);
    var byte_start i64 = start;
    var byte_end i64 = end;
    if byte_start < 0 {
        byte_start = phase_line_byte(source_record, line, column);
        byte_end = byte_start;
    }
    var origin_slot *i64 = entry + 48;
    *origin_slot = phase_origin_new(source_id, byte_start, byte_end, phase_include_origin, phase_expansion_origin);
    phase_node_index_set(node, node_origin_count);
    node_origin_count = node_origin_count + 1;
}

pub func node_set_origin(node *u8, source_name *u8, line i64, column i64) void {
    node_set_origin_full(node, source_name, line, column, -1, -1);
}

// Attach a reader-relative byte span and derive its one-based line/column.
pub func node_set_span(node *u8, source_name *u8, source *u8,
                       start i64, end i64) void {
    if source == nil || phase_span_valid(phase_origin_source_id(source_name), start, end) == 0 {
        phase_error("invalid-span", source_name);
    }

    // The immutable source already indexes line starts. Rescanning its prefix
    // for every reader span makes a flat program quadratic in source length.
    var record *PhaseSource = phase_source_get(phase_origin_source_id(source_name));
    var low i64 = 0;
    var high i64 = record.line_count;
    while low + 1 < high {
        var mid i64 = low + (high - low) / 2;
        if phase_word(record.lines, mid) <= start { low = mid; }
        else { high = mid; }
    }
    node_set_origin_full(node, source_name, low + 1,
                         start - phase_word(record.lines, low) + 1, start, end);
}

func node_origin_entry(node *u8) *u8 {
    var index i64 = phase_node_index_find(node);
    if index < 0 { index = node_origin_resolve_missing(node); }
    if index < 0 { return nil; }
    return node_origins + index * 56;
}

pub func node_origin_source(node *u8) *u8 {
    var entry *u8 = node_origin_entry(node);
    if entry == nil { return nil; }
    var source_slot **u8 = entry + 8;
    return *source_slot;
}

pub func node_origin_line(node *u8) i64 {
    var entry *u8 = node_origin_entry(node);
    if entry == nil { return 0; }
    var line_slot *i64 = entry + 16;
    return *line_slot;
}

pub func node_origin_column(node *u8) i64 {
    var entry *u8 = node_origin_entry(node);
    if entry == nil { return 0; }
