// std/core.lang - Standard library for language
// Provides basic I/O, memory allocation, and string operations

include "src/limits.lang"
include "std/os.lang"
include "std/tools.lang"

// ============================================================
// Memory
// ============================================================
// alloc() is now provided by the OS layer (std/os/*.lang)
// - linux_x86_64: mmap-based bump allocator with Linux flags
// - macos_arm64: mmap-based bump allocator with macOS flags
// - libc: delegates to libc malloc()

// A streaming reader can reclaim recognizer temporaries after lowering one
// production. Pause the scope before allocating any values that must escape.
struct ReaderScratchPage { next *ReaderScratchPage; data *u8; capacity i64; }
var reader_scratch_active i64 = 0;
var reader_scratch_head *ReaderScratchPage = nil;
var reader_scratch_page *ReaderScratchPage = nil;
var reader_scratch_used i64 = 0;
var reader_scratch_capacity i64 = 0;

pub func reader_scratch_begin() void {
    reader_scratch_active = 1;
    reader_scratch_page = nil;
    reader_scratch_used = 0;
}

pub func reader_scratch_end() void { reader_scratch_active = 0; }

pub func reader_scratch_alloc(size i64) *u8 {
    var aligned i64 = ((size + 7) / 8) * 8;
    if reader_scratch_page != nil {
        if aligned <= reader_scratch_page.capacity - reader_scratch_used {
            var result *u8 = reader_scratch_page.data + reader_scratch_used;
            reader_scratch_used = reader_scratch_used + aligned;
            return result;
        }
    }
    var next *ReaderScratchPage = reader_scratch_head;
    if reader_scratch_page != nil { next = reader_scratch_page.next; }
    while next != nil {
        if next.capacity >= aligned { break; }
        next = next.next;
    }
    if next == nil {
        var capacity i64 = 65536;
        if aligned > capacity { capacity = aligned; }
        if capacity > 268435456 - reader_scratch_capacity {
            eprintln("Error: reader scratch memory limit exceeded");
            exit(1);
        }
        reader_scratch_capacity = reader_scratch_capacity + capacity;
        next = alloc(24);
        if next == nil { eprintln("Error: reader scratch allocation failed"); exit(1); }
        next.data = alloc(capacity);
        if next.data == nil { eprintln("Error: reader scratch allocation failed"); exit(1); }
        next.capacity = capacity;
        if reader_scratch_page == nil {
            next.next = reader_scratch_head;
            reader_scratch_head = next;
        } else {
            next.next = reader_scratch_page.next;
            reader_scratch_page.next = next;
        }
    }
    reader_scratch_page = next;
    reader_scratch_used = aligned;
    return next.data;
}

// ============================================================
// Dynamic Array (Vec)
// ============================================================
// Vec layout: [capacity:8][length:8][data:8] = 24 bytes
// Data array stores i64 values (8 bytes each)

pub func vec_new(cap i64) *u8 {
    var v *u8 = nil;
    if reader_scratch_active != 0 { v = reader_scratch_alloc(24); }
    else { v = malloc(24); }

    // Initialize capacity
    if cap < 4 {
        cap = 4;
    }
    var cap_ptr *i64 = v;
    *cap_ptr = cap;

    // Initialize length to 0
    var len_ptr *i64 = v + 8;
    *len_ptr = 0;

    // Allocate initial data array
    var data_ptr **u8 = v + 16;
    if reader_scratch_active != 0 { *data_ptr = reader_scratch_alloc(cap * 8); }
    else { *data_ptr = malloc(cap * 8); }

    return v;
}

pub func vec_len(v *u8) i64 {
    var len_ptr *i64 = v + 8;
    return *len_ptr;
}

pub func vec_get(v *u8, index i64) i64 {
    var data_ptr **u8 = v + 16;
    var data *u8 = *data_ptr;
    var elem_ptr *i64 = data + index * 8;
    return *elem_ptr;
}

pub func vec_set(v *u8, index i64, value i64) {
    var data_ptr **u8 = v + 16;
    var data *u8 = *data_ptr;
    var elem_ptr *i64 = data + index * 8;
    *elem_ptr = value;
}

pub func vec_push(v *u8, value i64) {
    var cap_ptr *i64 = v;
    var len_ptr *i64 = v + 8;
    var data_ptr **u8 = v + 16;

    var cap i64 = *cap_ptr;
    var len i64 = *len_ptr;
    var data *u8 = *data_ptr;

    // Check if we need to grow
    if len >= cap {
        // Double capacity
        var new_cap i64 = cap * 2;
        var new_data *u8 = nil;
        if reader_scratch_active != 0 { new_data = reader_scratch_alloc(new_cap * 8); }
        else { new_data = malloc(new_cap * 8); }

        // Copy old data
        var i i64 = 0;
        var old_ptr *i64 = nil;
        var new_ptr *i64 = nil;
        while i < len {
            old_ptr = data + i * 8;
            new_ptr = new_data + i * 8;
            *new_ptr = *old_ptr;
            i = i + 1;
        }

        // Free old data and update vec
        if reader_scratch_active == 0 { free(data); }
        *cap_ptr = new_cap;
        *data_ptr = new_data;
        data = new_data;
    }

    // Add element
    var elem_ptr *i64 = data + len * 8;
    *elem_ptr = value;
    *len_ptr = len + 1;
}

pub func vec_free(v *u8) {
    var data_ptr **u8 = v + 16;
    var data *u8 = *data_ptr;
    free(data);
    free(v);
}

pub func vec_pop(v *u8) i64 {
    var len_ptr *i64 = v + 8;
    var data_ptr **u8 = v + 16;
    var len i64 = *len_ptr;
    if len == 0 {
        return 0;  // Empty vector
    }
    len = len - 1;
    *len_ptr = len;
    var data *u8 = *data_ptr;
    var elem_ptr *i64 = data + len * 8;
    return *elem_ptr;
}

// ============================================================
// Hash Map (string keys -> i64 values)
// ============================================================
// Map layout: [capacity:8][count:8][keys:8][values:8] = 32 bytes
// keys: array of *u8 (nil = empty slot)
// values: array of i64
// Uses open addressing with linear probing

pub func hash_str(s *u8) i64 {
    // djb2 hash
    var h i64 = 5381;
    while *s != 0 {
        h = h * 33 + *s;
        s = s + 1;
    }
    // Make positive
    if h < 0 {
        h = 0 - h;
    }
    return h;
}

pub func map_new() *u8 {
    var m *u8 = malloc(32);

    // Initial capacity 16
    var cap_ptr *i64 = m;
    *cap_ptr = 16;

    // Count 0
    var count_ptr *i64 = m + 8;
    *count_ptr = 0;

    // Allocate keys array (16 * 8 = 128 bytes)
    var keys_ptr **u8 = m + 16;
    var keys *u8 = malloc(128);
    *keys_ptr = keys;

    // Initialize keys to nil
    var i i64 = 0;
    while i < 16 {
        var slot **u8 = keys + i * 8;
        *slot = nil;
        i = i + 1;
    }

    // Allocate values array (16 * 8 = 128 bytes)
    var vals_ptr **u8 = m + 24;
    *vals_ptr = malloc(128);

    return m;
}

func map_find_slot(m *u8, key *u8) i64 {
    // Returns index where key is or should be inserted
    var cap_ptr *i64 = m;
    var cap i64 = *cap_ptr;
    var keys_ptr **u8 = m + 16;
    var keys *u8 = *keys_ptr;

    var h i64 = hash_str(key) % cap;
    var i i64 = 0;

    while i < cap {
        var idx i64 = (h + i) % cap;
        var slot **u8 = keys + idx * 8;
        var slot_key *u8 = *slot;

        if slot_key == nil {
            return idx;
        }
        if streq(slot_key, key) {
            return idx;
        }
        i = i + 1;
    }

    // Should never reach here if load factor < 1
    return 0 - 1;
}

func map_grow(m *u8) {
    var cap_ptr *i64 = m;
    var count_ptr *i64 = m + 8;
    var keys_ptr **u8 = m + 16;
    var vals_ptr **u8 = m + 24;

    var old_cap i64 = *cap_ptr;
    var old_keys *u8 = *keys_ptr;
    var old_vals *u8 = *vals_ptr;

    // Double capacity
    var new_cap i64 = old_cap * 2;
    *cap_ptr = new_cap;
    *count_ptr = 0;

    // Allocate new arrays
    var new_keys *u8 = malloc(new_cap * 8);
    var new_vals *u8 = malloc(new_cap * 8);

    // Initialize new keys to nil
    var i i64 = 0;
    while i < new_cap {
        var slot **u8 = new_keys + i * 8;
        *slot = nil;
        i = i + 1;
    }

    *keys_ptr = new_keys;
    *vals_ptr = new_vals;

    // Rehash old entries
    i = 0;
    while i < old_cap {
        var old_slot **u8 = old_keys + i * 8;
        var old_key *u8 = *old_slot;

        if old_key != nil {
            var old_val_ptr *i64 = old_vals + i * 8;
            var old_val i64 = *old_val_ptr;

            // Insert into new table
            var idx i64 = map_find_slot(m, old_key);
            var new_slot **u8 = new_keys + idx * 8;
            *new_slot = old_key;
            var new_val_ptr *i64 = new_vals + idx * 8;
            *new_val_ptr = old_val;

            var count i64 = *count_ptr;
            *count_ptr = count + 1;
        }
        i = i + 1;
    }

    free(old_keys);
    free(old_vals);
}

pub func map_set(m *u8, key *u8, value i64) {
    var cap_ptr *i64 = m;
    var count_ptr *i64 = m + 8;
    var keys_ptr **u8 = m + 16;
    var vals_ptr **u8 = m + 24;

    var cap i64 = *cap_ptr;
    var count i64 = *count_ptr;

    // Check load factor (> 0.75 = count * 4 > cap * 3)
    if count * 4 > cap * 3 {
        map_grow(m);
    }

    var keys *u8 = *keys_ptr;
    var vals *u8 = *vals_ptr;

    var idx i64 = map_find_slot(m, key);
    var slot **u8 = keys + idx * 8;
    var slot_key *u8 = *slot;

    // Set key if new slot
    if slot_key == nil {
        *slot = key;
        count = *count_ptr;
        *count_ptr = count + 1;
    }

    // Set value
    var val_ptr *i64 = vals + idx * 8;
    *val_ptr = value;
}

pub func map_get(m *u8, key *u8) i64 {
    var keys_ptr **u8 = m + 16;
    var vals_ptr **u8 = m + 24;
    var keys *u8 = *keys_ptr;
    var vals *u8 = *vals_ptr;

    var idx i64 = map_find_slot(m, key);
    var slot **u8 = keys + idx * 8;
    var slot_key *u8 = *slot;

    if slot_key == nil {
        return 0;  // Not found, return 0
    }

    var val_ptr *i64 = vals + idx * 8;
    return *val_ptr;
}

pub func map_has(m *u8, key *u8) i64 {
    var keys_ptr **u8 = m + 16;
    var keys *u8 = *keys_ptr;

    var idx i64 = map_find_slot(m, key);
    var slot **u8 = keys + idx * 8;
    var slot_key *u8 = *slot;

    if slot_key == nil {
        return 0;
    }
    return 1;
}

pub func map_free(m *u8) {
    var keys_ptr **u8 = m + 16;
    var vals_ptr **u8 = m + 24;
    free(*keys_ptr);
    free(*vals_ptr);
    free(m);
}

pub func map_size(m *u8) i64 {
    var count_ptr *i64 = m + 8;
    return *count_ptr;
}

// Return a Vec of all non-nil keys
pub func map_keys(m *u8) *u8 {
    var cap_ptr *i64 = m;
    var cap i64 = *cap_ptr;
    var keys_ptr **u8 = m + 16;
    var keys *u8 = *keys_ptr;

    var result *u8 = vec_new(16);
    var i i64 = 0;
    while i < cap {
        var slot **u8 = keys + i * 8;
        var key *u8 = *slot;
        if key != nil {
            vec_push(result, key);
        }
        i = i + 1;
    }
    return result;
}

// Make a null-terminated copy of a string with explicit length
pub func str_dup_n(s *u8, len i64) *u8 {
    var result *u8 = malloc(len + 1);
    var i i64 = 0;
    while i < len {
        *(result + i) = *(s + i);
        i = i + 1;
    }
    *(result + len) = 0;
    return result;
}

// Map set/get with length-prefixed keys (creates null-terminated copy)
pub func map_set_n(m *u8, key *u8, key_len i64, value i64) void {
    var key_copy *u8 = str_dup_n(key, key_len);
    map_set(m, key_copy, value);
}

pub func map_get_n(m *u8, key *u8, key_len i64) i64 {
    var key_copy *u8 = str_dup_n(key, key_len);
    var result i64 = map_get(m, key_copy);
    free(key_copy);
    return result;
}

