// ============================================================
// Strings
// ============================================================

pub func strlen(s *u8) i64 {
    var n i64 = 0;
    while *(s + n) != 0 {
        n = n + 1;
    }
    return n;
}

// Match the C ABI because LLVM can lower copy loops to this symbol.
pub func memcpy(dst *u8, src *u8, n i64) *u8 {
    var i i64 = 0;
    while i < n {
        *(dst + i) = *(src + i);
        i = i + 1;
    }
    return dst;
}

pub func streq(a *u8, b *u8) i64 {
    // Avoid per-iteration short-circuit storage when comparing source snapshots
    // in a compiler linked without aggressive stack-allocation promotion.
    while *a != 0 {
        if *a != *b {
            return 0;
        }
        a = a + 1;
        b = b + 1;
    }
    if *a == *b {
        return 1;
    }
    return 0;
}

// Compare two strings with explicit lengths
pub func str_eq_n(a *u8, a_len i64, b *u8, b_len i64) bool {
    if a_len != b_len {
        return false;
    }
    var i i64 = 0;
    while i < a_len {
        if *(a + i) != *(b + i) {
            return false;
        }
        i = i + 1;
    }
    return true;
}

pub func str_concat(a *u8, b *u8) *u8 {
    var len_a i64 = strlen(a);
    var len_b i64 = strlen(b);
    var result *u8 = malloc(len_a + len_b + 1);

    // Copy a
    var i i64 = 0;
    while i < len_a {
        *(result + i) = *(a + i);
        i = i + 1;
    }

    // Copy b
    var j i64 = 0;
    while j < len_b {
        *(result + len_a + j) = *(b + j);
        j = j + 1;
    }

    // Null terminate
    *(result + len_a + len_b) = 0;

    return result;
}

pub func str_dup(s *u8) *u8 {
    var len i64 = strlen(s);
    var result *u8 = malloc(len + 1);
    var i i64 = 0;
    while i <= len {
        *(result + i) = *(s + i);
        i = i + 1;
    }
    return result;
}

pub func str_starts_with(s *u8, prefix *u8) i64 {
    while *prefix != 0 {
        if *s != *prefix { return 0; }
        s = s + 1;
        prefix = prefix + 1;
    }
    return 1;
}

