pub func eprint_i64(n i64) {
    if n < 0 {
        ___compiler_stderr_write("-", 1, 0);
        n = 0 - n;
    }

    if n == 0 {
        ___compiler_stderr_write("0", 1, 0);
        return;
    }

    // Find the highest power of 10
    var divisor i64 = 1;
    var temp i64 = n;
    while temp >= 10 {
        temp = temp / 10;
        divisor = divisor * 10;
    }

    // Print each digit
    while divisor > 0 {
        var digit i64 = n / divisor;
        var c u8 = 48 + digit;  // '0' = 48
        ___compiler_stderr_write(&c, 1, 0);
        n = n % divisor;
        divisor = divisor / 10;
    }
}

