// ============================================================
// Numeric helpers (useful for debugging)
// ============================================================

pub func print_digit(d i64) {
    var c u8 = 48 + d;  // '0' = 48
    file_write(1, &c, 1);
}

pub func print_int(n i64) {
    // Its positive magnitude is not representable as an i64.
    if n == (0 - 9223372036854775807 - 1) {
        file_write(1, "-9223372036854775808", 20);
        return;
    }

    if n < 0 {
        file_write(1, "-", 1);
        n = 0 - n;
    }

    if n == 0 {
        file_write(1, "0", 1);
        return;
    }

    // Find the highest power of 10
    var divisor i64 = 1;
    var temp i64 = n;
    while temp >= 10 {
        temp = temp / 10;
        divisor = divisor * 10;
    }

    // Print each digit
    while divisor > 0 {
        var digit i64 = n / divisor;
        print_digit(digit);
        n = n % divisor;
        divisor = divisor / 10;
    }
}

// Print f64 to stdout (LLVM backend only)
pub func print_f64(val f64) void {
    printf("%f\n", val);
}

// Convert integer to string, write to buffer, return length
pub func itoa(n i64, buf *u8) i64 {
    // Its positive magnitude is not representable as an i64.
    if n == (0 - 9223372036854775807 - 1) {
        var min_text *u8 = "-9223372036854775808";
        var i i64 = 0;
        while i < 20 {
            *(buf + i) = *(min_text + i);
            i = i + 1;
        }
        return 20;
    }

    var pos i64 = 0;

    if n < 0 {
        *(buf + pos) = 45;  // '-'
        pos = pos + 1;
        n = 0 - n;
    }

    if n == 0 {
        *(buf + pos) = 48;  // '0'
        return pos + 1;
    }

    // Find the highest power of 10
    var divisor i64 = 1;
    var temp i64 = n;
    while temp >= 10 {
        temp = temp / 10;
        divisor = divisor * 10;
    }

    // Write each digit
    while divisor > 0 {
        var digit i64 = n / divisor;
        *(buf + pos) = 48 + digit;
        pos = pos + 1;
        n = n % divisor;
        divisor = divisor / 10;
    }

    return pos;
}

