        var input *ReaderSourceInput = vec_get(reader_host_inputs, i);
        if !phase_source_provide(input.name, input.text, input.parse_source) {
            reader_host_protocol(); cg_had_error = 1; return nil;
        }
        i = i + 1;
    }
