// mean the process defaults; projects only accept positive, bounded limits.
var phase_recognition_work i64 = 0;
var phase_recognition_depth i64 = 0;
var phase_recognition_source *u8 = nil;
var phase_recognition_offset i64 = 0;
pub func phase_recognition_limit(name *u8, fallback i64, maximum i64) i64 {
    return phase_recognition_setting(name, fallback, maximum, 1);
}
pub func phase_recognition_setting(name *u8, fallback i64, maximum i64, minimum i64) i64 {
    var text *u8 = getenv(name);
    if text == nil || *text == 0 { return fallback; }
    var n i64 = 0;
    while *text != 0 {
        if *text < 48 || *text > 57 || n > maximum / 10 {
