    stage_fail("native-stage-evaluation-unavailable");
    return nil;
}

std/prec.lang:
// std/prec.lang - operator precedence for reader lowering
//
// Every reader whose language spells `a + b * c` needs the same climb. The
// only things that differ are which operators exist, how tightly each binds,
// which way each associates, and whether an operator takes a left operand at
// all - so put those facts in a table and the climb stops being reader code.
//
//   func calc_table() *PrecTable {
//       var t *PrecTable = prec_new();
//       prec_assign(t, "= += -=");  // loosest level first
//       prec_left(t, "+ -");        // each call binds tighter than the last
//       prec_prefix(t, "!");        // takes no left operand
//       prec_left(t, "* / %");
//       return t;
//   }
//
// Build the expression by pushing operands and operators in source order; the
// operands are AST you already emitted, the operators are their token text.
//
//   var e *PrecExpr = prec_expr(calc_table());
//   prec_operand(e, ast_number("1"));
//   prec_op(e, "+");
//   prec_operand(e, ast_number("2"));
//   return prec_build(e);           // (binop + (number 1) (number 2))
//
// That order is what a hand-written parser and a flat generated grammar
// (`expr = first:unary rest:(op:operator right:unary)*`) both already walk, so
// neither has to build parallel vectors or carry its own climber. An operator
// pushed where an operand was expected is a PREFIX operator - position is what
// says which, so a language with `not a == b` pushes `not` and `a` in the order
// it read them and the table decides that `not` wraps the comparison.
//
// Assignment is a statement in the shared AST, not an expression, so it has its
// own build:
//
//   prec_build(e)        // an expression; an assignment operator is refused
//   prec_build_stmt(e)   // a statement: (assign ...) or (expr_stmt ...)
//
// That is what makes `f(a = b)` an error in a reader whose statements assign,
// instead of a tree the kernel cannot lower.
//
// prec_build refuses an operator with no level rather than guessing one: an
// unlisted operator is a hole in the ladder, not a reason to emit something.

include "std/ast.lang"

// What an operator does with the operands around it.
var PREC_INFIX i64 = 0;
var PREC_ASSIGN i64 = 1;
var PREC_PREFIX i64 = 2;

// What a pushed item is. Operands and operators share one list because their
// ORDER is the only thing that says whether an operator is prefix or infix.
var PREC_OPERAND i64 = 0;
var PREC_OP i64 = 1;

struct PrecOp {
    text *u8;
    level i64;      // 1 = loosest; higher binds tighter
    right i64;      // 1 = right-associative
    kind i64;       // PREC_INFIX | PREC_ASSIGN | PREC_PREFIX
}

struct PrecTable {
    ops *u8;        // vec of *PrecOp: operators that take a left operand
    prefixes *u8;   // vec of *PrecOp: operators that take none
    levels i64;     // levels declared so far
}

struct PrecExpr {
    table *PrecTable;
    items *u8;      // vec of *u8: operand AST or operator text, in source order
    kinds *u8;      // vec of PREC_OPERAND / PREC_OP, parallel to items
    assigned i64;   // 1 when the node built last was an assignment
}

pub func prec_new() *PrecTable {
    var t *PrecTable = alloc(24);
    t.ops = vec_new(16);
    t.prefixes = vec_new(4);
    t.levels = 0;
    return t;
}

// Declare one level from a space-separated operator list. Levels are handed
// out in call order, so the first call is the loosest.
func prec_level(t *PrecTable, ops *u8, right i64, kind i64) void {
    t.levels = t.levels + 1;
    var p *u8 = ops;
    while *p != 0 {
        while *p == ' ' { p = p + 1; }
        if *p == 0 { return; }
        // Count rather than subtract pointers: direct wasm has no pointer
        // difference, and this helper has to build readers for the browser too.
        var start *u8 = p;
        var len i64 = 0;
        while *p != 0 && *p != ' ' {
            p = p + 1;
            len = len + 1;
        }

        var text *u8 = alloc(len + 1);
        var i i64 = 0;
        while i < len {
            *(text + i) = *(start + i);
            i = i + 1;
        }
        *(text + len) = 0;

        var op *PrecOp = alloc(32);
        op.text = text;
        op.level = t.levels;
        op.right = right;
        op.kind = kind;
        if kind == PREC_PREFIX {
            vec_push(t.prefixes, op);
        } else {
            vec_push(t.ops, op);
        }
    }
}

pub func prec_left(t *PrecTable, ops *u8) void {
    prec_level(t, ops, 0, PREC_INFIX);
}

pub func prec_right(t *PrecTable, ops *u8) void {
    prec_level(t, ops, 1, PREC_INFIX);
}

// Operators that take no left operand and wrap what follows them. A prefix
// level binds everything TIGHTER than itself, which is how Python's `not`
// ends up looser than the comparisons it wraps.
pub func prec_prefix(t *PrecTable, ops *u8) void {
    prec_level(t, ops, 0, PREC_PREFIX);
}

// Assignment, its own kind because the shared AST spells it (assign target
// value), not (binop = target value). Declare it first - it is the loosest thing
// in every language that has it.
//
// Its right operand is an EXPRESSION, and the shared AST has no assignment
// expression, so `a = b = c` is refused rather than lowered to a tree the kernel
// cannot emit. The level is right-associative so the second operator lands in
// the first one's right operand, which is where that refusal reads correctly.
pub func prec_assign(t *PrecTable, ops *u8) void {
    prec_level(t, ops, 1, PREC_ASSIGN);
}

func prec_find(t *PrecTable, op *u8) *PrecOp {
    if op == nil { return nil; }
    var count i64 = vec_len(t.ops);
    var i i64 = 0;
    while i < count {
        var entry *PrecOp = vec_get(t.ops, i);
        if streq(entry.text, op) { return entry; }
        i = i + 1;
    }
    return nil;
}

func prec_find_prefix(t *PrecTable, op *u8) *PrecOp {
    if op == nil { return nil; }
    var count i64 = vec_len(t.prefixes);
    var i i64 = 0;
    while i < count {
        var entry *PrecOp = vec_get(t.prefixes, i);
        if streq(entry.text, op) { return entry; }
        i = i + 1;
    }
    return nil;
}

// Binding power of an operator in infix position, or 0 when the table does not
// list it there. A token-driven reader uses this to decide whether the next
// token continues the expression at all.
pub func prec_of(t *PrecTable, op *u8) i64 {
    var entry *PrecOp = prec_find(t, op);
    if entry == nil { return 0; }
    return entry.level;
}

// Whether an operator assigns. A reader whose grammar carries a tail its
// language binds tighter than assignment (C's `?:`) asks this to find where
// that tail belongs.
pub func prec_is_assign(t *PrecTable, op *u8) i64 {
    var entry *PrecOp = prec_find(t, op);
    if entry == nil { return 0; }
    if entry.kind == PREC_ASSIGN { return 1; }
    return 0;
}

pub func prec_expr(t *PrecTable) *PrecExpr {
    var e *PrecExpr = malloc(32);
    e.table = t;
    e.items = vec_new(8);
    e.kinds = vec_new(8);
    e.assigned = 0;
    return e;
}

pub func prec_operand(e *PrecExpr, value *u8) void {
    vec_push(e.items, value);
    vec_push(e.kinds, PREC_OPERAND);
}

pub func prec_op(e *PrecExpr, op *u8) void {
    vec_push(e.items, op);
    vec_push(e.kinds, PREC_OP);
}

func prec_undeclared(op *u8) void {
    eprint("reader lowering error: no precedence declared for operator '");
    eprint(op);
    eprintln("'");
}

// `x += y` means `x = x + y`. An assignment operator spelled as a declared
// operator followed by '=' reads, applies and writes back; anything else is a
// plain assignment, so a language whose assignment is ':=' or '<-' says so
// without inheriting C's compound forms.
func prec_assign_node(t *PrecTable, op *u8, target *u8, value *u8) *u8 {
    var len i64 = strlen(op);
    if len > 1 && *(op + len - 1) == '=' {
        var base *u8 = alloc(len);
        var i i64 = 0;
        while i < len - 1 {
            *(base + i) = *(op + i);
            i = i + 1;
        }
        *(base + len - 1) = 0;
        if prec_find(t, base) != nil {
            return ast_assign(target, ast_binop(base, target, value));
        }
    }
    return ast_assign(target, value);
}

// One Pratt pass over the item list. An operator in operand position is a
// prefix operator; an operator in operator position takes the tree built so
// far as its left operand. Either way the table is asked, never guessed at.
func prec_parse(e *PrecExpr, posptr *i64, minlevel i64, assignable i64) *u8 {
    var n i64 = vec_len(e.items);
    if *posptr >= n {
        eprintln("reader lowering error: expression has an operator without both operands");
        return nil;
    }

    var left *u8 = nil;
    var lead i64 = vec_get(e.kinds, *posptr);
    if lead == PREC_OP {
        var pre_op *u8 = vec_get(e.items, *posptr);
        var pre *PrecOp = prec_find_prefix(e.table, pre_op);
        if pre == nil {
            if prec_find(e.table, pre_op) == nil {
                prec_undeclared(pre_op);
            } else {
                eprint("reader lowering error: operator '");
                eprint(pre_op);
                eprintln("' has no left operand");
            }
            return nil;
        }
        if pre.level < minlevel {
            eprint("reader lowering error: operator '");
            eprint(pre_op);
            eprintln("' binds too loosely to be an operand here");
            return nil;
        }
        *posptr = *posptr + 1;
        // A prefix operator's operand is everything that binds at least as
        // tightly as the operator itself, so `not a == b` is `!(a == b)`.
        var operand *u8 = prec_parse(e, posptr, pre.level, 0);
        if operand == nil { return nil; }
        left = ast_unop(pre_op, operand);
        e.assigned = 0;
    } else {
        left = vec_get(e.items, *posptr);
        *posptr = *posptr + 1;
    }

    while *posptr < n {
        var kind i64 = vec_get(e.kinds, *posptr);
        if kind != PREC_OP {
            eprintln("reader lowering error: expression has two operands with no operator between them");
            return nil;
        }
        var op *u8 = vec_get(e.items, *posptr);
        var entry *PrecOp = prec_find(e.table, op);
        if entry == nil {
            if prec_find_prefix(e.table, op) == nil {
                prec_undeclared(op);
            } else {
                eprint("reader lowering error: operator '");
                eprint(op);
                eprintln("' takes no left operand");
            }
            return nil;
        }
        if entry.level < minlevel { return left; }
        if entry.kind == PREC_ASSIGN && assignable == 0 {
            eprint("reader lowering error: assignment operator '");
            eprint(op);
            eprintln("' is not an expression");
            return nil;
        }
        *posptr = *posptr + 1;

        // Left-associative levels stop at the same power on the right, so the
        // next operator of equal power folds around the tree built so far.
        var next i64 = entry.level + 1;
        if entry.right != 0 { next = entry.level; }
        var rhs_assignable i64 = assignable;
        if entry.kind == PREC_ASSIGN { rhs_assignable = 0; }
        var right *u8 = prec_parse(e, posptr, next, rhs_assignable);
        if right == nil { return nil; }
        if entry.kind == PREC_ASSIGN {
            left = prec_assign_node(e.table, op, left, right);
            e.assigned = 1;
        } else {
            left = ast_binop(op, left, right);
            e.assigned = 0;
        }
    }
    return left;
}

// The climb builds every node after its children, so the last node built is the
// outermost one - which is what `assigned` ends up describing.
func prec_climb_all(e *PrecExpr, assignable i64) *u8 {
    e.assigned = 0;
    if vec_len(e.items) == 0 {
        eprintln("reader lowering error: expression has no operands");
        return nil;
    }
    var pos i64 = 0;
    return prec_parse(e, &pos, 1, assignable);
}

pub func prec_build(e *PrecExpr) *u8 {
    return prec_climb_all(e, 0);
}

// The same expression in statement position, where an assignment is legal: a
// top-level assignment becomes (assign ...), anything else (expr_stmt ...).
pub func prec_build_stmt(e *PrecExpr) *u8 {
    var value *u8 = prec_climb_all(e, 1);
    if value == nil { return nil; }
    if e.assigned != 0 { return value; }
    return ast_expr_stmt(value);
}

std/tok.lang:
// ============================================================
// std/tok.lang - Tokenizer for Reader Macros
// ============================================================
//
// A simple, configurable tokenizer for building readers.
// Provides a stream of tokens with position tracking.
//
// Example:
//   var t *Tokenizer = tok_new("(+ 1 2)");
//   while !tok_eof(t) {
//       var kind i64 = tok_kind(t);
//       var text *u8 = tok_text(t);
//       tok_advance(t);
//   }
//

// ============================================================
// Token Kinds
// ============================================================

var TOK_EOF i64 = 0;
var TOK_NUMBER i64 = 1;
var TOK_IDENT i64 = 2;
var TOK_STRING i64 = 3;
var TOK_LPAREN i64 = 4;    // (
var TOK_RPAREN i64 = 5;    // )
var TOK_LBRACKET i64 = 6;  // [
var TOK_RBRACKET i64 = 7;  // ]
var TOK_LBRACE i64 = 8;    // {
var TOK_RBRACE i64 = 9;    // }
var TOK_PLUS i64 = 10;
var TOK_MINUS i64 = 11;
var TOK_STAR i64 = 12;
var TOK_SLASH i64 = 13;
var TOK_PERCENT i64 = 14;
var TOK_COMMA i64 = 15;
var TOK_COLON i64 = 16;
var TOK_SEMI i64 = 17;
var TOK_DOT i64 = 18;
var TOK_EQ i64 = 19;
var TOK_LT i64 = 20;
var TOK_GT i64 = 21;
var TOK_BANG i64 = 22;
var TOK_AMP i64 = 23;
var TOK_PIPE i64 = 24;
var TOK_CARET i64 = 25;
var TOK_QUESTION i64 = 26;  // ? (ternary)
var TOK_TILDE i64 = 27;     // ~ (bitwise not)
var TOK_UNKNOWN i64 = 99;

// Kinds a reader invents for its own token stream start here. The built-in
// scanner never produces one, so a grammar referring to a custom kind can only
// match a token some reader put there deliberately.
var TOK_USER i64 = 100;

// Reader-local numeric and identifier policies. Existing constructors retain
// the inherited scanner. Decimal profiles use unsigned [0-9]+; signs are tokens.
var TOK_NUM_DEFAULT i64 = 0;
var TOK_NUM_DECIMAL i64 = 1;

struct TokProfile {
    numbers i64;
    identifier_extra *u8; // extra continuation bytes, e.g. "-"; nil for ASCII
    line *u8;
    open *u8;
    close *u8;
}

pub func tok_profile_new(numbers i64, identifier_extra *u8, line *u8,
                         open *u8, close *u8) *TokProfile {
    var profile *TokProfile = alloc(40);
    profile.numbers = numbers;
    profile.identifier_extra = identifier_extra;
    profile.line = line;
    profile.open = open;
    profile.close = close;
    return profile;
}

// ============================================================
// Tokenizer State
// ============================================================

// Trusted measurement switch; manifests never set this.
var tok_parser_instrumentation i64 = 1;

struct Tokenizer {
    input *u8;      // input string
    pos i64;        // current position
    len i64;        // length of input
    tok_start i64;  // start of current token
    tok_len i64;    // length of current token
    tok_kind i64;   // kind of current token
    error_pos i64;       // furthest failed match, or -1
    error_expected *u8;  // "number or '('", capped at 511 bytes
    error_expected_len i64;
    error_found *u8;     // token text captured at error_pos
    error_end i64;      // end-exclusive byte offset captured with error_pos
    stream *u8;          // reader-supplied token stream, or nil to scan input
    stream_index i64;    // index of the current token within that stream
    stream_count i64;    // number of tokens in it
    stream_text *u8;     // text override for the current token, or nil
    comment_line *u8;    // line-comment prefix, or nil if the language has none
    comment_open *u8;    // block-comment opener, or nil
    comment_close *u8;   // block-comment closer, or nil
    recovery i64;       // editor-only, zero for every ordinary tokenizer
    comment_error i64;   // sticky lexical failure offset, or -1
    numbers i64;
    identifier_extra *u8;
    profile_boundaries bool; // only explicit profiles split identifiers at openers
    parser_work i64;
    parser_depth i64;
    parser_peak i64;
    parser_work_limit i64;
    parser_depth_limit i64;
    parser_enabled i64;
    parser_source *u8;
    parser_offset i64;
    split_minus i64;
    comment_cr i64;
    parser_streaming i64;
}

func tok_new_state(input *u8) *Tokenizer {
    var t *Tokenizer = alloc(272);  // 34 fields * 8 bytes
    t.input = input;
    t.pos = 0;
    t.len = strlen(input);
    t.tok_start = 0;
    t.tok_len = 0;
    t.tok_kind = TOK_EOF;
    t.error_pos = -1;
    t.error_expected = alloc(512);
    t.error_expected_len = 0;
    t.error_found = nil;
    t.error_end = -1;
    t.stream = nil;
    t.stream_index = 0;
    t.stream_count = 0;
    t.stream_text = nil;
    t.comment_line = "//";
    t.comment_open = "/*";
    t.comment_close = "*/";
    t.recovery = 0;
    t.comment_error = -1;
    t.parser_work = 0; t.parser_depth = 0; t.parser_peak = 0;
    t.parser_work_limit = phase_recognition_work;
    if t.parser_work_limit == 0 {
        t.parser_work_limit = phase_recognition_limit("LANG_PARSER_MAX_WORK", 1000000, 1000000000);
    }
    t.parser_depth_limit = phase_recognition_depth;
    if t.parser_depth_limit == 0 {
        t.parser_depth_limit = phase_recognition_limit("LANG_PARSER_MAX_DEPTH", 128, 256);
    }
    t.parser_offset = phase_recognition_offset;
    if phase_recognition_source == nil {
        t.parser_offset = phase_recognition_setting("LANG_PARSER_OFFSET", 0, 1073741824, 0);
    }
    t.parser_source = phase_recognition_source;
    if t.parser_source == nil { t.parser_source = getenv("LANG_PARSER_SOURCE"); }
    if t.parser_source == nil { t.parser_source = "<reader-input>"; }
    t.parser_enabled = tok_parser_instrumentation;
    t.numbers = TOK_NUM_DEFAULT;
    t.identifier_extra = nil;
    t.profile_boundaries = false;
    return t;
}

pub func tok_new(input *u8) *Tokenizer {
    var t *Tokenizer = tok_new_state(input);
    tok_next(t);  // prime the tokenizer
    return t;
}

// The same scanner, told how the language it is reading spells a comment.
//
// A reader has to say this when it MAKES the tokenizer: comments are skipped
// between tokens, so the syntax has to be settled before the first one is
// scanned. nil means the language does not have that form - which is how minipy
// says `//` is floor division and not the start of a comment, and the reason a
// reader no longer has to rewrite its own source text before scanning it.
//
// A block comment needs both delimiters; giving only an opener declares none.
pub func tok_new_comments(input *u8, line *u8, open *u8, close *u8) *Tokenizer {
    var t *Tokenizer = tok_new_state(input);
    t.comment_line = line;
    t.comment_open = open;
    t.comment_close = close;
    tok_next(t);
    return t;
}

// Copy policy before scanning the first token. Profiles can be declared beside
// their grammar and reused without sharing cursor or diagnostic state.
pub func tok_new_profile(input *u8, profile *TokProfile) *Tokenizer {
    var t *Tokenizer = tok_new_state(input);
    t.profile_boundaries = true;
    t.numbers = profile.numbers;
    t.identifier_extra = profile.identifier_extra;
    t.comment_line = profile.line;
    t.comment_open = profile.open;
    t.comment_close = profile.close;
    tok_next(t);
    return t;
}

// ============================================================
// Reader-supplied token streams
// ============================================================
//
// A generated parser only ever asks a Tokenizer for the current token's kind,
// text and span, and for a mark it can rewind to. None of that requires the
// tokenizer to be the thing that produced the token. A reader whose language is
// not a straight left-to-right scan - layout, a preprocessing pass, a lexer that
// needs to know something the parser already decided - can therefore lex the
// source its own way and hand the result over, and every generated parser reads
// it unchanged.
//
// A token is (kind, start, len, text): a kind, a half-open byte span into the
// SAME input string, and an optional text override. Spans stay real even for
// tokens the source does not literally contain, which is what keeps error
// locations and AST spans honest in a language nobody can parse by reading
// characters in order.

pub func tok_stream_new() *u8 {
    return vec_new(64);
}

// `text` is nil for a token that reads as the bytes it spans. A synthetic token
// - an INDENT standing for a column, say - spans zero bytes at the position it
// was inferred from, and names itself through `text` so that a parse error can
// still say what it found.
pub func tok_stream_push(toks *u8, kind i64, start i64, len i64, text *u8) void {
    vec_push(toks, kind);
    vec_push(toks, start);
    vec_push(toks, len);
    vec_push(toks, text);
}

pub func tok_stream_count(toks *u8) i64 {
    return vec_len(toks) / 4;
}

pub func tok_new_stream(input *u8, toks *u8) *Tokenizer {
    var t *Tokenizer = tok_new_state(input);
    t.stream = toks;
    t.stream_count = tok_stream_count(toks);
    tok_stream_load(t, 0);
    return t;
}

// Position on token `index`. Past the end is EOF at the end of the input, which
// is where a parser that wanted more will report having run out.
func tok_stream_load(t *Tokenizer, index i64) void {
    if index < 0 { index = 0; }
    if index > t.stream_count { index = t.stream_count; }
    t.stream_index = index;
    if index >= t.stream_count {
        t.tok_kind = TOK_EOF;
        t.tok_start = t.len;
        t.tok_len = 0;
        t.stream_text = nil;
        t.pos = t.len;
        return;
    }
    var base i64 = index * 4;
    t.tok_kind = vec_get(t.stream, base);
    t.tok_start = vec_get(t.stream, base + 1);
    t.tok_len = vec_get(t.stream, base + 2);
    t.stream_text = vec_get(t.stream, base + 3);
    t.pos = t.tok_start + t.tok_len;
}

// ============================================================
// Character Helpers
// ============================================================

pub func tok_is_digit(c i64) bool {
    return c >= 48 && c <= 57;
}

pub func tok_is_alpha(c i64) bool {
    return (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95;
}

pub func tok_is_alnum(c i64) bool {
    return tok_is_digit(c) || tok_is_alpha(c);
}

func tok_identifier_continue(t *Tokenizer, c i64) bool {
    if tok_is_alnum(c) { return true; }
    if c == 0 || t.identifier_extra == nil { return false; }
    var extra *u8 = t.identifier_extra;
    while *extra != 0 {
        if *extra == c { return true; }
        extra = extra + 1;
    }
    return false;
}

pub func tok_is_space(c i64) bool {
    return c == 32 || c == 9 || c == 10 || c == 13;
}

// ============================================================
// Tokenizer Methods
// ============================================================

pub func tok_peek_char(t *Tokenizer) i64 {
    if t.pos >= t.len {
        return 0;
    }
    return *(t.input + t.pos);
}

pub func tok_peek_char_at(t *Tokenizer, offset i64) i64 {
    if t.pos + offset >= t.len {
        return 0;
    }
    return *(t.input + t.pos + offset);
}

pub func tok_advance_char(t *Tokenizer) void {
    if t.pos < t.len {
        t.pos = t.pos + 1;
    }
}

// Length of `s` when the input matches it at the cursor, else 0. A nil marker
// never matches, which is how a language that has no such comment says so.
func tok_marker_at(t *Tokenizer, s *u8) i64 {
    if s == nil { return 0; }
    var i i64 = 0;
    while *(s + i) != 0 {
        if t.pos + i >= t.len { return 0; }
        if *(t.input + t.pos + i) != *(s + i) { return 0; }
        i = i + 1;
    }
    return i;
}

func tok_skip_marker(t *Tokenizer, n i64) void {
    var i i64 = 0;
    while i < n {
        tok_advance_char(t);
        i = i + 1;
    }
}

// One sticky lexical diagnostic, shared by numeric and comment policies.
func tok_fail_lexical(t *Tokenizer, start i64, end i64, expected *u8, found *u8) void {
    t.comment_error = start;
    t.error_pos = start;
    t.error_end = end;
    t.error_expected_len = 0;
    while *expected != 0 && t.error_expected_len < 511 {
        *(t.error_expected + t.error_expected_len) = *expected;
        t.error_expected_len = t.error_expected_len + 1;
        expected = expected + 1;
    }
    *(t.error_expected + t.error_expected_len) = 0;
    t.error_found = found;
}

pub func tok_skip_whitespace(t *Tokenizer) void {
    if t.comment_error >= 0 { return; }
    var again i64 = 1;
    while again == 1 {
        again = 0;
        while t.pos < t.len && tok_is_space(tok_peek_char(t)) {
            tok_advance_char(t);
        }
        // Line comment: <marker> ... to end of line. The newline is left for
        // the whitespace pass, so a layout reader can still see where it was.
        if tok_marker_at(t, t.comment_line) > 0 {
            while t.pos < t.len && tok_peek_char(t) != 10 {
                if t.comment_cr != 0 && tok_peek_char(t) == 13 { break; }
                tok_advance_char(t);
            }
            again = 1;
        }
        // Block comment: <open> ... <close>, both required.
        if t.comment_close != nil {
            var open i64 = tok_marker_at(t, t.comment_open);
            if open > 0 {
                var start i64 = t.pos;
                tok_skip_marker(t, open);
                while t.pos < t.len && tok_marker_at(t, t.comment_close) == 0 {
                    tok_advance_char(t);
                }
                var close i64 = tok_marker_at(t, t.comment_close);
                if close == 0 {
                    // Lexical failure survives parser alternatives and end checks.
                    // Select the entire unfinished comment in original bytes.
                    tok_fail_lexical(t, start, t.len, t.comment_close, "unterminated block comment");
                    return;
                }
                tok_skip_marker(t, close);
                again = 1;
            }
        }
    }
}

// A valid scalar's width; malformed bytes remain individual unknown tokens.
func tok_utf8_width(t *Tokenizer) i64 {
    var first i64 = tok_peek_char(t);
    var width i64 = 1;
    if first >= 194 && first <= 223 { width = 2; }
    else if first >= 224 && first <= 239 { width = 3; }
    else if first >= 240 && first <= 244 { width = 4; }
    if t.pos + width > t.len { return 1; }
    var i i64 = 1;
    while i < width {
        var next i64 = tok_peek_char_at(t, i);
        if next < 128 || next > 191 { return 1; }
        i = i + 1;
    }
    var second i64 = tok_peek_char_at(t, 1);
    if first == 224 && second < 160 { return 1; }
    if first == 237 && second > 159 { return 1; }
    if first == 240 && second < 144 { return 1; }
    if first == 244 && second > 143 { return 1; }
    return width;
}

// Consume one complete invalid numeric spelling rather than accepting a
// numeric prefix. Delimiters/comments retain their original source positions.
func tok_decimal(t *Tokenizer) void {
    var invalid bool = false;
    while tok_is_digit(tok_peek_char(t)) {
        // An opener can itself start with a digit; it still ends the number.
        if tok_marker_at(t, t.comment_line) > 0 { break; }
        if t.comment_close != nil && tok_marker_at(t, t.comment_open) > 0 { break; }
        tok_advance_char(t);
    }
    var c i64 = tok_peek_char(t);
    var comment bool = tok_marker_at(t, t.comment_line) > 0;
    if t.comment_close != nil && tok_marker_at(t, t.comment_open) > 0 { comment = true; }
    if !comment && (c == 46 || tok_identifier_continue(t, c)) {
        invalid = true;
        var previous i64 = 0;
        while t.pos < t.len {
            if tok_marker_at(t, t.comment_line) > 0 { break; }
            if t.comment_close != nil && tok_marker_at(t, t.comment_open) > 0 { break; }
            c = tok_peek_char(t);
            if c != 46 && !tok_identifier_continue(t, c) &&
               !((c == 43 || c == 45) && (previous == 101 || previous == 69)) { break; }
            previous = c;
            tok_advance_char(t);
        }
    }
    t.tok_len = t.pos - t.tok_start;
    t.tok_kind = TOK_NUMBER;
    if invalid {
        t.tok_kind = TOK_UNKNOWN;
        tok_fail_lexical(t, t.tok_start, t.pos, "decimal integer", tok_text(t));
    }
}

pub func tok_next(t *Tokenizer) void {
    if t.stream != nil {
        tok_stream_load(t, t.stream_index + 1);
        return;
    }
    tok_skip_whitespace(t);

    if t.comment_error >= 0 {
        t.tok_start = t.comment_error;
        t.tok_len = t.error_end - t.comment_error;
        t.tok_kind = TOK_UNKNOWN;
        return;
    }

    t.tok_start = t.pos;
    t.tok_len = 0;

    if t.pos >= t.len {
        t.tok_kind = TOK_EOF;
        return;
    }

    var c i64 = tok_peek_char(t);

    if t.numbers == TOK_NUM_DECIMAL &&
       (tok_is_digit(c) || (c == 46 && tok_is_digit(tok_peek_char_at(t, 1)))) {
        tok_decimal(t);
        return;
    }

    // Single character tokens
    if c == 40 { t.tok_kind = TOK_LPAREN; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 41 { t.tok_kind = TOK_RPAREN; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 91 { t.tok_kind = TOK_LBRACKET; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 93 { t.tok_kind = TOK_RBRACKET; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 123 { t.tok_kind = TOK_LBRACE; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 125 { t.tok_kind = TOK_RBRACE; t.tok_len = 1; tok_advance_char(t); return; }
    // + ++ +=  (2-char forms share the kind, with tok_len=2 + 2-char text, like <<)
    if c == 43 {
        tok_advance_char(t);
        var pn i64 = tok_peek_char(t);
        if pn == 43 || pn == 61 { tok_advance_char(t); t.tok_len = 2; }  // ++ or +=
        else { t.tok_len = 1; }
        t.tok_kind = TOK_PLUS;
        return;
    }
    if c == 42 {  // * or *=
        tok_advance_char(t);
        if tok_peek_char(t) == 61 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_STAR;
        return;
    }
    if c == 47 {  // / or /=
        tok_advance_char(t);
        if tok_peek_char(t) == 61 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_SLASH;
        return;
    }
    if c == 37 {  // % or %=
        tok_advance_char(t);
        if tok_peek_char(t) == 61 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_PERCENT;
        return;
    }
    if c == 94 { t.tok_kind = TOK_CARET; t.tok_len = 1; tok_advance_char(t); return; }  // ^
    if c == 63 { t.tok_kind = TOK_QUESTION; t.tok_len = 1; tok_advance_char(t); return; }  // ?
    if c == 126 { t.tok_kind = TOK_TILDE; t.tok_len = 1; tok_advance_char(t); return; }  // ~
    if c == 44 { t.tok_kind = TOK_COMMA; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 58 { t.tok_kind = TOK_COLON; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 59 { t.tok_kind = TOK_SEMI; t.tok_len = 1; tok_advance_char(t); return; }
    if c == 46 { t.tok_kind = TOK_DOT; t.tok_len = 1; tok_advance_char(t); return; }

    // Multi-char operators: ==, !=, <=, >=, <<, >>, &&, ||
    if c == 61 {  // = or ==
        tok_advance_char(t);
        if tok_peek_char(t) == 61 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_EQ;
        return;
    }
    if c == 60 {  // < or <= or <<
        tok_advance_char(t);
        var next i64 = tok_peek_char(t);
        if next == 61 || next == 60 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_LT;
        return;
    }
    if c == 62 {  // > or >= or >>
        tok_advance_char(t);
        var next i64 = tok_peek_char(t);
        if next == 61 || next == 62 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_GT;
        return;
    }
    if c == 33 {  // ! or !=
        tok_advance_char(t);
        if tok_peek_char(t) == 61 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_BANG;
        return;
    }
    if c == 38 {  // & or &&
        tok_advance_char(t);
        if tok_peek_char(t) == 38 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_AMP;
        return;
    }
    if c == 124 {  // | or ||
        tok_advance_char(t);
        if tok_peek_char(t) == 124 { tok_advance_char(t); t.tok_len = 2; }
        else { t.tok_len = 1; }
        t.tok_kind = TOK_PIPE;
        return;
    }

    // Minus or negative number
    if c == 45 {
        if tok_peek_char_at(t, 1) == 62 {  // -> : lex as '.' (the kernel's field
            tok_advance_char(t);           // access auto-derefs pointers, so p->x
            tok_advance_char(t);           // and p.x are equivalent for a reader)
            t.tok_len = 2;
            t.tok_kind = TOK_DOT;
            return;
        }
        var mn i64 = tok_peek_char_at(t, 1);
        if (mn == 45 && t.split_minus == 0) || mn == 61 {          // -- or -= (TOK_MINUS, tok_len=2, text)
            tok_advance_char(t);
            tok_advance_char(t);
            t.tok_len = 2;
            t.tok_kind = TOK_MINUS;
            return;
        }
        if t.split_minus == 0 && t.numbers == TOK_NUM_DEFAULT && tok_is_digit(tok_peek_char_at(t, 1)) {
            // Negative number
            tok_advance_char(t);
            while tok_is_digit(tok_peek_char(t)) {
                tok_advance_char(t);
            }
            t.tok_len = t.pos - t.tok_start;
            t.tok_kind = TOK_NUMBER;
            return;
        }
        t.tok_kind = TOK_MINUS;
        t.tok_len = 1;
        tok_advance_char(t);
        return;
    }

    // Number
    if tok_is_digit(c) {
        while tok_is_digit(tok_peek_char(t)) {
            tok_advance_char(t);
        }
        t.tok_len = t.pos - t.tok_start;
        t.tok_kind = TOK_NUMBER;
        return;
    }

    // Identifier
    if tok_is_alpha(c) {
        while tok_identifier_continue(t, tok_peek_char(t)) {
            // Explicit profiles give openers priority inside an identifier.
            // Legacy constructors only recognize comments between tokens.
            if t.profile_boundaries {
                if tok_marker_at(t, t.comment_line) > 0 { break; }
                if t.comment_close != nil && tok_marker_at(t, t.comment_open) > 0 { break; }
            }
            tok_advance_char(t);
        }
        t.tok_len = t.pos - t.tok_start;
        t.tok_kind = TOK_IDENT;
        return;
    }

    // Double-quoted string
    if c == 34 {  // "
        tok_advance_char(t);  // skip opening quote
        while tok_peek_char(t) != 0 {
            if tok_peek_char(t) == 34 { break; }
            if tok_peek_char(t) == 92 {  // backslash escape
                tok_advance_char(t);
            }
            tok_advance_char(t);
        }
        if tok_peek_char(t) == 34 {
            tok_advance_char(t);  // skip closing quote
        }
        t.tok_len = t.pos - t.tok_start;
        t.tok_kind = TOK_STRING;
        return;
    }

    // Single-quoted string (for grammar literals like '(')
    if c == 39 {  // '
        tok_advance_char(t);  // skip opening quote
        while tok_peek_char(t) != 0 {
            if tok_peek_char(t) == 39 { break; }
            if tok_peek_char(t) == 92 {  // backslash escape
                tok_advance_char(t);
            }
            tok_advance_char(t);
        }
        if tok_peek_char(t) == 39 {
            tok_advance_char(t);  // skip closing quote
        }
        t.tok_len = t.pos - t.tok_start;
        t.tok_kind = TOK_STRING;
        return;
    }

    // Unknown Unicode scalars remain one token, with their original byte span.
    // They are not identifiers or whitespace unless a reader declares them so.
    t.tok_kind = TOK_UNKNOWN;
    t.tok_len = tok_utf8_width(t);
    tok_skip_marker(t, t.tok_len);
}

pub func tok_kind(t *Tokenizer) i64 {
    return t.tok_kind;
}

pub func tok_eof(t *Tokenizer) bool {
    return t.tok_kind == TOK_EOF;
}

// Returns the raw text of the current token (not null-terminated!)
pub func tok_text_ptr(t *Tokenizer) *u8 {
    if t.stream_text != nil { return t.stream_text; }
    return t.input + t.tok_start;
}

pub func tok_text_len(t *Tokenizer) i64 {
    if t.stream_text != nil { return strlen(t.stream_text); }
    return t.tok_len;
}

pub func tok_start_offset(t *Tokenizer) i64 {
    return t.tok_start;
}

pub func tok_end_offset(t *Tokenizer) i64 {
    return t.tok_start + t.tok_len;
}

// Returns a null-terminated copy of the token text
pub func tok_text(t *Tokenizer) *u8 {
    if t.stream_text != nil { return t.stream_text; }
    if t.tok_kind == TOK_UNKNOWN && t.tok_len == 1 &&
       *(t.input + t.tok_start) >= 128 { return "invalid UTF-8 byte"; }
    var buf *u8 = nil;
    if reader_scratch_active != 0 { buf = reader_scratch_alloc(t.tok_len + 1); }
    else { buf = alloc(t.tok_len + 1); }
    var i i64 = 0;
    while i < t.tok_len {
        *(buf + i) = *(t.input + t.tok_start + i);
        i = i + 1;
    }
    *(buf + t.tok_len) = 0;
    return buf;
}

// A checkpoint names the current token, not the byte after it. Restoring and
// lexing again also handles whitespace/comments between the previous token and
// this one, while leaving furthest-error tracking intact across alternatives.
pub func tok_mark(t *Tokenizer) i64 {
    if t.stream != nil { return t.stream_index; }
    return t.tok_start;
}

pub func tok_reset(t *Tokenizer, mark i64) void {
    if t.stream != nil { tok_stream_load(t, mark); return; }
    if mark < 0 { mark = 0; }
    if mark > t.len { mark = t.len; }
    t.pos = mark;
    tok_next(t);
}

func tok_expected_has(t *Tokenizer, expected *u8, expected_len i64) i64 {
    var i i64 = 0;
    while i + expected_len <= t.error_expected_len {
        var before_ok i64 = 0;
        if i == 0 { before_ok = 1; }
        else if i >= 4 && str_eq_n(t.error_expected + i - 4, 4, " or ", 4) { before_ok = 1; }
        if before_ok != 0 && str_eq_n(t.error_expected + i, expected_len, expected, expected_len) {
            var after i64 = i + expected_len;
            if after == t.error_expected_len { return 1; }
            if after + 4 <= t.error_expected_len &&
               str_eq_n(t.error_expected + after, 4, " or ", 4) {
                return 1;
            }
        }
        i = i + 1;
    }
    return 0;
}

// Generated parsers call this on a terminal mismatch. Expectations at the
// furthest byte win; alternatives failing at that byte are accumulated.
pub func tok_note_expected(t *Tokenizer, expected *u8) void {
    if t.comment_error >= 0 { return; }
    var at i64 = t.tok_start;
    if at < t.error_pos { return; }

    if at > t.error_pos {
        t.error_pos = at;
        t.error_end = tok_end_offset(t);
        t.error_expected_len = 0;
        *t.error_expected = 0;
        if t.tok_kind == TOK_EOF { t.error_found = "end of input"; }
        else { t.error_found = tok_text(t); }
    }

    var expected_len i64 = strlen(expected);
    if tok_expected_has(t, expected, expected_len) != 0 { return; }

    var needed i64 = expected_len;
    if t.error_expected_len > 0 { needed = needed + 4; }
    if t.error_expected_len + needed >= 512 { return; }

    if t.error_expected_len > 0 {
        memcpy(t.error_expected + t.error_expected_len, " or ", 4);
        t.error_expected_len = t.error_expected_len + 4;
    }
    memcpy(t.error_expected + t.error_expected_len, expected, expected_len);
    t.error_expected_len = t.error_expected_len + expected_len;
    *(t.error_expected + t.error_expected_len) = 0;
}

// Call only after a successful root parse. A mismatch beyond the remaining
// token explains a rewound partial match; otherwise report the input boundary.
pub func tok_expect_end(t *Tokenizer) bool {
    if t.comment_error >= 0 { return false; }
    if tok_eof(t) { return true; }
    if t.error_pos > t.tok_start { return false; }
    t.error_pos = -1;
    t.error_expected_len = 0;
    *t.error_expected = 0;
    tok_note_expected(t, "end of input");
    return false;
}

pub func tok_error_end_offset(t *Tokenizer) i64 {
    return t.error_end;
}

pub func tok_error_offset(t *Tokenizer) i64 {
    return t.error_pos;
}

pub func tok_error_expected(t *Tokenizer) *u8 {
    return t.error_expected;
}

pub func tok_error_found(t *Tokenizer) *u8 {
    if t.error_found == nil { return ""; }
    return t.error_found;
}

pub func tok_error_line(t *Tokenizer) i64 {
    var stop i64 = t.error_pos;
    if stop < 0 { stop = t.tok_start; }
    var line i64 = 1;
    var i i64 = 0;
    while i < stop {
        if *(t.input + i) == 10 { line = line + 1; }
        i = i + 1;
    }
    return line;
}

pub func tok_error_column(t *Tokenizer) i64 {
    var stop i64 = t.error_pos;
    if stop < 0 { stop = t.tok_start; }
    var column i64 = 1;
    var i i64 = 0;
    while i < stop {
        if *(t.input + i) == 10 { column = 1; }
        else { column = column + 1; }
        i = i + 1;
    }
    return column;
}

// Ready-to-use diagnostic for small readers. Larger readers can use the query
// functions above to integrate the same structured data into their own errors.
pub func tok_print_error(t *Tokenizer, label *u8) void {
    // Without a recorded mismatch, success cannot be inferred here. Readers
    // explicitly check successful roots with tok_expect_end before printing.
    if t.error_pos < 0 { tok_note_expected(t, "valid token"); }
    var message *u8 = str_concat("expected ", tok_error_expected(t));
    message = str_concat(message, ", found ");
    message = str_concat(message, tok_error_found(t));
    if label == nil || *label == 0 { label = "reader"; }
    reader_error("reader-syntax", message, label, t.input,
                 tok_error_offset(t), tok_error_end_offset(t));
}

// Opt in to source context without changing the compact diagnostic above.
// Carry the request through the diagnostic record so the host renders it only
// after validating and mapping the source span; JSON stays structured.
pub func tok_print_error_snippet(t *Tokenizer, label *u8) void {
    if t.error_pos < 0 { tok_note_expected(t, "valid token"); }
    var message *u8 = str_concat("expected ", tok_error_expected(t));
    message = str_concat(message, ", found ");
    message = str_concat(message, tok_error_found(t));
    if label == nil || *label == 0 { label = "reader"; }
    reader_error("reader-syntax-snippet", message, label, t.input,
                 tok_error_offset(t), tok_error_end_offset(t));
}

// Parse the current number token as i64
pub func tok_number(t *Tokenizer) i64 {
    var ptr *u8 = tok_text_ptr(t);
    var len i64 = tok_text_len(t);
    var neg i64 = 0;
    var i i64 = 0;

    if len > 0 && *ptr == 45 {  // '-'
        neg = 1;
        i = 1;
    }

    var n i64 = 0;
    while i < len {
        n = n * 10 + (*(ptr + i) - 48);
        i = i + 1;
    }

    if neg != 0 {
        return 0 - n;
    }
    return n;
}

// Get the string value (without quotes, with escapes processed)
pub func tok_string_value(t *Tokenizer) *u8 {
    var start *u8 = t.input + t.tok_start + 1;  // skip opening quote
    var len i64 = t.tok_len - 2;  // exclude both quotes
    var buf *u8 = alloc(len + 1);
    var i i64 = 0;
    var j i64 = 0;

    while i < len {
        var c i64 = *(start + i);
        if c == 92 && i + 1 < len {  // backslash
            i = i + 1;
            var next i64 = *(start + i);
            if next == 110 { c = 10; }       // \n
            else if next == 114 { c = 13; }  // \r
            else if next == 116 { c = 9; }   // \t
            else if next == 34 { c = 34; }   // \"
            else if next == 92 { c = 92; }   // \\
            else { c = next; }
        }
        *(buf + j) = c;
        i = i + 1;
        j = j + 1;
    }
    *(buf + j) = 0;
    return buf;
}

// Check if current token matches a specific kind
pub func tok_check(t *Tokenizer, kind i64) bool {
    return t.tok_kind == kind;
}

// Match and consume a token of the given kind
pub func tok_match(t *Tokenizer, kind i64) bool {
    if t.tok_kind == kind {
        tok_next(t);
        return true;
    }
    return false;
}

// Expect a token of the given kind (error if not found)
pub func tok_expect(t *Tokenizer, kind i64) bool {
    if t.tok_kind != kind {
        return false;
    }
    tok_next(t);
    return true;
}

// Each outer parse_<rule> call owns one budget. Rewinds never refund work.
// Trusted direct callers may disable instrumentation for measurement by setting
// parser_enabled=0 before entry; projects never expose this as a manifest limit.
pub func tok_parser_error(t *Tokenizer, code *u8, rule *u8, grammar i64) void {
    eprint("parser rule "); eprint(rule); eprint(" grammar @");
    eprint_i64(grammar); eprint(" source "); eprint(t.parser_source);
    eprint(" @"); eprint_i64(t.parser_offset + t.tok_start); eprintln("");
    phase_error_at(code, t.parser_source, t.parser_offset + t.tok_start,
                   t.parser_offset + t.tok_start + t.tok_len);
}
// A streaming reader recognizes several roots in one input. Keep a single
// work account across those roots, using the caller's default for this grammar.
func tok_parser_streaming(t *Tokenizer, default_work i64) void {
    t.parser_streaming = 1;
    if phase_recognition_work == 0 {
        t.parser_work_limit = phase_recognition_limit("LANG_PARSER_MAX_WORK", default_work, 1000000000);
    }
}
pub func tok_parser_enter(t *Tokenizer, rule *u8, grammar i64) void {
    if t.parser_enabled == 0 { return; }
    if t.parser_depth == 0 && t.parser_streaming == 0 { t.parser_work = 0; t.parser_peak = 0; }
    if t.parser_depth >= t.parser_depth_limit {
        tok_parser_error(t, "parser-depth-budget", rule, grammar);
    }
    t.parser_depth = t.parser_depth + 1;
    if t.parser_depth > t.parser_peak { t.parser_peak = t.parser_depth; }
}
pub func tok_parser_work(t *Tokenizer, rule *u8, grammar i64) void {
    if t.parser_enabled == 0 { return; }
    if t.parser_work >= t.parser_work_limit {
        tok_parser_error(t, "parser-work-budget", rule, grammar);
    }
    t.parser_work = t.parser_work + 1;
}
pub func tok_parser_leave(t *Tokenizer) void {
    if t.parser_enabled != 0 { t.parser_depth = t.parser_depth - 1; }
}

