// ============================================================
// PNode - the parse tree shared by generated parsers and the kernel
// ============================================================
//
// Both #parser{}-generated parsers (via std/rdgen.lang) and the kernel's
// S-expression loader (src/sexpr_reader.lang) build this tree. It is defined
// ONCE here so a composed compiler - `kernel -r <name> <reader.ast>`, which
// links a reader's toolkit into the kernel - carries a single copy instead of
// colliding on duplicate symbols. The kernel includes this file; the reader
// toolkit requires it (so -r composition filters it as kernel-supplied).

struct PNode {
    kind i64;       // PNODE_* constant
    text *u8;       // token text (for atoms)
    children *u8;   // vec of *PNode (for lists/sequences)
    start i64;      // zero-based byte start in reader input, or -1
    end i64;        // exclusive byte end in reader input, or -1
    branch *u8;     // label of the choice alternative that built this, or nil
}

var PNODE_ERROR i64 = 8;
var PNODE_SKIPPED i64 = 9;
var PNODE_MISSING i64 = 10;
var PNODE_MISMATCH i64 = 11;

var PNODE_NUMBER i64 = 1;
var PNODE_SYMBOL i64 = 2;
var PNODE_STRING i64 = 3;
var PNODE_LIST i64 = 4;
var PNODE_OPERATOR i64 = 5;
var PNODE_CAPTURE i64 = 6;
var PNODE_TOKEN i64 = 7;      // a token kind the reader defined, not the scanner

pub func pnode_new(kind i64) *PNode {
    var n *PNode = nil;
    if reader_scratch_active != 0 { n = reader_scratch_alloc(48); }
    else { n = alloc(48); }
    n.kind = kind;
    n.text = nil;
    n.children = nil;
    n.start = -1;
    n.end = -1;
    n.branch = nil;
    return n;
}

pub func pnode_atom(kind i64, text *u8) *PNode {
    var n *PNode = pnode_new(kind);
    n.text = text;
    return n;
}

pub func pnode_atom_span(kind i64, text *u8, start i64, end i64) *PNode {
    var n *PNode = pnode_atom(kind, text);
    n.start = start;
    n.end = end;
    return n;
}

pub func pnode_list(children *u8) *PNode {
    var n *PNode = pnode_new(PNODE_LIST);
    n.children = children;
    var count i64 = vec_len(children);
    var i i64 = 0;
    while i < count && n.start < 0 {
        var child *PNode = vec_get(children, i);
        if child != nil && child.start >= 0 { n.start = child.start; }
        i = i + 1;
    }
    i = count - 1;
    while i >= 0 && n.end < 0 {
        var child *PNode = vec_get(children, i);
        if child != nil && child.end >= 0 { n.end = child.end; }
        i = i - 1;
    }
    return n;
}

// Captures are opt-in wrappers generated by `name:element` in #parser{}.
// Keeping the label on a wrapper rather than on the child makes nested
// captures safe and leaves the PNode layout and every old grammar unchanged.
pub func pnode_capture(name *u8, child *PNode) *PNode {
    var children *u8 = vec_new(1);
    vec_push(children, child);
    var n *PNode = pnode_list(children);
    n.kind = PNODE_CAPTURE;
    n.text = name;
    return n;
}

pub func pnode_unwrap(node *PNode) *PNode {
    while node != nil && node.kind == PNODE_CAPTURE &&
          node.children != nil && vec_len(node.children) > 0 {
        node = vec_get(node.children, 0);
    }
    return node;
}

pub func pnode_child(node *PNode, index i64) *PNode {
    node = pnode_unwrap(node);
    if node == nil || node.children == nil { return nil; }
    return pnode_unwrap(vec_get(node.children, index));
}

// Report a reader's own error in the same byte-based line/column format as
// tok_print_error. The source is the text handed to the reader, not the host
// file containing a reader block. Nodes without spans keep a bare diagnostic.
pub func pnode_print_error(node *PNode, source *u8, label *u8, message *u8) void {
    var start i64 = -1; var end i64 = -1;
    if node != nil { start = node.start; end = node.end; }
    if label == nil || *label == 0 { label = "reader"; }
    reader_error("reader-error", message, label, source, start, end);
}

func pnode_collect_capture_chain(node *PNode, name *u8,
                                 matches *u8) void {
    while node != nil && node.kind == PNODE_CAPTURE {
        if node.text != nil && streq(node.text, name) {
            vec_push(matches, pnode_unwrap(node));
        }
        if node.children == nil || vec_len(node.children) == 0 { return; }
        node = vec_get(node.children, 0);
    }
}

func pnode_count_capture_chain(node *PNode, name *u8) i64 {
    var count i64 = 0;
    while node != nil && node.kind == PNODE_CAPTURE {
        if node.text != nil && streq(node.text, name) { count = count + 1; }
        if node.children == nil || vec_len(node.children) == 0 { return count; }
        node = vec_get(node.children, 0);
    }
    return count;
}

func pnode_first_capture_chain(node *PNode, name *u8) *PNode {
    while node != nil && node.kind == PNODE_CAPTURE {
        if node.text != nil && streq(node.text, name) {
            return pnode_unwrap(node);
        }
        if node.children == nil || vec_len(node.children) == 0 { return nil; }
        node = vec_get(node.children, 0);
    }
    return nil;
}

// A labeled alternative names its node instead of wrapping it, so a child that
// carries the label answers the same question a capture wrapper used to.
func pnode_branch_matches(node *PNode, name *u8) i64 {
    node = pnode_unwrap(node);
    if node == nil || node.branch == nil { return 0; }
    if streq(node.branch, name) { return 1; }
    return 0;
}

func pnode_visible_capture_count(node *PNode, name *u8) i64 {
    var total i64 = pnode_count_capture_chain(node, name);
    node = pnode_unwrap(node);
    if node == nil || node.children == nil { return total; }
    var count i64 = vec_len(node.children);
    var i i64 = 0;
    while i < count {
        var child *PNode = vec_get(node.children, i);
        total = total + pnode_count_capture_chain(child, name);
        total = total + pnode_branch_matches(child, name);
        i = i + 1;
    }
    return total;
}

func pnode_first_visible_capture(node *PNode, name *u8) *PNode {
    var found *PNode = pnode_first_capture_chain(node, name);
    if found != nil { return found; }
    node = pnode_unwrap(node);
    if node == nil || node.children == nil { return nil; }
    var count i64 = vec_len(node.children);
    var i i64 = 0;
    while i < count {
        var child *PNode = vec_get(node.children, i);
        found = pnode_first_capture_chain(child, name);
        if found != nil { return found; }
        if pnode_branch_matches(child, name) != 0 { return pnode_unwrap(child); }
        i = i + 1;
    }
    return nil;
}

// Return every matching capture directly visible from this parse node. This is
// the explicit API for captures repeated by `*`/`+` or surfaced by more than
// one referenced rule.
pub func pnode_get_all(node *PNode, name *u8) *u8 {
    var matches *u8 = vec_new(4);
    pnode_collect_capture_chain(node, name, matches);

    node = pnode_unwrap(node);
    if node == nil || node.children == nil { return matches; }
    var count i64 = vec_len(node.children);
    var i i64 = 0;
    while i < count {
        var child *PNode = vec_get(node.children, i);
        pnode_collect_capture_chain(child, name, matches);
        if pnode_branch_matches(child, name) != 0 {
            vec_push(matches, pnode_unwrap(child));
        }
        i = i + 1;
    }
    return matches;
}

func pnode_lookup_one(node *PNode, name *u8, required i64) *PNode {
    var count i64 = pnode_visible_capture_count(node, name);
    if count > 1 {
        eprint("reader lowering error: grammar capture '");
        eprint(name);
        eprintln("' is ambiguous in this parse node");
        return nil;
    }
    if count == 0 {
        if required == 0 { return nil; }
        eprint("reader lowering error: required grammar capture '");
        eprint(name);
        eprintln("' is absent");
        return nil;
    }
    return pnode_first_visible_capture(node, name);
}

// Look up one capture directly visible from this parse node. Optional captures
// return nil; multiple matches are an error instead of an arbitrary first hit.
pub func pnode_get(node *PNode, name *u8) *PNode {
    return pnode_lookup_one(node, name, 0);
}

pub func pnode_require(node *PNode, name *u8) *PNode {
    return pnode_lookup_one(node, name, 1);
}

// A labeled choice alternative (`name:element` as a whole alternative) records
// its name ON the chosen node rather than wrapping it. That is what makes the
// label survive: pnode_child, pnode_get, and pnode_require all unwrap, so a
// wrapper would vanish exactly where lowering needs to ask which branch it got.
// Positional access and existing grammars are unaffected - nothing is inserted
// into the tree.
pub func pnode_set_branch(node *PNode, name *u8) void {
    if node == nil { return; }
    node.branch = name;
}

// Which alternative built this node? Sole dispatch primitive for a labeled
// choice; kinds and child order stay out of it.
pub func pnode_is(node *PNode, name *u8) bool {
    if node == nil || node.branch == nil { return false; }
    return streq(node.branch, name);
}

// The label itself, for reporting a branch the reader does not handle. Returns
// nil when the grammar left the alternative unlabeled.
pub func pnode_branch(node *PNode) *u8 {
    if node == nil { return nil; }
    return node.branch;
}

func pnode_kind_name(kind i64) *u8 {
    if kind == 0 { return "marker"; }
    if kind == PNODE_NUMBER { return "number"; }
    if kind == PNODE_SYMBOL { return "symbol"; }
    if kind == PNODE_STRING { return "string"; }
    if kind == PNODE_LIST { return "list"; }
    if kind == PNODE_OPERATOR { return "operator"; }
    if kind == PNODE_CAPTURE { return "capture"; }
    if kind == PNODE_TOKEN { return "token"; }
    if kind == PNODE_ERROR { return "error"; }
    if kind == PNODE_SKIPPED { return "skipped"; }
    if kind == PNODE_MISSING { return "missing"; }
    if kind == PNODE_MISMATCH { return "mismatch"; }
    return "unknown";
}

func pnode_dump_write(fd i64, text *u8) void {
    if fd == 2 { eprint(text); return; }
    var len i64 = strlen(text);
    var written i64 = 0;
    while written < len {
        var count i64 = file_write(fd, text + written, len - written);
        if count <= 0 { exit(1); }
        written = written + count;
    }
}

func pnode_dump_int(fd i64, value i64) void {
    var buffer *u8 = alloc(32);
    var len i64 = itoa(value, buffer); *(buffer + len) = 0;
    pnode_dump_write(fd, buffer);
}

pub func pnode_dump_text_to(fd i64, text *u8) void {
    pnode_dump_write(fd, "\"");
    var p *u8 = text;
    while p != nil && *p != 0 {
        var c i64 = *p;
        if c == 34 { pnode_dump_write(fd, "\\\""); }
        else if c == 92 { pnode_dump_write(fd, "\\\\"); }
        else if c == 10 { pnode_dump_write(fd, "\\n"); }
        else if c == 13 { pnode_dump_write(fd, "\\r"); }
        else if c == 9 { pnode_dump_write(fd, "\\t"); }
        else {
            var byte u8 = c;
            if fd == 2 { eprint_buf(&byte, 1); } else { file_write(fd, &byte, 1); }
        }
        p = p + 1;
    }
    pnode_dump_write(fd, "\"");
}

pub func pnode_dump_to(fd i64, node *PNode, depth i64) void {
    var i i64 = 0;
    while i < depth {
        pnode_dump_write(fd, "  ");
        i = i + 1;
    }
    if node == nil {
        pnode_dump_write(fd, "nil\n");
        return;
    }

    pnode_dump_write(fd, pnode_kind_name(node.kind));
    if node.branch != nil {
        pnode_dump_write(fd, " <");
        pnode_dump_write(fd, node.branch);
        pnode_dump_write(fd, ">");
    }
    if node.text != nil {
        pnode_dump_write(fd, " ");
        pnode_dump_text_to(fd, node.text);
    }
    pnode_dump_write(fd, " @");
    pnode_dump_int(fd, node.start);
    pnode_dump_write(fd, ":");
    pnode_dump_int(fd, node.end);
    pnode_dump_write(fd, "\n");

    if node.children == nil { return; }
    var count i64 = vec_len(node.children);
    i = 0;
    while i < count {
        pnode_dump_to(fd, vec_get(node.children, i), depth + 1);
        i = i + 1;
    }
}

// Print the generated parse tree to stderr without changing a reader's AST
// output. Capture wrappers are deliberately visible: this is a lowering aid,
// not the transparent positional view exposed by pnode_child.
pub func pnode_dump(node *PNode) void {
    pnode_dump_to(2, node, 0);
}

func pnode_dump_text(text *u8) void { pnode_dump_text_to(2, text); }
func pnode_dump_at(node *PNode, depth i64) void { pnode_dump_to(2, node, depth); }

// A lowering boundary must reject the whole tree if any recovery marker exists.
pub func pnode_has_error(node *PNode) bool {
    if node == nil { return false; }
    if node.kind >= PNODE_ERROR && node.kind <= PNODE_MISMATCH { return true; }
    if node.children != nil {
        var i i64 = 0;
        var count i64 = vec_len(node.children);
        // Checked rule wrappers carry private metadata after the parsed child.
        if node.kind == PNODE_CAPTURE && node.text != nil && streq(node.text, "@rule") && count > 1 { count = 1; }
        while i < count {
            if pnode_has_error(vec_get(node.children, i)) { return true; }
            i = i + 1;
        }
    }
    return false;
}

std/capture_contract.lang:
// Syntax-only capture contracts. PNode's six-field layout is unchanged. Internal
// capture wrappers are transparent to the legacy positional/named APIs.
require "std/pnode"

struct CaptureSpec {
    minimum i64;
    maximum i64; // -1 means unbounded
    mode i64;    // 1 required, 2 optional, 3 repeated
}

func capture_spec(minimum i64, maximum i64) *CaptureSpec {
    var spec *CaptureSpec = alloc(24);
    spec.minimum = minimum;
    spec.maximum = maximum;
    spec.mode = 1;
    if minimum == 0 { spec.mode = 2; }
    if maximum == -1 || maximum > 1 { spec.mode = 3; }
    return spec;
}

// Private wrapper slots: parsed tree, rule name, alternative index. The first
// child remains the transparent PNode view; metadata is never a guest token.
func capture_tree(node *PNode, rule *u8, alternative i64) *PNode {
    if node == nil { return nil; }
    var tree *PNode = pnode_capture("@rule", node);
    vec_push(tree.children, pnode_atom(0, rule));
    vec_push(tree.children, pnode_new(alternative));
    tree.branch = node.branch;
    return tree;
}

func capture_many(node *PNode) *PNode {
    if node == nil { return nil; }
    return pnode_capture("@many", node);
}

func capture_branch(node *PNode, label *u8) void {
    pnode_set_branch(node, label);
    pnode_set_branch(pnode_unwrap(node), label);
}

func capture_fail(rule *u8, name *u8, message *u8) void {
    eprint("reader-author capture contract: rule '");
    eprint(rule);
    eprint("', capture '");
    eprint(name);
    eprint("': ");
    eprintln(message);
    exit(1);
}

func capture_alternative(node *PNode, rule *u8, name *u8) i64 {
    if node == nil || node.kind != PNODE_CAPTURE || node.text == nil ||
       !streq(node.text, "@rule") || node.children == nil || vec_len(node.children) != 3 {
        capture_fail(rule, name, "expected checked rule tree");
    }
    var declared *PNode = vec_get(node.children, 1);
    if declared == nil || declared.text == nil || !streq(declared.text, rule) {
        capture_fail(rule, name, "tree belongs to another rule");
    }
    var alternative *PNode = vec_get(node.children, 2);
    if alternative == nil { capture_fail(rule, name, "missing alternative"); }
    return alternative.kind;
}

// Search only this rule's lexical captures, including nested groups. Referenced
// rules are opaque, even when they reuse the same capture names recursively.
func capture_collect(node *PNode, rule *u8, name *u8, matches *u8) void {
    if node == nil { return; }
    if node.kind == PNODE_CAPTURE {
        if node.text != nil && streq(node.text, "@rule") { return; }
        if node.children == nil || vec_len(node.children) != 1 {
            if node.text != nil && streq(node.text, name) {
                capture_fail(rule, name, "invalid capture payload");
            }
            return;
        }
        var child *PNode = vec_get(node.children, 0);
        if node.text != nil && streq(node.text, name) {
            if child != nil && child.kind == PNODE_CAPTURE && child.text != nil &&
               streq(child.text, "@many") {
                var list *PNode = pnode_unwrap(child);
                if list == nil || list.kind != PNODE_LIST || list.children == nil {
                    capture_fail(rule, name, "invalid repeated capture payload");
                }
                var i i64 = 0;
                while i < vec_len(list.children) {
                    vec_push(matches, vec_get(list.children, i));
                    i = i + 1;
                }
            } else { vec_push(matches, child); }
        }
        capture_collect(child, rule, name, matches);
        return;
    }
    if node.children == nil { return; }
    var i i64 = 0;
    while i < vec_len(node.children) {
        capture_collect(vec_get(node.children, i), rule, name, matches);
        i = i + 1;
    }
}

func capture_checked(node *PNode, rule *u8, name *u8,
                     spec *CaptureSpec, mode i64) *u8 {
    capture_alternative(node, rule, name);
    if spec == nil { capture_fail(rule, name, "not declared in this alternative"); }
    if spec.mode != mode { capture_fail(rule, name, "accessor cardinality differs from grammar"); }
    var matches *u8 = vec_new(4);
    capture_collect(vec_get(node.children, 0), rule, name, matches);
    var count i64 = vec_len(matches);
    if count < spec.minimum || (spec.maximum >= 0 && count > spec.maximum) {
        capture_fail(rule, name, "tree cardinality differs from grammar");
    }
    var i i64 = 0;
    while i < count {
        vec_set(matches, i, capture_value(vec_get(matches, i), rule, name));
        i = i + 1;
    }
    return matches;
}

func capture_value(node *PNode, rule *u8, name *u8) *PNode {
    var checked *PNode = nil;
    while node != nil && node.kind == PNODE_CAPTURE {
        if node.text == nil || node.children == nil || vec_len(node.children) == 0 {
            capture_fail(rule, name, "invalid capture payload");
        }
        // Validate through rule wrappers but preserve the first one for nested
        // checked access. Even a present optional/repeated value must be nonnil.
        if checked == nil && streq(node.text, "@rule") { checked = node; }
        node = vec_get(node.children, 0);
    }
    if node == nil { capture_fail(rule, name, "nil capture payload"); }
    if checked != nil { return checked; }
    return node;
}

func capture_one(matches *u8) *PNode {
    if vec_len(matches) == 0 { return nil; }
    // Keep checked rule wrappers so nested rule access remains possible. Ordinary
    // nested captures are transparent just as they are in pnode_require.
    return vec_get(matches, 0);
}

std/reader_request.lang:
// Private request state. Native workers import it from the compiler's request.
// The compiler supplies the output target directly for embedded readers.
var reader_request_inspect_stage *u8 = nil;
var reader_request_output_target *u8 = nil;

func reader_request_init() void {
    reader_request_inspect_stage = getenv("LANG_INSPECT_STAGE");
    reader_request_output_target = getenv("LANG_STAGE_OUTPUT_TARGET");
}

std/parser_inspect.lang:
// Opt-in generated parser boundary. The actual reader supplies its tokenizer,
// including comment policy or a custom token stream. No replacement scanner.
include "std/reader_request.lang"
var parser_inspect_depth i64 = 0;

func parser_inspect_begin(t *Tokenizer) void {
    var stage *u8 = reader_request_inspect_stage;
    if stage == nil { return; }
    parser_inspect_depth = parser_inspect_depth + 1;
    if !streq(stage, "tokens") || parser_inspect_depth != 1 { return; }
    print("LANG-INSPECT/1 tokens\n");
    while !tok_eof(t) {
        if t.comment_error >= 0 {
            tok_expect_end(t); tok_print_error(t, getenv("LANG_INSPECT_READER")); exit(1);
        }
        print("token "); print_int(tok_kind(t)); print(" ");
        pnode_dump_text_to(1, tok_text(t));
        print(" @"); print_int(tok_start_offset(t)); print(":");
        print_int(tok_end_offset(t)); print("\n");
        tok_next(t);
    }
    if !tok_expect_end(t) { tok_print_error(t, getenv("LANG_INSPECT_READER")); exit(1); }
    exit(0);
}

func parser_inspect_end(t *Tokenizer, tree *PNode, rule *u8) void {
    var stage *u8 = reader_request_inspect_stage;
    if stage == nil { return; }
    parser_inspect_depth = parser_inspect_depth - 1;
    if !streq(stage, "tree") || parser_inspect_depth != 0 { return; }
    var complete bool = false;
    if tree != nil { complete = tok_expect_end(t); }
    if !complete { tok_print_error(t, getenv("LANG_INSPECT_READER")); exit(1); }
    print("LANG-INSPECT/1 tree\n");
    pnode_dump_to(1, tree, 0);
    exit(0);
}

