example/tiny/tiny.lang:
// The smallest useful reader: `answer 42` becomes a complete native program.

include "std/tok.lang"
include "std/ast.lang"

reader tiny(text *u8) *u8 {
    var tokens *Tokenizer = tok_new(text);
    if tok_kind(tokens) != TOK_IDENT || !streq(tok_text(tokens), "answer") {
        tok_note_expected(tokens, "answer");
        tok_print_error(tokens, "tiny");
        return nil;
    }
    tok_next(tokens);
    if tok_kind(tokens) != TOK_NUMBER {
        tok_note_expected(tokens, "number");
        tok_print_error(tokens, "tiny");
        return nil;
    }

    var value *u8 = tok_text(tokens);
    tok_next(tokens);
    if !tok_eof(tokens) {
        tok_note_expected(tokens, "end of input");
        tok_print_error(tokens, "tiny");
        return nil;
    }

    return ast_main_i64(ast_number(value));
}

example/tree/tree.lang:
include "std/parser_runtime.lang"
include "std/ast.lang"

// Change ':' to '+' and right to result (including the lookup below),
// then try 10+42. Source-only edits reuse the compiled reader.
#parser{
    debug_program = left:number ':' right:number
}

reader pdebug(text *u8) *u8 {
    var tokens *Tokenizer = tok_new(text);
    var tree *PNode = parse_debug_program(tokens);
    var complete bool = false;
    if tree != nil { complete = tok_expect_end(tokens); }
    if !complete {
        tok_print_error(tokens, "source.read"); return nil;
    }
    pnode_dump(tree);
    var right *PNode = pnode_require(tree, "right");
    if right == nil { return nil; }
    return ast_main_i64(ast_span(ast_number(right.text), right.start, right.end));
}

example/calc/calc.lang:
// A small reader with a real grammar: `answer (2 + 3) * 4`.

include "std/tok.lang"
include "std/ast.lang"
include "std/prec.lang"

// The whole precedence ladder, loosest level first. A new binary operator is
// one entry here; `prec_right` would make a level right-associative.
func calc_table() *PrecTable {
    var t *PrecTable = prec_new();
    prec_left(t, "+ -");
    prec_left(t, "* / %");
    return t;
}

func calc_primary(tokens *Tokenizer) *u8 {
    if tok_kind(tokens) == TOK_NUMBER {
        var value *u8 = ast_number(tok_text(tokens));
        tok_next(tokens);
        return value;
    }

    if tok_match(tokens, TOK_LPAREN) {
        var expr *u8 = calc_expr(tokens);
        if expr == nil { return nil; }
        if !tok_expect(tokens, TOK_RPAREN) {
            eprintln("calc: expected `)`");
            return nil;
        }
        return expr;
    }

    eprintln("calc: expected a number or `(`");
    return nil;
}

// The table decides where each operator binds; this loop only has to read
// operands and operators in source order.
func calc_expr(tokens *Tokenizer) *u8 {
    var table *PrecTable = calc_table();
    var expr *PrecExpr = prec_expr(table);

    var first *u8 = calc_primary(tokens);
    if first == nil { return nil; }
    prec_operand(expr, first);

    while prec_of(table, tok_text(tokens)) > 0 {
        prec_op(expr, tok_text(tokens));
        tok_next(tokens);
        var right *u8 = calc_primary(tokens);
        if right == nil { return nil; }
        prec_operand(expr, right);
    }
    return prec_build(expr);
}

reader calc(text *u8) *u8 {
    var tokens *Tokenizer = tok_new(text);
    if tok_kind(tokens) != TOK_IDENT || !streq(tok_text(tokens), "answer") {
        eprintln("calc: expected `answer EXPRESSION`");
        return nil;
    }
    tok_next(tokens);

    var value *u8 = calc_expr(tokens);
    if value == nil { return nil; }
    if !tok_eof(tokens) {
        eprintln("calc: unexpected token after expression");
        return nil;
    }

    var body *u8 = ast_block1(ast_return(value));
    return ast_program1(ast_func("main", ast_vec(), ast_type_i64(), body));
}

example/c/c.lang:
// ============================================================
// c - A C-subset reader (capture real C, compile to native)
// ============================================================
//
// Proves the reader-authorship thesis on a REAL language: a subset of C
// maps almost 1:1 onto lang's C-like AST. Built with #parser{} (the crown
// jewel, Level 3) for parsing, plus a converter that lowers the parse tree to
// lang AST via the std/ast.lang builder API (Level 1) - NO hand-written S-expr
// strings. The converter does operator precedence-climbing.
//
//   #c{ int factorial(int n) { if (n < 2) return 1; return n * factorial(n - 1); } }
//
// Then factorial() is a normal native function, callable from lang.
//
// SUBSET (deliberately bounded - no typedef/preprocessor/declarators):
//   types:      int, char, void (int/char->i64/u8), pointers (T*), struct Name
//   decls:      structs (struct N { ... };), funcs, local decls (init optional)
//   statements: return, if/else, while, for, assignment, blocks, expr statements
//   operators:  + - * / %  < > <= >= == != && ||, unary - ! ~ * &, ternary ?:,
//               calls f(a,b), member access p.f and (*p).f  (-> lexed as .)
//   strings:    "..." literals (char*); funcs may return non-struct types only
//
// rdgen handles ordered alternatives transactionally. This grammar still uses
// keyword-led named statement rules because that shape is easy to inspect and
// produces smaller parse trees. Operator precedence is flat in the grammar and
// resolved here.

// require (not include) so the -r composition path can filter them: the kernel
// already carries std/core and std/tok, and this lets `kernel -r c c.ast`
// build a standalone C compiler without duplicating their declarations.
require "std/core"
require "std/tok"
include "std/parser_reader.lang"
include "std/ast.lang"
include "std/prec.lang"

// All rules are c_-prefixed: bare names like program/type/block/primary would
// generate parse_program/parse_type/... which COLLIDE with the compiler's own
// parser functions (pulled in transitively via lang_reader).
#parser{
    c_program    = c_topdecl+
    c_topdecl    = struct:c_structdef | enum:c_enumdef | var:c_topvar
    c_topvar     = type:c_rettype name:symbol tail:c_topvartail
    c_topvartail = func:c_functail | global:c_globaltail
    c_functail   = '(' params:c_params ')' body:c_block
    c_globaltail = dims:c_arrdim init:c_initopt ';'
    c_structdef  = 'struct' name:symbol '{' fields:c_fields '}' ';'
    c_fields     = c_field*
    c_field      = type:c_ptype name:symbol ';'
    c_enumdef    = 'enum' c_enumtag '{' items:c_enumitems '}' ';'
    c_enumtag    = c_tagname*
    c_tagname    = symbol
    c_enumitems  = c_enumitem*
    c_enumitem   = member:c_enummember | ','
    c_enummember = name:symbol value:c_enumvalopt
    c_enumvalopt = c_enumval*
    c_enumval    = '=' value:number
    c_rettype    = type:c_basetype stars:c_stars
    c_ptype      = type:c_anytype stars:c_stars
    c_anytype    = base:c_basetype | struct:c_structtype | enum:c_enumtype
    c_basetype   = 'int' | 'char' | 'void'
    c_structtype = 'struct' name:symbol
    c_enumtype   = 'enum' name:symbol
    c_stars      = c_star*
    c_star       = '*'
    c_params     = c_paramitem*
    c_paramitem  = param:c_param | ','
    c_param      = type:c_ptype name:symbol
    c_block     = '{' stmts:c_stmt* '}'
    c_stmt      = ret:c_retstmt | if:c_ifstmt | while:c_whilestmt | for:c_forstmt | switch:c_switchstmt | break:c_breakstmt | continue:c_continuestmt | decl:c_decl | block:c_block | expr:c_exprstmt
    c_switchstmt = 'switch' '(' scrut:c_expr ')' '{' items:c_switchitems '}'
    c_switchitems = c_switchitem*
    c_switchitem = case:c_caseval | default:c_defaultlabel | c_stmt
    c_caseval    = 'case' value:c_expr ':'
    c_defaultlabel = 'default' ':'
    c_breakstmt = 'break' ';'
    c_continuestmt = 'continue' ';'
    c_retstmt   = 'return' value:c_expr ';'
    c_ifstmt    = 'if' '(' cond:c_expr ')' then:c_stmt elses:c_elses
    c_elses     = c_elsepart*
    c_elsepart  = 'else' body:c_stmt
    c_whilestmt = 'while' '(' cond:c_expr ')' body:c_stmt
    c_forstmt   = 'for' '(' init:c_forinit cond:c_expr ';' step:c_expr ')' body:c_stmt
    c_forinit   = decl:c_decl | expr:c_exprstmt
    c_decl      = type:c_ptype name:symbol dims:c_arrdim init:c_initopt ';'
    c_arrdim    = c_dim*
    c_dim       = '[' size:number ']'
    c_initopt   = c_initval*
    c_initval   = '=' value:c_expr
    c_exprstmt  = value:c_expr ';'
    c_expr      = bin:c_binexpr tern:c_terntail*
    c_terntail  = '?' then:c_expr ':' alt:c_expr
    c_binexpr   = first:c_unary rest:c_oprest*
    c_oprest    = op:operator right:c_unary?
    c_unary     = neg:c_neg | postfix:c_postfix
    c_neg       = op:operator operand:c_postfix
    c_postfix   = primary:c_primary ops:c_postfixop*
    c_postfixop = call:c_callargs | member:c_member | index:c_index
    c_callargs  = '(' args:c_args ')'
    c_member    = '.' name:symbol | '->' name:symbol
    c_index     = '[' index:c_expr ']'
    c_args      = c_argitem*
    c_argitem   = arg:c_expr | ','
    c_primary   = num:number | str:string | sym:symbol | paren:c_parenexpr
    c_parenexpr = '(' inner:c_expr ')'
}

// PNode kinds: 1=number, 2=symbol, 3=string, 4=list/sequence, 5=operator, 0=literal marker

var c_src *u8 = nil;

// ============================================================
// Operator precedence (higher binds tighter)
// ============================================================

// C's ladder, loosest level first. The tokenizer already lexes the 2-char
// operators (==, !=, <=, >=, &&, ||, <<, >>) and carries their text, so they
// only need a level here. Assignment leads: it is the loosest thing C has, it
// associates to the right, and each `<op>=` lowers to `lv = lv <op> rhs`
// because `<op>` is declared below. An operator with no declared level is
// refused rather than guessed at.
func c_table() *PrecTable {
    var t *PrecTable = prec_new();
    prec_assign(t, "= += -= *= /= %=");
    prec_left(t, "||");
    prec_left(t, "&&");
    prec_left(t, "|");
    prec_left(t, "^");
    prec_left(t, "&");
    prec_left(t, "== !=");
    prec_left(t, "< > <= >=");
    prec_left(t, "<< >>");
    prec_left(t, "+ -");
    prec_left(t, "* / %");
    return t;
}

// ============================================================
// Expression emission (precedence climbing over a flat operand/op list)
// ============================================================

// std/prec.lang already named the operator it refused, so this only has to stop.
func c_checked(value *u8, node *PNode) *u8 {
    if value == nil {
        pnode_print_error(node, c_src, "c", "this expression is not in the C subset");
        exit(1);
    }
    return value;
}

func c_refused(what *u8, op *PNode) void {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "'");
    sb_str(sb, op.text);
    sb_str(sb, "' ");
    sb_str(sb, what);
    pnode_print_error(op, c_src, "c", sb_finish(sb));
    exit(1);
}

// One c_oprest = op:operator right:c_unary?. The right operand is optional so a
// postfix `i++` can be a whole statement (see try_incdec); anywhere else an
// operator with no right operand is not a binary operator and has no value, so
// refuse it. Dropping it is how `x = i++` used to compile as `x = i`.
func c_push_oprest(expr *PrecExpr, item *PNode) void {
    var op *PNode = pnode_require(item, "op");
    var right *PNode = pnode_get(item, "right");
    if right == nil {
        c_refused("has no value here; use it as a statement of its own", op);
    }
    prec_op(expr, op.text);
    prec_operand(expr, emit_operand_str(right));
}

// c_binexpr = first:c_unary rest:c_oprest*. Push operands and operators in
// source order from rest[from] on, and let the table shape the tree.
func c_push_flat(expr *PrecExpr, first *PNode, rest *PNode, from i64) void {
    prec_operand(expr, emit_operand_str(first));
    var n i64 = vec_len(rest.children);
    var i i64 = from;
    while i < n {
        var item *PNode = vec_get(rest.children, i);
        c_push_oprest(expr, item);
        i = i + 1;
    }
}

// Index of the last assignment operator in rest, or -1. `?:` binds tighter than
// assignment, so this is where a ternary tail belongs.
func c_last_assign(table *PrecTable, rest *PNode) i64 {
    var n i64 = vec_len(rest.children);
    var at i64 = 0 - 1;
    var i i64 = 0;
    while i < n {
        var item *PNode = vec_get(rest.children, i);
        var op *PNode = pnode_require(item, "op");
        if prec_is_assign(table, op.text) != 0 { at = i; }
        i = i + 1;
    }
    return at;
}

// A c_expr is `c_binexpr c_terntail*`: build the binexpr value, then fold any
// ternary tail around it. In value position an assignment operator has no tree
// to lower to, and prec_build says so instead of building one.
func emit_expr_str(e *PNode) *u8 {
    var binexpr *PNode = pnode_require(e, "bin");
    var terntail *PNode = pnode_require(e, "tern");
    var expr *PrecExpr = prec_expr(c_table());
    c_push_flat(expr, pnode_require(binexpr, "first"),
                pnode_require(binexpr, "rest"), 0);
    var base *u8 = c_checked(prec_build(expr), e);
    if vec_len(terntail.children) > 0 {
        return emit_ternary(base, vec_get(terntail.children, 0));
    }
    return base;
}

// Per-node-unique temp name (block/block_expr vars leak to the enclosing scope,
// so ternary temps and switch scrutinees each need their own; derive it from the
// node's source byte offset). Distinct prefixes separate each use.
func c_gensym(prefix *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var offset i64 = node.start;
    sb_int(sb, offset);
    return sb_finish(sb);
}

func ternary_tmp(node *PNode) *u8 {
    return c_gensym("__ct", node);
}

// `cond ? a : b` -> a value-returning block_expr (only the taken branch runs):
//   { var t = 0; if (cond) { t = a; } else { t = b; }  t }
// tt is a c_terntail. The temp is i64, which covers the bounded subset's int
// and pointer values.
func emit_ternary(cond *u8, tt *PNode) *u8 {
    var t *u8 = ternary_tmp(tt);
    var thenexpr *u8 = emit_expr_str(pnode_require(tt, "then"));
    var elseexpr *u8 = emit_expr_str(pnode_require(tt, "alt"));
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
    ast_push(stmts, ast_if(cond,
                           ast_block1(ast_assign(ast_ident(t), thenexpr)),
                           ast_block1(ast_assign(ast_ident(t), elseexpr))));
    return ast_block_expr(stmts, ast_ident(t));
}

// A branch the grammar can produce but this converter does not handle is a
// reader bug. Name it and stop: emitting a placeholder is how a reader turns its
// own gap into a mystery in the generated program.
func c_unhandled(what *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "unhandled ");
    sb_str(sb, what);
    var label *u8 = pnode_branch(node);
    if label == nil {
        sb_str(sb, " (the grammar left this alternative unlabeled)");
    } else {
        sb_str(sb, " branch '");
        sb_str(sb, label);
        sb_str(sb, "'");
    }
    pnode_print_error(node, c_src, "c", sb_finish(sb));
    exit(1);
    return nil;
}

// c_unary = neg:c_neg | postfix:c_postfix. The grammar names the alternative
// that matched, so lowering asks it instead of inspecting the first child's kind.
func emit_operand_str(node *PNode) *u8 {
    if pnode_is(node, "neg") {
        var f *PNode = pnode_require(node, "op");
        var operand *u8 = emit_postfix_str(pnode_require(node, "operand"));
        if streq(f.text, "~") {               // ~x == x ^ -1 (kernel has no unary ~)
            return ast_binop("^", operand, ast_unop("-", ast_int(1)));
        }
        return ast_unop(f.text, operand);
    }
    if pnode_is(node, "postfix") { return emit_postfix_str(node); }
    return c_unhandled("operand", node);
}

// If `primary` is a parenthesized lone deref `(*X)`, return the c_postfix node X
// being dereferenced; else nil. Used to peel C's explicit deref before a member
// access (see emit_postfix_str).
func deref_paren_inner(primary *PNode) *PNode {
    if !pnode_is(primary, "paren") { return nil; }
    var inner *PNode = pnode_require(primary, "inner");
    if vec_len(pnode_require(inner, "tern").children) != 0 { return nil; }  // not a lone deref
    var binexpr *PNode = pnode_require(inner, "bin");
    if vec_len(pnode_require(binexpr, "rest").children) != 0 { return nil; } // lone unary only
    var u *PNode = pnode_require(binexpr, "first");
    if !pnode_is(u, "neg") { return nil; }
    var u0 *PNode = pnode_require(u, "op");
    if streq(u0.text, "*") {
        return pnode_require(u, "operand");           // the c_postfix being deref'd
    }
    return nil;
}

func arli_c_call_args_fail(message *u8, node *PNode) void {
    pnode_print_error(node, c_src, "c", message);
    exit(1);
}

// postfix = primary postfixop*  ->  fold the chain left-to-right. Each op is a
// call (c_callargs = ['(', args, ')'], so children[1] is the args list, kind 4)
// or a member access (c_member = ['.', name], so children[1] is the name, kind 2).
func emit_postfix_str(pf *PNode) *u8 {
    var primary *PNode = pnode_require(pf, "primary");
    var ops *PNode = pnode_require(pf, "ops");
    var nops i64 = vec_len(ops.children);

    // C's (*p).field is lang's auto-deref p.field. When a member access follows a
    // parenthesized lone deref, peel the '*' and emit (field p ...): the kernel
    // auto-derefs pointer.field, whereas (field (unop * p) ...) would load a
    // struct value and crash.
    var base *u8 = nil;
    var peeled *PNode = nil;
    if nops > 0 {
        if pnode_is(vec_get(ops.children, 0), "member") {
            peeled = deref_paren_inner(primary);
        }
    }
    if peeled != nil {
        base = emit_postfix_str(peeled);
    } else {
        base = emit_primary_str(primary);
    }

    var oi i64 = 0;
    while oi < nops {
        var op *PNode = vec_get(ops.children, oi);
        if pnode_is(op, "member") {               // p.f / p->f -> (field base name)
            base = ast_field(base, pnode_require(op, "name").text);
        } else if pnode_is(op, "index") {         // a[i] -> (index base idx)
            base = ast_index(base, emit_expr_str(pnode_require(op, "index")));
        } else if pnode_is(op, "call") {          // f(a, b) -> (call base args...)
            var items *u8 = pnode_require(op, "args").children;
            var n i64 = vec_len(items);
            var i i64 = 0;
            var expect_arg i64 = 1;
            while i < n {
                var it *PNode = vec_get(items, i);
                if pnode_is(it, "arg") {
                    if expect_arg == 0 { arli_c_call_args_fail("expected argument separator", it); }
                    expect_arg = 0;
                } else {
                    if expect_arg == 1 { arli_c_call_args_fail("unexpected argument separator", it); }
                    expect_arg = 1;
                }
                i = i + 1;
            }
            if n > 0 && expect_arg == 1 {
                arli_c_call_args_fail("trailing argument separator", vec_get(items, n - 1));
            }
            var args *u8 = ast_vec();
            i = 0;
            while i < n {
                var it *PNode = vec_get(items, i);
                if pnode_is(it, "arg") {
                    ast_push(args, emit_expr_str(it));
                }
                i = i + 1;
            }
            base = ast_span(ast_call(base, args), primary.start, op.end);
        } else {
            return c_unhandled("postfix operator", op);
        }
        oi = oi + 1;
    }
    return base;
}

func emit_primary_str(p *PNode) *u8 {
    if pnode_is(p, "num") { return ast_number(p.text); }
    if pnode_is(p, "sym") { return ast_ident(p.text); }
    if pnode_is(p, "str") {         // one token covers "..." and '...'
        if *(p.text) == 39 {        // leading ' -> C char literal, an integer value
            return ast_int(char_literal_value(p.text));
        }
        return ast_string_raw(p.text);  // "..." string; text keeps its quotes for the kernel
    }
    if pnode_is(p, "paren") {
        return emit_expr_str(pnode_require(p, "inner"));
    }
    return c_unhandled("primary", p);
}

// Value of a C char literal token (text includes the single quotes, e.g. 'a' or
// '\n'). Handles the common backslash escapes.
func char_literal_value(text *u8) i64 {
    var c i64 = *(text + 1);       // first char after the opening quote
    if c == 92 {                   // backslash escape
        var e i64 = *(text + 2);
        if e == 110 { return 10; }     // \n
        if e == 116 { return 9; }      // \t
        if e == 114 { return 13; }     // \r
        if e == 48 { return 0; }       // \0
        if e == 92 { return 92; }      // \\
        if e == 39 { return 39; }      // \'
        return e;                      // \<other> -> literal char
    }
    return c;
}

// ============================================================
// Statement emission
// ============================================================

// c_stmt names its alternatives, so the statement says what it is. This used to
// be re-derived from a leading keyword's text and, for the two keyword-less
// forms, from how deep a 'struct' sat under the first child - which is how
// telling a declaration from an expression statement ended up being a question
// about parse-tree shape rather than about C.
//
// c_forinit labels its two alternatives `decl` and `expr` as well, so a for
// loop's initializer arrives here answering the same two questions.
func emit_stmt(s *PNode) *u8 {
    return ast_span(emit_stmt_inner(s), s.start, s.end);
}

func emit_stmt_inner(s *PNode) *u8 {
    if pnode_is(s, "block") { return emit_block(s); }
    if pnode_is(s, "break") { return ast_break(nil); }
    if pnode_is(s, "continue") { return ast_continue(nil); }
    if pnode_is(s, "ret") { return ast_return(emit_expr_str(pnode_require(s, "value"))); }
    if pnode_is(s, "if") {
        var cond *u8 = emit_expr_str(pnode_require(s, "cond"));
        var then_b *u8 = emit_stmt_as_block(pnode_require(s, "then"));
        var elses *PNode = pnode_require(s, "elses");
        var else_b *u8 = nil;
        if vec_len(elses.children) > 0 {
            var elsepart *PNode = vec_get(elses.children, 0);
            else_b = emit_stmt_as_block(pnode_require(elsepart, "body"));
        }
        return ast_if(cond, then_b, else_b);
    }
    if pnode_is(s, "while") {
        return ast_while(emit_expr_str(pnode_require(s, "cond")),
                         emit_stmt_as_block(pnode_require(s, "body")));
    }
    if pnode_is(s, "for") { return emit_for(s); }
    if pnode_is(s, "switch") { return emit_switch(s); }
    if pnode_is(s, "decl") { return emit_decl(s); }
    if pnode_is(s, "expr") {
        return emit_exprstmt_from_expr(pnode_require(s, "value"));
    }
    return c_unhandled("statement", s);
}

// Base operator for an increment/decrement op ("++" -> "+", "--" -> "-"); nil otherwise.
func incdec_base(op *u8) *u8 {
    if streq(op, "++") { return "+"; }
    if streq(op, "--") { return "-"; }
    return nil;
}

// Emit `lv = lv <base> 1` for a ++/-- statement (lvnode is a c_unary/c_postfix).
func emit_incdec(lvnode *PNode, base *u8) *u8 {
    var lv *u8 = emit_operand_str(lvnode);
    return ast_assign(lv, ast_binop(base, lv, ast_int(1)));
}

// Handle ++/-- used as a whole statement (or for-step): postfix `i++` / `i--`
// (one oprest that is a bare op) or prefix `++i` / `--i` (a c_neg with op ++/--).
// Returns the assign string if handled, else nil. ++/-- in value position is NOT
// handled here (see climb).
func try_incdec(expr *PNode) *u8 {
    var u *PNode = pnode_require(expr, "first");
    var star *PNode = pnode_require(expr, "rest");
    var ns i64 = vec_len(star.children);
    if ns == 1 {                                     // postfix: lvalue ++ / --
        var orn *PNode = vec_get(star.children, 0);
        if pnode_get(orn, "right") == nil {          // bare op, no right operand
            var opn *PNode = pnode_require(orn, "op");
            var base *u8 = incdec_base(opn.text);
            if base != nil { return emit_incdec(u, base); }
        }
    }
    if ns == 0 {                                     // prefix: ++ / -- lvalue
        if pnode_is(u, "neg") {
            var base *u8 = incdec_base(pnode_require(u, "op").text);
            if base != nil { return emit_incdec(pnode_require(u, "operand"), base); }
        }
    }
    return nil;
}

// Lower a bare c_expr as a statement, which is the one position where C's
// assignment operators are legal. ++/-- on a bare lvalue still desugars here -
// it is a statement, not an operator with a value. Shared by exprstmt and the
// for-loop step (a bare expr with no trailing ';').
//
// The one thing the table cannot see is the ternary tail, which the grammar
// keeps outside c_binexpr. `?:` binds tighter than assignment, so it wraps
// everything after the assignment operator: `a = b + c ? d : e` is
// `a = ((b + c) ? d : e)`, and that wrapped value is the assignment's operand.
func emit_exprstmt_from_expr(expr *PNode) *u8 {
    var binexpr *PNode = pnode_require(expr, "bin");
    var terntail *PNode = pnode_require(expr, "tern");
    var ntt i64 = vec_len(terntail.children);
    if ntt == 0 {                                     // ++/-- only on a bare lvalue
        var inc *u8 = try_incdec(binexpr);
        if inc != nil { return inc; }
    }

    var table *PrecTable = c_table();
    var first *PNode = pnode_require(binexpr, "first");
    var rest *PNode = pnode_require(binexpr, "rest");
    var at i64 = 0 - 1;
    if ntt > 0 { at = c_last_assign(table, rest); }

    if at < 0 {
        var whole *PrecExpr = prec_expr(table);
        c_push_flat(whole, first, rest, 0);
        if ntt == 0 { return c_checked(prec_build_stmt(whole), expr); }
        return ast_expr_stmt(emit_ternary(c_checked(prec_build(whole), expr),
                                          vec_get(terntail.children, 0)));
    }

    var last *PNode = vec_get(rest.children, at);
    var tail *PrecExpr = prec_expr(table);
    c_push_flat(tail, pnode_require(last, "right"), rest, at + 1);
    var value *u8 = emit_ternary(c_checked(prec_build(tail), pnode_require(last, "right")),
                                 vec_get(terntail.children, 0));

    var head *PrecExpr = prec_expr(table);
    prec_operand(head, emit_operand_str(first));
    var i i64 = 0;
    while i < at {
        var item *PNode = vec_get(rest.children, i);
        c_push_oprest(head, item);
        i = i + 1;
    }
    prec_op(head, pnode_require(last, "op").text);
    prec_operand(head, value);
    return c_checked(prec_build_stmt(head), expr);
}

// c_forstmt = 'for' '(' c_forinit c_expr ';' c_expr ')' c_stmt
//   children: [for, (, init, cond, ;, step, ), body]   (init consumes its ';')
// Desugar to a block: { init; while (cond) { body; step; } }.  (continue inside
// the body skips step - an accepted limitation of this bounded subset.)
func emit_for(s *PNode) *u8 {
    var init *PNode = pnode_require(s, "init");
    var cond *PNode = pnode_require(s, "cond");
    var step *PNode = pnode_require(s, "step");
    var body *PNode = pnode_require(s, "body");
    var inner *u8 = ast_vec();
    ast_push(inner, emit_stmt(body));
    ast_push(inner, emit_exprstmt_from_expr(step));
    var outer *u8 = ast_vec();
    ast_push(outer, emit_stmt(init));                       // decl or assignment (handles both)
    ast_push(outer, ast_while(emit_expr_str(cond), ast_block(inner)));
    return ast_block(outer);
}

// A c_switchitem is a 'case' label, a 'default' label, or a statement. Return
// 1=case, 2=default, 0=statement. The statement alternative is deliberately
// unlabeled: c_stmt labels its own alternatives, and one node cannot carry two
// branch names - so a statement arrives here still answering to its own label.
func switch_label_kind(it *PNode) i64 {
    if pnode_is(it, "case") { return 1; }
    if pnode_is(it, "default") { return 2; }
    return 0;
}

func switch_is_break(it *PNode) i64 {
    if pnode_is(it, "break") { return 1; }
    return 0;
}

// Finalize one case group: build its condition (svname == v1 || svname == v2 ...,
// or nil for `default`) and body block, appending both to the parallel conds/bodies.
func switch_finalize(conds *u8, bodies *u8, svname *u8, vals *u8, is_default i64, body *u8) void {
    var cond *u8 = nil;
    if is_default == 0 {
        var nv i64 = vec_len(vals);
        var j i64 = 0;
        while j < nv {
            var eq *u8 = ast_binop("==", ast_ident(svname), vec_get(vals, j));
            if cond == nil { cond = eq; }
            else { cond = ast_binop("||", cond, eq); }
            j = j + 1;
        }
    }
    vec_push(conds, cond);          // nil marks the default group
    vec_push(bodies, ast_block(body));
}

// switch (E) { case V: ... } -> evaluate E once into a temp, then an if/else-if
// chain (one arm per case group; `default` is the final else). BOUNDED: each
// case is independent - there is NO fall-through (a case body without break does
// not flow into the next). Stacked empty labels (case 2: case 3:) share one body.
// A top-level break just terminates its case (it is the idiomatic terminator).
//   c_switchstmt = ['switch','(',expr,')','{', items, '}']  -> children[2]=expr, [5]=items
func arli_c_switch_default_fail(message *u8, node *PNode) void {
    pnode_print_error(node, c_src, "c", message);
    exit(1);
}

func emit_switch(s *PNode) *u8 {
    var svname *u8 = c_gensym("__sw", s);
    var scrut *u8 = emit_expr_str(pnode_require(s, "scrut"));
    var items *PNode = pnode_require(s, "items");
    var n i64 = vec_len(items.children);

    var conds *u8 = vec_new(8);     // per group: condition string (nil = default)
    var bodies *u8 = vec_new(8);    // per group: body block string

    var pend_vals *u8 = ast_vec();  // case-value expr strings for the current stacked labels
    var pend_default i64 = 0;
    var default_seen i64 = 0;
    var pend_body *u8 = ast_vec();
    var have_body i64 = 0;          // current group has started collecting body statements?
    var have_group i64 = 0;         // any label seen for the current group?

    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items.children, i);
        var lab i64 = switch_label_kind(it);
        if lab != 0 {
            if have_body != 0 {     // a label after a body => finalize the previous group
                switch_finalize(conds, bodies, svname, pend_vals, pend_default, pend_body);
                pend_vals = ast_vec(); pend_default = 0; pend_body = ast_vec(); have_body = 0;
            }
            have_group = 1;
            if lab == 2 {
                if default_seen != 0 { arli_c_switch_default_fail("duplicate default", it); }
                default_seen = 1;
                pend_default = 1;
            }
            else { ast_push(pend_vals, emit_expr_str(pnode_require(it, "value"))); }
        } else {
            if have_group == 0 { arli_c_switch_default_fail("statement before switch label", it); }
            if switch_is_break(it) == 0 {       // drop the case-terminating break
                ast_push(pend_body, emit_stmt(it));
            }
            have_body = 1;
        }
        i = i + 1;
    }
    if have_group != 0 {
        switch_finalize(conds, bodies, svname, pend_vals, pend_default, pend_body);
    }

    // Assemble: default body is the innermost else; case arms wrap it (reverse order).
    var else_branch *u8 = nil;
    var ng i64 = vec_len(conds);
    var k i64 = 0;
    while k < ng {
        if vec_get(conds, k) == nil { else_branch = vec_get(bodies, k); }
        k = k + 1;
    }
    var idx i64 = ng - 1;
    while idx >= 0 {
        var c *u8 = vec_get(conds, idx);
        if c != nil { else_branch = ast_if(c, vec_get(bodies, idx), else_branch); }
        idx = idx - 1;
    }

    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(svname, ast_type_i64(), scrut));
    if else_branch != nil { ast_push(stmts, else_branch); }
    return ast_block(stmts);
}

// (var NAME TYPE INIT?). arrdim is a c_dim* (zero = scalar; one c_dim =
// ['[', number, ']'] = 1-D array `T[N]` -> (type_array N ELEM), no initializer).
// initopt is the stable-slot optional init for scalars (absent -> no store, as in
// C / a top-level zero). Shared by local decls and globals.
func arli_c_decl_loss_fail(message *u8, node *PNode) void {
    pnode_print_error(node, c_src, "c", message);
    exit(1);
}

func emit_var(name *PNode, typenode *PNode, arrdim *PNode, initopt *PNode) *u8 {
    if vec_len(arrdim.children) > 1 {
        arli_c_decl_loss_fail("multidimensional array", vec_get(arrdim.children, 1));
    }
    if vec_len(arrdim.children) > 0 {
        if vec_len(initopt.children) > 0 {
            arli_c_decl_loss_fail("array initializer", vec_get(initopt.children, 0));
        }
        var dim0 *PNode = vec_get(arrdim.children, 0);
        var sizenode *PNode = pnode_require(dim0, "size");
        return ast_var(name.text, ast_type_array(sizenode.text, emit_type(typenode)), nil);
    }
    if vec_len(initopt.children) > 0 {
        var initval *PNode = vec_get(initopt.children, 0);
        return ast_var(name.text, emit_type(typenode),
                       emit_expr_str(pnode_require(initval, "value")));
    }
    return ast_var(name.text, emit_type(typenode), nil);
}

func emit_decl(d *PNode) *u8 {
    return emit_var(pnode_require(d, "name"), pnode_require(d, "type"),
                    pnode_require(d, "dims"), pnode_require(d, "init"));
}

// A control-flow body must be a block; wrap a single statement if needed.
func emit_stmt_as_block(s *PNode) *u8 {
    if pnode_is(s, "block") { return emit_block(s); }
    return ast_block1(emit_stmt(s));
}

func emit_block(block *PNode) *u8 {
    var stmts *u8 = ast_vec();
    if block != nil {
        var sl *PNode = pnode_require(block, "stmts");
        var n i64 = vec_len(sl.children);
        var i i64 = 0;
        while i < n {
            ast_push(stmts, emit_stmt(vec_get(sl.children, i)));
            i = i + 1;
        }
    }
    return ast_block(stmts);
}

// ============================================================
// Declarations
// ============================================================

// c_ptype/c_rettype = anytype c_stars  ->  children [anytype, stars_star]. Each
// star wraps the base in a (type_ptr ...). c_anytype names which of its three
// alternatives matched. char -> u8 so `char*` is `*u8` (lang's string type);
// int -> i64; void -> void; struct N -> N; `enum Name` is just an int.
func emit_type(t *PNode) *u8 {
    if t == nil { return ast_type("i64"); }
    var anytype *PNode = pnode_require(t, "type");
    var stars *PNode = pnode_require(t, "stars");
    var n i64 = vec_len(stars.children);
    var base *u8 = nil;
    if pnode_is(anytype, "enum") {                // `enum Name` is just an int
        base = ast_type("i64");
    } else if pnode_is(anytype, "struct") {
        base = ast_type(pnode_require(anytype, "name").text);
    } else if streq(anytype.text, "void") {
        base = ast_type("void");
    } else if streq(anytype.text, "char") {
        base = ast_type("u8");
    } else {
        base = ast_type("i64");
    }
    var i i64 = 0;
    while i < n { base = ast_type_ptr(base); i = i + 1; }
    return base;
}

// A c_topvar whose tail is a c_functail is a function definition.
func emit_func(tv *PNode) *u8 {
    var tail *PNode = pnode_require(tv, "tail");
    return ast_span(ast_func(pnode_require(tv, "name").text,
                    emit_params(pnode_require(tail, "params")),
                    emit_type(pnode_require(tv, "type")),
                    emit_block(pnode_require(tail, "body"))), tv.start, tv.end);
}

// A c_topvar whose tail is a c_globaltail is a global (var ...).
func emit_global(tv *PNode) *u8 {
    var tail *PNode = pnode_require(tv, "tail");
    return emit_var(pnode_require(tv, "name"), pnode_require(tv, "type"),
                    pnode_require(tail, "dims"), pnode_require(tail, "init"));
}

// params = paramitem* ; paramitem = param | ',' ; param = type symbol
// Returns a vec of (param name type) for ast_func.
func arli_c_params_fail(message *u8, node *PNode) void {
    pnode_print_error(node, c_src, "c", message);
    exit(1);
}

func emit_params(params *PNode) *u8 {
    var pv *u8 = ast_vec();
    if params == nil { return pv; }
    var items *u8 = params.children;
    var names *u8 = vec_new(8);
    var n i64 = vec_len(items);
    var expect_param bool = true;
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if pnode_is(it, "param") {
            if !expect_param { arli_c_params_fail("expected parameter separator", it); }
            var pname *PNode = pnode_require(it, "name");
            var j i64 = 0;
            while j < vec_len(names) {
                if streq(vec_get(names, j), pname.text) {
                    arli_c_params_fail("duplicate parameter", pname);
                }
                j = j + 1;
            }
            vec_push(names, pname.text);
            var type_node *PNode = pnode_require(it, "type");
            var base *PNode = pnode_require(type_node, "type");
            var stars *PNode = pnode_require(type_node, "stars");
            if pnode_is(base, "base") && streq(base.text, "void") && vec_len(stars.children) == 0 {
                arli_c_params_fail("void parameter", base);
            }
            ast_push(pv, ast_param(pname.text, emit_type(type_node)));
            expect_param = false;
        } else {
            if expect_param { arli_c_params_fail("unexpected parameter separator", it); }
            expect_param = true;
        }
        i = i + 1;
    }
    if n > 0 && expect_param {
        arli_c_params_fail("trailing parameter separator", vec_get(items, n - 1));
    }
    return pv;
}

// Parse a non-negative decimal integer from text (enum value literals).
func c_atoi(s *u8) i64 {
    var n i64 = 0;
    var i i64 = 0;
    while *(s + i) != 0 {
        var c i64 = *(s + i);
        if c >= 48 {
            if c <= 57 { n = n * 10 + (c - 48); }
        }
        i = i + 1;
    }
    return n;
}

// c_enumdef = 'enum' tag '{' c_enumitems '}' ';'  ->  children [enum, tag, '{',
// items, '}', ';'].  Each member becomes a global int constant (var NAME i64 V);
// implicit values count up from 0 (or from the last explicit value + 1), so
// `enum { A, B, C }` is 0/1/2 and `enum { X = 10, Y }` is 10/11. The tag name is
// cosmetic (the kernel has no enum type; `enum Tag` lowers to i64 in emit_type).
func arli_c_enum_shape_fail(message *u8, node *PNode) void {
    pnode_print_error(node, c_src, "c", message);
    exit(1);
}

func emit_enumdef(d *PNode, decls *u8) void {
    var items *PNode = pnode_require(d, "items");
    var n i64 = vec_len(items.children);
    if n == 0 { arli_c_enum_shape_fail("empty enum", d); }
    var names *u8 = vec_new(8);
    var expect_member bool = true;
    var counter i64 = 0;
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items.children, i);   // c_enumitem = member:... | ','
        if pnode_is(it, "member") {
            if !expect_member { arli_c_enum_shape_fail("expected enum separator", it); }
            var namep *PNode = pnode_require(it, "name");
            var j i64 = 0;
            while j < vec_len(names) {
                if streq(vec_get(names, j), namep.text) {
                    arli_c_enum_shape_fail("duplicate enum member", namep);
                }
                j = j + 1;
            }
            vec_push(names, namep.text);
            var valopt *PNode = pnode_require(it, "value");   // c_enumvalopt = c_enumval*
            if vec_len(valopt.children) > 1 {
                arli_c_enum_shape_fail("repeated enum value", vec_get(valopt.children, 1));
            }
            var value i64 = counter;
            if vec_len(valopt.children) > 0 {
                var ev *PNode = vec_get(valopt.children, 0);
                var number *PNode = pnode_require(ev, "value");
                var k i64 = 0;
                if *number.text == 0 { arli_c_enum_shape_fail("decimal enum value required", number); }
                while *(number.text + k) != 0 {
                    var c i64 = *(number.text + k);
                    if c < 48 || c > 57 { arli_c_enum_shape_fail("decimal enum value required", number); }
                    k = k + 1;
                }
                value = c_atoi(number.text);
            }
            ast_push(decls, ast_var(namep.text, ast_type_i64(), ast_int(value)));
            counter = value + 1;
            expect_member = false;
        } else {
            if expect_member { arli_c_enum_shape_fail("unexpected enum separator", it); }
            expect_member = true;
        }
        i = i + 1;
    }
}

// c_structdef = 'struct' Name '{' c_fields '}' ';'  ->  children [struct, Name,
// '{', fields, '}', ';'].  Each c_field = c_ptype symbol ';'.
func emit_structdef(sd *PNode) *u8 {
    var name *PNode = pnode_require(sd, "name");
    var fields *PNode = pnode_require(sd, "fields");
    var fv *u8 = ast_vec();
    var n i64 = vec_len(fields.children);
    var i i64 = 0;
    while i < n {
        var fld *PNode = vec_get(fields.children, i);
        var fname *PNode = pnode_require(fld, "name");
        ast_push(fv, ast_field_decl(fname.text, emit_type(pnode_require(fld, "type"))));
        i = i + 1;
    }
    return ast_struct(name.text, fv);
}

// program = topdecl+. c_topdecl names struct/enum/var, and a var's c_topvartail
// names func/global - the two questions that used to be answered by whether a
// keyword sat at children[0] and whether the tail began with a '(' marker.
func emit_program(prog *PNode) *u8 {
    var decls *u8 = ast_vec();
    if prog != nil {
        var dl *u8 = prog.children;
        var n i64 = vec_len(dl);
        var i i64 = 0;
        while i < n {
            var d *PNode = vec_get(dl, i);
            if pnode_is(d, "struct") {
                ast_push(decls, emit_structdef(d));
            } else if pnode_is(d, "enum") {
                emit_enumdef(d, decls);                     // pushes one global per member
            } else if pnode_is(d, "var") {
                var tail *PNode = pnode_require(d, "tail");
                if pnode_is(tail, "func") {
                    ast_push(decls, emit_func(d));
                } else if pnode_is(tail, "global") {
                    ast_push(decls, emit_global(d));
                } else {
                    return c_unhandled("top-level declarator", tail);
                }
            } else {
                return c_unhandled("top-level declaration", d);
            }
            i = i + 1;
        }
    }
    return ast_program(decls);
}

reader c(text *u8) *u8 {
    c_src = text;
    var t *Tokenizer = tok_new(text);
    var prog *PNode = parse_c_program(t);
    // Repetition can stop at a valid prefix. Never emit that prefix as a
    // complete translation unit when a declaration failed to parse.
    if prog == nil || !tok_eof(t) {
        var token *PNode = pnode_atom(0, tok_text(t));
        token.start = tok_start_offset(t);
        token.end = tok_end_offset(t);
        pnode_print_error(token, text, "c", "unsupported or invalid C subset syntax");
        exit(1);
        return nil;
    }
    return emit_program(prog);
}

example/forth/forth.lang:
// ============================================================
// forth - a stack language whose stack vanishes at compile time
// ============================================================
//
// The fourth polyglot language, and the one furthest from the other three. C,
// minilisp and flow all have an expression grammar; Forth has none. A Forth
// program is a flat stream of whitespace-separated words that push and pop a
// data stack, and control flow is just more words:
//
//   #forth{
//       : square ( n -- n2 ) dup * ;
//       : fact   ( n -- f )  dup 2 < if drop 1 else dup 1 - recurse * then ;
//   }
//
// There is NO data stack in the generated code. The reader keeps a stack of AST
// NODES while it walks the word stream: `dup` duplicates a node, `*` pops two
// and pushes `(binop * a b)`. By `;` the stack holds the word's result and every
// trace of the stack is gone - `square` compiles to exactly the same native code
// as `func square(n i64) i64 { return n * n; }`. This mirrors how a real Forth
// compiles `if`/`then` with a compile-time control stack, except we erase the
// data stack too.
//
// The stack effect comment is LOAD-BEARING here (in real Forth it is a comment):
// `( a b -- s )` names the parameters and counts the results, which is what lets
// a word become an ordinary raw-i64 lang function callable by clients whose
// representation and ownership contracts agree, and callable back from Forth.
//
// Words:
//   : n ( ... ) ... ;   define        extern n ( ... ) ;   import a host function
//   + - * / mod         arithmetic    = <> < > <= >=       comparison (flag 0/1)
//   and or xor invert   bitwise       negate               unary minus
//   dup drop swap over nip rot        stack shuffling
//   if ... else ... then              conditional
//   recurse             self-call     .  cr                output (see runtime)
//
// Deliberate bounds (round 1): no loops (`begin`/`do`) and no `variable`/`!`/`@`,
// so a word body stays a pure expression tree and recursion is the only
// repetition. Word names must be lang identifiers plus an optional trailing `?`
// (`prime?` mangles to `prime_p`) - the shared tokenizer lexes `-` as an
// operator, so `is-prime` can't be a name. Negative literals must be written
// `0 5 -` or `5 negate`; the tokenizer splits `-5` into two words. Comments are
// `( ... )` (or lang's `//`), not `\`.
//
// Evaluation order is preserved exactly: before any word that duplicates,
// reorders, discards or emits a statement, every impure node still sitting on
// the compile-time stack is materialized into a temp (see fo_flush). Otherwise
// deferring an unevaluated call past a `.` would silently reorder side effects.
//
// Converter helpers are fo_-prefixed so forth composes with the C, minilisp and
// flow readers in one binary (no symbol collisions).

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"
include "std/reader_exports.lang"

// The grammar is almost nothing - which is the point. A body is a FLAT word
// list; `if`/`else`/`then` are ordinary words that the converter gives meaning
// to, exactly as Forth does with immediate words. There is deliberately no
// expression grammar: nesting is meaning assigned later by the reader.
#parser{
    fo_program   = fo_def+
    fo_def       = word:fo_worddef | extern:fo_externdef | comment:fo_effect
    fo_worddef   = ':' name:fo_name effect:fo_effect body:fo_body ';'
    fo_externdef = 'extern' name:fo_name effect:fo_effect ';'
    fo_name      = sym:symbol marks:fo_qmark*
    fo_qmark     = '?'
    fo_effect    = '(' items:fo_eitem* ')'
    fo_eitem     = sym:symbol | op:operator | num:number
    fo_body      = fo_word*
    fo_word      = name:fo_name | num:number | op:operator | comment:fo_effect | dot:'.'
}

// PNode kinds: 0=literal marker (carries its text), 1=number, 2=symbol,
// 4=list/seq, 5=operator.

var fo_src *u8 = nil;
var fo_label *u8 = "forth";

// ============================================================
// Comments
// ============================================================

func fo_word_char(c i64) i64 {
    if c >= 48 && c <= 57 { return 1; }         // 0-9
    if c >= 65 && c <= 90 { return 1; }         // A-Z
    if c >= 97 && c <= 122 { return 1; }        // a-z
    if c == 95 { return 1; }                    // _
    if c == 45 { return 1; }                    // -  (keeps the `--` separator)
    return 0;
}

// A Forth comment is `( ... )` and, being a comment, may contain anything at
// all - but the shared tokenizer would choke on a `:` or a quote inside one and
// silently derail the parse. Real Forth never tokenizes a comment's contents;
// we can't skip them entirely (the stack effect wears the same parentheses and
// IS parsed), so instead sanitize every parenthesized interior down to word
// characters. A comment can then say what it likes, while a stack effect - just
// names plus the `--` separator - still reads exactly as before.
//
// `\\` line comments are passed through untouched (the tokenizer strips them),
// so a `(` inside one can't be mistaken for the start of a Forth comment.
func fo_sanitize_comments(text *u8) *u8 {
    var sb *StringBuilder = sb_new();
    var p *u8 = text;
    var depth i64 = 0;
    while *p != 0 {
        var c i64 = *p;
        if depth == 1 {
            if c == 41 {                        // )
                depth = 0;
                sb_char(sb, c);
            } else if fo_word_char(c) == 1 {
                sb_char(sb, c);
            } else {
                sb_char(sb, 32);
            }
        } else if c == 40 {                     // (
            depth = 1;
            sb_char(sb, c);
        } else if c == 92 {                     // \ to end of line
            while *p != 0 && *p != 10 {
                sb_char(sb, *p);
                p = p + 1;
            }
            if *p == 0 { return sb_finish(sb); }
            sb_char(sb, *p);
        } else {
            sb_char(sb, c);
        }
        p = p + 1;
    }
    return sb_finish(sb);
}

// ============================================================
// Names and stack effects
// ============================================================

// fo_name = symbol fo_qmark*. Forth loves `?` in names (`prime?`); lang has no
// such identifier, so each trailing `?` becomes `_p`.
func fo_name_text(n *PNode) *u8 {
    var sym *PNode = pnode_require(n, "sym");
    var qs *PNode = pnode_require(n, "marks");
    var nq i64 = vec_len(qs.children);
    if nq == 0 { return sym.text; }
    var sb *StringBuilder = sb_new();
    sb_str(sb, sym.text);
    var i i64 = 0;
    while i < nq {
        sb_str(sb, "_p");
        i = i + 1;
    }
    return sb_finish(sb);
}

// The word at index i, if it is a name word (else nil) - for peeking at the
// `else`/`then` terminators without consuming them.
func fo_word_at(items *u8, i i64) *u8 {
    if i >= vec_len(items) { return nil; }
    var it *PNode = vec_get(items, i);
    if !pnode_is(it, "name") { return nil; }
    return fo_name_text(it);
}

// `( a b -- s )` -> push "a","b" onto pnames, return the result count. The `--`
// arrives as a single 2-char operator atom (the tokenizer lexes it for C's `--`).
func fo_effect_split(eff *PNode, pnames *u8) i64 {
    var star *PNode = pnode_require(eff, "items");
    var items *u8 = star.children;
    var n i64 = vec_len(items);
    var past i64 = 0;
    var nres i64 = 0;
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if pnode_is(it, "op") {
            if !streq(it.text, "--") || past == 1 {
                fo_fail("invalid stack effect", nil, it);
            }
            past = 1;
        } else if pnode_is(it, "sym") {
            if past == 1 {
                if nres == 1 { fo_fail("invalid stack effect", nil, it); }
                nres = nres + 1;
            } else {
                var j i64 = 0;
                while j < vec_len(pnames) {
                    var name *u8 = vec_get(pnames, j);
                    if streq(name, it.text) { fo_fail("invalid stack effect", nil, it); }
                    j = j + 1;
                }
                vec_push(pnames, it.text);
            }
        } else {
            fo_fail("invalid stack effect", nil, it);
        }
        i = i + 1;
    }
    if past == 0 { fo_fail("invalid stack effect", nil, eff); }
    return nres;
}

// A top-level item is a `:` definition (1), an `extern` declaration (2), or a
// bare ( ... ) comment between definitions (0).
func fo_def_kind(d *PNode) i64 {
    if pnode_is(d, "extern") { return 2; }
    if pnode_is(d, "word") { return 1; }
    return 0;                                   // comment:fo_effect
}

// Signatures are a flat vec of (name, nparams, nresults) triples, collected in a
// pre-pass and threaded as a parameter.
func fo_collect_sigs(prog *PNode) *u8 {
    var sigs *u8 = vec_new(24);
    var defs *u8 = prog.children;
    var n i64 = vec_len(defs);
    var i i64 = 0;
    while i < n {
        var d *PNode = vec_get(defs, i);
        if fo_def_kind(d) == 0 {
            i = i + 1;
            continue;
        }
        var namen *PNode = pnode_require(d, "name");
        var eff *PNode = pnode_require(d, "effect");
        var pnames *u8 = vec_new(8);
        var nres i64 = fo_effect_split(eff, pnames);
        vec_push(sigs, fo_name_text(namen));
        vec_push(sigs, vec_len(pnames));
        vec_push(sigs, nres);
        i = i + 1;
    }
    return sigs;
}

func fo_sig_find(sigs *u8, name *u8) i64 {
    var n i64 = vec_len(sigs);
    var i i64 = 0;
    while i < n {
        var nm *u8 = vec_get(sigs, i);
        if streq(nm, name) { return i; }
        i = i + 3;
    }
    return 0 - 1;
}

// ============================================================
// The compile-time stack (of AST nodes)
// ============================================================

// A reported error must end the build. It used not to: `: bad ( -- n ) + ;`
// printed "stack underflow" four times and then wrote a working-looking program
// whose word returned whatever `ast_int(0)` stood in for.
func fo_fail(msg *u8, what *u8, node *PNode) void {
    var sb *StringBuilder = sb_new();
    sb_str(sb, msg);
    if what != nil {
        sb_str(sb, " '");
        sb_str(sb, what);
        sb_str(sb, "'");
    }
    pnode_print_error(node, fo_src, fo_label, sb_finish(sb));
    exit(1);
}

func fo_pop(stack *u8, node *PNode) *u8 {
    if vec_len(stack) == 0 {
        fo_fail("stack underflow", nil, node);
    }
    return vec_pop(stack);
}

func fo_stack_copy(src *u8) *u8 {
    var d *u8 = vec_new(16);
    var n i64 = vec_len(src);
    var i i64 = 0;
    while i < n {
        vec_push(d, vec_get(src, i));
        i = i + 1;
    }
    return d;
}

func fo_stack_load(dst *u8, src *u8) void {
    while vec_len(dst) > 0 { vec_pop(dst); }
    var n i64 = vec_len(src);
    var i i64 = 0;
    while i < n {
        vec_push(dst, vec_get(src, i));
        i = i + 1;
    }
}

// Per-node-unique temp name (reader globals are dropped, so derive uniqueness
// from the source byte offset plus a slot tag).
func fo_gensym(prefix *u8, node *PNode, tag i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var offset i64 = node.start;
    sb_int(sb, offset);
    sb_str(sb, "_");
    sb_int(sb, tag);
    return sb_finish(sb);
}

func fo_starts(s *u8, p *u8) i64 {
    while *p != 0 {
        if *s == 0 { return 0; }
        if *s != *p { return 0; }
        s = s + 1;
        p = p + 1;
    }
    return 1;
}

// A node is "simple" when re-evaluating it or deferring it past a statement is
// free of consequence: a literal or a bare variable reference.
func fo_is_simple(e *u8) i64 {
    if fo_starts(e, "(number ") == 1 { return 1; }
    if fo_starts(e, "(ident ") == 1 { return 1; }
    return 0;
}

// Force every pending computation on the stack into a temp, bottom-up, so it
// happens HERE. Called before any word that duplicates, reorders, discards or
// emits a statement - without it, `f g 42 . *` would emit the print before f and
// g ran, quietly reordering side effects relative to real Forth.
func fo_flush_upto(stack *u8, stmts *u8, node *PNode, limit i64) void {
    var n i64 = limit;
    var i i64 = 0;
    while i < n {
        var e *u8 = vec_get(stack, i);
        if fo_is_simple(e) == 0 {
            var t *u8 = fo_gensym("__fs", node, i);
            ast_push(stmts, ast_var(t, ast_type_i64(), e));
            vec_set(stack, i, ast_ident(t));
        }
        i = i + 1;
    }
}

func fo_flush(stack *u8, stmts *u8, node *PNode) void {
    fo_flush_upto(stack, stmts, node, vec_len(stack));
}

// ============================================================
// Words
// ============================================================

func fo_binop_for(op *u8) *u8 {
    if streq(op, "=")  { return "=="; }     // Forth's `=` is a comparison
    if streq(op, "+")  { return "+"; }
    if streq(op, "-")  { return "-"; }
    if streq(op, "*")  { return "*"; }
    if streq(op, "/")  { return "/"; }
    if streq(op, "%")  { return "%"; }
    if streq(op, "<")  { return "<"; }
    if streq(op, ">")  { return ">"; }
    if streq(op, "<=") { return "<="; }
    if streq(op, ">=") { return ">="; }
    return nil;
}

// ( a b -- a OP b ). No flush: operands are popped in Forth's own order, and
// lang evaluates a binop left-to-right, so the order already matches.
func fo_binary(stack *u8, op *u8, node *PNode) void {
    var b *u8 = fo_pop(stack, node);
    var a *u8 = fo_pop(stack, node);
    vec_push(stack, ast_binop(op, a, b));
}

func fo_emit_operator(items *u8, ip *i64, stack *u8) void {
    var op *PNode = vec_get(items, *ip);
    var text *u8 = op.text;
    *ip = *ip + 1;
    // Forth's not-equal is `<>`; the tokenizer hands us two separate operators.
    if streq(text, "<") {
        var nxt *PNode = nil;
        if *ip < vec_len(items) { nxt = vec_get(items, *ip); }
        if nxt != nil {
            if pnode_is(nxt, "op") {
                if streq(nxt.text, ">") {
                    *ip = *ip + 1;
                    fo_binary(stack, "!=", op);
                    return;
                }
            }
        }
    }
    var lop *u8 = fo_binop_for(text);
    if lop == nil {
        fo_fail("unknown operator word", text, op);
    }
    fo_binary(stack, lop, op);
}

// dup/over duplicate a node, so what they duplicate must already be a value.
func fo_shuffle(w *u8, stack *u8, stmts *u8, node *PNode) i64 {
    fo_flush(stack, stmts, node);
    var n i64 = vec_len(stack);
    if streq(w, "dup") {
        if n < 1 { fo_fail("dup on an empty stack", nil, node); }
        vec_push(stack, vec_get(stack, n - 1));
        return 1;
    }
    if streq(w, "drop") {
        if n < 1 { fo_fail("drop on an empty stack", nil, node); }
        vec_pop(stack);
        return 1;
    }
    if streq(w, "swap") {
        if n < 2 { fo_fail("swap needs two values", nil, node); }
        var a *u8 = vec_get(stack, n - 2);
        var b *u8 = vec_get(stack, n - 1);
        vec_set(stack, n - 2, b);
        vec_set(stack, n - 1, a);
        return 1;
    }
    if streq(w, "over") {
        if n < 2 { fo_fail("over needs two values", nil, node); }
        vec_push(stack, vec_get(stack, n - 2));
        return 1;
    }
    if streq(w, "nip") {
        if n < 2 { fo_fail("nip needs two values", nil, node); }
        var top *u8 = vec_get(stack, n - 1);
        vec_pop(stack);
        vec_set(stack, n - 2, top);
        return 1;
    }
    if streq(w, "rot") {
        if n < 3 { fo_fail("rot needs three values", nil, node); }
        var x *u8 = vec_get(stack, n - 3);
        var y *u8 = vec_get(stack, n - 2);
        var z *u8 = vec_get(stack, n - 1);
        vec_set(stack, n - 3, y);
        vec_set(stack, n - 2, z);
        vec_set(stack, n - 1, x);
        return 1;
    }
    return 0;
}

// A call to a defined word, an extern host function, or `recurse`.
func fo_emit_call(name *u8, stack *u8, stmts *u8, sigs *u8, node *PNode) void {
    var si i64 = fo_sig_find(sigs, name);
    if si < 0 {
        fo_fail("undefined word (declare host functions with `extern name ( a -- r ) ;`)",
                name, node);
    }
    var np i64 = vec_get(sigs, si + 1);
    var nr i64 = vec_get(sigs, si + 2);
    // A word that returns nothing becomes a statement, so pending work on the
    // stack has to happen first.
    if nr == 0 { fo_flush(stack, stmts, node); }

    var popped *u8 = vec_new(8);
    var k i64 = 0;
    while k < np {
        vec_push(popped, fo_pop(stack, node));
        k = k + 1;
    }
    var args *u8 = ast_vec();
    k = np - 1;
    while k >= 0 {
        ast_push(args, vec_get(popped, k));
        k = k - 1;
    }
    var call *u8 = ast_span(ast_call_named(name, args), node.start, node.end);
    if nr == 0 {
        ast_push(stmts, ast_expr_stmt(call));
    } else {
        if nr > 1 {
            eprint("forth: warning: word '");
            eprint(name);
            eprint("' declares more than one result; only the first is kept\n");
        }
        vec_push(stack, call);
    }
}

// ============================================================
// if / else / then
// ============================================================

// The flag is popped, then BOTH branches run on a copy of the same stack. Any
// slot they disagree about becomes a temp assigned in each branch - which is how
// a value-producing conditional falls out of a language that has no conditional
// expression. The condition is evaluated exactly once.
//
// *ip points just past `if` on entry, and just past `then` on exit.
func fo_emit_if(node *PNode, items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    var cond *u8 = fo_pop(stack, node);
    fo_flush(stack, stmts, node);
    var saved *u8 = fo_stack_copy(stack);

    var then_stmts *u8 = ast_vec();
    fo_emit_seq(items, ip, stack, then_stmts, sigs, selfname);
    var then_stack *u8 = fo_stack_copy(stack);

    var has_else i64 = 0;
    var w *u8 = fo_word_at(items, *ip);
    if w != nil {
        if streq(w, "else") == 1 { has_else = 1; }
    }
    var else_stmts *u8 = ast_vec();
    var else_stack *u8 = saved;
    if has_else == 1 {
        *ip = *ip + 1;
        fo_stack_load(stack, saved);
        fo_emit_seq(items, ip, stack, else_stmts, sigs, selfname);
        else_stack = fo_stack_copy(stack);
    }

    var w2 *u8 = fo_word_at(items, *ip);
    if w2 == nil {
        fo_fail("`if` without a closing `then`", nil, node);
    } else {
        if streq(w2, "then") {
            *ip = *ip + 1;
        } else {
            fo_fail("`if` without a closing `then`", nil, node);
        }
    }

    var dt i64 = vec_len(then_stack);
    var de i64 = vec_len(else_stack);
    if dt != de {
        eprint("forth: warning: if/else leave different stack depths; using the shallower one\n");
    }
    var d i64 = dt;
    if de < d { d = de; }

    var result *u8 = vec_new(16);
    var j i64 = 0;
    while j < d {
        var a *u8 = vec_get(then_stack, j);
        var b *u8 = vec_get(else_stack, j);
        if streq(a, b) == 1 {
            vec_push(result, a);
        } else {
            var t *u8 = fo_gensym("__fi", node, j);
            ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
            ast_push(then_stmts, ast_assign(ast_ident(t), a));
            ast_push(else_stmts, ast_assign(ast_ident(t), b));
            vec_push(result, ast_ident(t));
        }
        j = j + 1;
    }

    var else_block *u8 = nil;
    if ast_vec_len(else_stmts) > 0 { else_block = ast_block(else_stmts); }
    ast_push(stmts, ast_if(cond, ast_block(then_stmts), else_block));
    fo_stack_load(stack, result);
}

// ============================================================
// The word stream
// ============================================================

// Walk words from *ip, stopping AT `else`/`then` (the caller consumes them).
func fo_emit_seq(items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    var n i64 = vec_len(items);
    while *ip < n {
        var it *PNode = vec_get(items, *ip);
        if pnode_is(it, "num") {
            vec_push(stack, ast_number(it.text));
            *ip = *ip + 1;
        } else if pnode_is(it, "op") {
            fo_emit_operator(items, ip, stack);
        } else if pnode_is(it, "dot") {
            // `.` - print the top of stack (with Forth's trailing space)
            fo_flush(stack, stmts, it);
            ast_push(stmts, ast_expr_stmt(ast_call_named1("forth_dot", fo_pop(stack, it))));
            *ip = *ip + 1;
        } else if pnode_is(it, "comment") {
            *ip = *ip + 1;                          // an inline ( ... ) comment
        } else {
            var w *u8 = fo_name_text(it);
            if streq(w, "else") == 1 { return; }
            if streq(w, "then") == 1 { return; }
            *ip = *ip + 1;
            fo_emit_word(w, it, items, ip, stack, stmts, sigs, selfname);
        }
    }
}

// One name word. *ip already points past it.
func fo_emit_word(w *u8, node *PNode, items *u8, ip *i64, stack *u8, stmts *u8, sigs *u8, selfname *u8) void {
    if streq(w, "if") == 1 {
        fo_emit_if(node, items, ip, stack, stmts, sigs, selfname);
        return;
    }
    if fo_shuffle(w, stack, stmts, node) == 1 { return; }
    if streq(w, "mod") == 1 { fo_binary(stack, "%", node); return; }
    if streq(w, "and") == 1 { fo_binary(stack, "&", node); return; }
    if streq(w, "or") == 1  { fo_binary(stack, "|", node); return; }
    if streq(w, "xor") == 1 { fo_binary(stack, "^", node); return; }
    if streq(w, "negate") == 1 {
        vec_push(stack, ast_neg(fo_pop(stack, node)));
        return;
    }
    if streq(w, "invert") == 1 {                    // lang has no unary `~`
        vec_push(stack, ast_binop("^", fo_pop(stack, node), ast_neg(ast_int(1))));
        return;
    }
    if streq(w, "cr") == 1 {
        fo_flush(stack, stmts, node);
        ast_push(stmts, ast_expr_stmt(ast_call_named0("forth_cr")));
        return;
    }
    var target *u8 = w;
    if streq(w, "recurse") == 1 { target = selfname; }
    fo_emit_call(target, stack, stmts, sigs, node);
}

// ============================================================
// Definitions
// ============================================================

// `: name ( a b -- s ) words ;` -> func name(a i64, b i64) i64 { ... }
// The stack starts holding the parameters; whatever is on top at `;` is the
// result. Every word uses raw i64 values. Other readers must agree about tags
// and ownership as well as storage before a direct call is valid.
func fo_emit_worddef(d *PNode, sigs *u8) *u8 {
    var namen *PNode = pnode_require(d, "name");
    var wname *u8 = fo_name_text(namen);
    var eff *PNode = pnode_require(d, "effect");
    var body *PNode = pnode_require(d, "body");

    var pnames *u8 = vec_new(8);
    var nres i64 = fo_effect_split(eff, pnames);

    var params *u8 = ast_vec();
    var stack *u8 = vec_new(16);
    var np i64 = vec_len(pnames);
    var i i64 = 0;
    while i < np {
        var pn *u8 = vec_get(pnames, i);
        ast_push(params, ast_param(pn, ast_type_i64()));
        vec_push(stack, ast_ident(pn));
        i = i + 1;
    }

    var stmts *u8 = ast_vec();
    var ip i64 = 0;
    fo_emit_seq(body.children, &ip, stack, stmts, sigs, wname);

    // Anything left BELOW the result is a discarded value whose side effects
    // still have to happen, and happen first. The result itself needs no temp -
    // the return is its evaluation point.
    var depth i64 = vec_len(stack);
    var keep i64 = 0;
    if nres > 0 { keep = 1; }
    fo_flush_upto(stack, stmts, d, depth - keep);
    if nres > 0 {
        if depth > 0 {
            ast_push(stmts, ast_return(vec_get(stack, depth - 1)));
        } else {
            fo_fail("word promises a result but leaves an empty stack", wname, namen);
        }
    } else {
        ast_push(stmts, ast_return(ast_int(0)));
    }
    return ast_span(ast_func(wname, params, ast_type_i64(), ast_block(stmts)), d.start, d.end);
}

// `extern` contributes only a signature (so calls get the right arity); the
// function itself comes from C, Lisp, flow or lang.
func fo_emit_program(prog *PNode) *u8 {
    var sigs *u8 = fo_collect_sigs(prog);
    var decls *u8 = ast_vec();
    var defs *u8 = prog.children;
    var n i64 = vec_len(defs);
    var i i64 = 0;
    while i < n {
        var d *PNode = vec_get(defs, i);
        if fo_def_kind(d) == 1 {
            ast_push(decls, fo_emit_worddef(d, sigs));
        }
        i = i + 1;
    }
    return ast_program(decls);
}

// Opt-in project boundary: all externs must match the producer's catalog.
// Existing `forth` externs remain trusted, unchecked native declarations.
func fo_check_exports(prog *PNode, exports *u8) void {
    var seen *u8 = map_new();
    var defs *u8 = prog.children;
    var i i64 = 0;
    while i < vec_len(defs) {
        var d *PNode = vec_get(defs, i);
        var kind i64 = fo_def_kind(d);
        if kind != 0 {
            var node *PNode = pnode_require(d, "name");
            var name *u8 = fo_name_text(node);
            if map_has(seen, name) { fo_fail("duplicate word", name, node); }
            map_set(seen, name, "seen");
            var actual *ReaderExport = reader_export_find(exports, name);
            if kind == 1 && actual != nil { fo_fail("definition shadows export", name, node); }
            if kind == 2 {
                var names *u8 = vec_new(8);
                var results i64 = fo_effect_split(pnode_require(d, "effect"), names);
                if results != 1 { fo_fail("export requires one i64 value result", name, node); }
                var parameters *u8 = vec_new(8);
                var j i64 = 0;
                while j < vec_len(names) { vec_push(parameters, reader_i64_value()); j = j + 1; }
                var message *u8 = reader_export_mismatch(actual, reader_export(name, parameters, reader_i64_value()));
                if message != nil { fo_fail(str_concat(message, "; explicit adapter required for incompatible exports"), name, node); }
                // Ambiguous catalogs cannot select an arbitrary definition.
                j = 0;
                var count i64 = 0;
                while j < vec_len(exports) {
                    var candidate *ReaderExport = vec_get(exports, j);
                    if streq(candidate.symbol, name) { count = count + 1; }
                    j = j + 1;
                }
                if count != 1 { fo_fail("duplicate export", name, node); }
            }
        }
        i = i + 1;
    }
}

func fo_read(text *u8, exports *u8, label *u8) *u8 {
    fo_src = text;
    fo_label = label;
    // Forth's line comment is `\\`, which the shared scanner can now be told.
    // `( ... )` stays a source pre-pass, because in THIS Forth a parenthesized
    // group is not a comment: the stack effect wears the same parentheses and
    // the grammar parses it (see fo_sanitize_comments).
    var t *Tokenizer = tok_new_comments(fo_sanitize_comments(text), "\\", nil, nil);
    var prog *PNode = parse_fo_program(t);
    if prog == nil || !tok_expect_end(t) { tok_print_error(t, fo_label); return nil; }
    if exports != nil { fo_check_exports(prog, exports); }
    return fo_emit_program(prog);
}

reader forth(text *u8) *u8 { return fo_read(text, nil, "forth"); }

example/minilisp/minilisp.lang:
// ============================================================
// minilisp - a small but real Lisp that compiles to a native binary
// ============================================================
//
// Reads s-expression syntax via #parser{} (Level 3) and lowers it to lang AST
// with the std/ast.lang builder API (Level 1) - NO hand-written S-expr strings.
//
// Values are BOXED: every Lisp value is an i64 that is really a *LispObj pointer
// (see example/minilisp/lisp_runtime.lang). So lists are first-class. Programs
// using #minilisp{} must `include "example/minilisp/lisp_runtime.lang"`, and
// cross-language calls marshal with lisp_int(...) / lisp_to_int(...).
//
// EXPRESSIONS:
//   (+ 1 2)  (* 2 (+ 3 4))  (< x 0)  (if c t e)  (and a b) (or a b) (not x)
//   (cons 1 (cons 2 nil))  (car xs)  (cdr xs)  (list 1 2 3)  (eq a b)
//   (quote (a b c))  (let ((x 1) (y 2)) body)
//   (lambda (x) (+ x 1))  (funcall f a b)  (apply f arglist)  ((lambda (x) x) 5)
// DEFINITIONS:
//   (defun add (a b) (+ a b))
//   (defun len (xs) (if (eq xs nil) 0 (+ 1 (len (cdr xs)))))
//   (defun map (f xs) (if (eq xs nil) nil (cons (funcall f (car xs)) (map f (cdr xs)))))
//
// Lisp-2: (f x) calls the function NAMED f (a defun); to call a value (a lambda
// in a variable/param) use (funcall f x) or (apply f args), as in Common Lisp.

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"
include "std/stage.lang"

// #parser{} generates a recursive descent parser from this grammar
#parser{
    sexp = num:number | sym:symbol | op:operator | list:list
    list = '(' items:sexp* ')'
}

// PNODE kinds: 1=number, 2=symbol, 4=list, 5=operator

var ml_src *u8 = nil;

// ============================================================
// Parse tree helpers
// ============================================================

func list_inner(node *PNode) *PNode {
    return pnode_require(node, "items");
}

func list_get(node *PNode, i i64) *PNode {
    return vec_get(list_inner(node).children, i);
}

func list_len(node *PNode) i64 {
    return vec_len(list_inner(node).children);
}

// A form the reader does not recognize is a reader bug or a program bug, and
// either way `lisp_nil` is the wrong answer: `(+ 1 (2 3))` used to compile clean
// and evaluate the inner call to nil.
func ml_fail(what *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, what);
    if node != nil && node.text != nil {
        sb_str(sb, " '");
        sb_str(sb, node.text);
        sb_str(sb, "'");
    }
    pnode_print_error(node, ml_src, "minilisp", sb_finish(sb));
    exit(1);
    return nil;
}

func is_sym(node *PNode, name *u8) bool {
    if node == nil { return false; }
    if !pnode_is(node, "sym") { return false; }
    return streq(node.text, name);
}

// Runtime function for an n-ary arithmetic operator (foldable); nil otherwise.
func arith_fn(op *u8) *u8 {
    if streq(op, "+") { return "lisp_add"; }
    if streq(op, "-") { return "lisp_sub"; }
    if streq(op, "*") { return "lisp_mul"; }
    if streq(op, "/") { return "lisp_div"; }
    if streq(op, "%") { return "lisp_mod"; }
    return nil;
}

// Runtime function for a binary comparison operator; nil otherwise.
func cmp_fn(op *u8) *u8 {
    if streq(op, "<") { return "lisp_lt"; }
    if streq(op, ">") { return "lisp_gt"; }
    if streq(op, "<=") { return "lisp_le"; }
    if streq(op, ">=") { return "lisp_ge"; }
    if streq(op, "=") { return "lisp_num_eq"; }
    if streq(op, "==") { return "lisp_num_eq"; }
    if streq(op, "!=") { return "lisp_ne"; }
    return nil;
}

// Per-node-unique temp name, derived from its source byte offset (each `if` node is
// distinct). Avoids a module-global counter: the reader-build path drops globals
// declared in the reader's OWN file - only included-file globals survive.
func lisp_tmp(node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "__lt");
    var offset i64 = node.start;
    sb_int(sb, offset);
    return sb_finish(sb);
}

// A boxed integer literal: (call lisp_int (number n))
func lisp_num_lit(n i64) *u8 {
    return ast_call_named1("lisp_int", ast_int(n));
}

// ============================================================
// Lowering: parse tree (PNode) -> lang AST calling the Lisp runtime
// ============================================================

// Left-fold a foldable runtime op over operands 1..hi:
// (+ a b c) with hi=3 -> lisp_add(lisp_add(a, b), c)
func lisp_fold(opfn *u8, node *PNode, hi i64) *u8 {
    if hi == 1 {
        return lisp_expr(list_get(node, 1));
    }
    return ast_call_named2(opfn, lisp_fold(opfn, node, hi - 1), lisp_expr(list_get(node, hi)));
}

// (let ((n1 v1) (n2 v2) ...) body) -> nested kernel lets. Sequential (let*-style):
// a later binding sees the earlier ones.
func lisp_let(bindings *PNode, i i64, count i64, body *PNode) *u8 {
    if i >= count {
        return lisp_expr(body);
    }
    var binding *PNode = list_get(bindings, i);
    if !pnode_is(binding, "list") { return ml_fail("invalid let binding", binding); }
    if list_len(binding) != 2 { return ml_fail("invalid let binding", binding); }
    var name *PNode = list_get(binding, 0);
    if !pnode_is(name, "sym") || is_sym(name, "nil") {
        return ml_fail("invalid let binding", name);
    }
    var valexpr *PNode = list_get(binding, 1);
    return ast_let(name.text, ast_type_i64(), lisp_expr(valexpr),
                   lisp_let(bindings, i + 1, count, body));
}

// The kernel closure type every Lisp lambda lowers to: closure(i64) i64
// (takes one arg - the Lisp argument list - and returns a Lisp value).
func lisp_closure_type() *u8 {
    var ptypes *u8 = ast_vec();
    ast_push(ptypes, ast_type_i64());
    return ast_type_closure(ptypes, ast_type_i64());
}

// Bind each Lisp param to an element of the kernel lambda's single __args list:
// param[0] = (car __args), param[1] = (car (cdr __args)), ... then run the body.
func lisp_lambda_binds(params *PNode, i i64, count i64, argexpr *u8, body *u8) *u8 {
    if i >= count { return body; }
    var pnode *PNode = list_get(params, i);
    return ast_let(pnode.text, ast_type_i64(),
                   ast_call_named1("lisp_car", argexpr),
                   lisp_lambda_binds(params, i + 1, count,
                                     ast_call_named1("lisp_cdr", argexpr), body));
}

// (lambda (params) body) -> a boxed closure VALUE. Every Lisp lambda becomes a
// kernel closure of uniform type closure(i64) i64: it takes the argument list,
// destructures it into the named params, and runs the body. Routing it through
// a closure-typed `var` forces the [tag][fn_ptr][captures] heap layout (the
// kernel auto-wraps a non-capturing lambda to tag=0 there), then lisp_closure
// boxes the pointer so the lambda is first-class. The holding var is uniquely
// named per node (block_expr vars leak to the enclosing scope, like `if` temps).
func lisp_lambda(params *PNode, bodynode *PNode) *u8 {
    if !pnode_is(params, "list") { return ml_fail("invalid lambda parameter", params); }
    var count i64 = list_len(params);
    var i i64 = 0;
    while i < count {
        var param *PNode = list_get(params, i);
        if !pnode_is(param, "sym") || is_sym(param, "nil") {
            return ml_fail("invalid lambda parameter", param);
        }
        var j i64 = 0;
        while j < i {
            var previous *PNode = list_get(params, j);
            if streq(param.text, previous.text) { return ml_fail("invalid lambda parameter", param); }
            j = j + 1;
        }
        i = i + 1;
    }

    var sb *StringBuilder = sb_new();
    sb_str(sb, "__arli_ml_lambda_shape_args_");
    var offset i64 = params.start;
    sb_int(sb, offset);
    var cursor *u8 = sb_finish(sb);
    var body_stmts *u8 = ast_vec();
    ast_push(body_stmts, ast_var(cursor, ast_type_i64(), ast_ident("__args")));
    var failure *u8 = ast_vec();
    ast_push(failure, ast_expr_stmt(ast_call_named1("eprintln", ast_string("minilisp: lambda argument count"))));
    ast_push(failure, ast_expr_stmt(ast_call_named1("exit", ast_int(1))));
    i = 0;
    while i < count {
        ast_push(body_stmts, ast_if_then(ast_ne(ast_call_named1("lisp_tag", ast_ident(cursor)), ast_int(2)), ast_block(failure)));
        ast_push(body_stmts, ast_assign(ast_ident(cursor), ast_call_named1("lisp_cdr", ast_ident(cursor))));
        i = i + 1;
    }
    ast_push(body_stmts, ast_if_then(ast_ne(ast_call_named1("lisp_tag", ast_ident(cursor)), ast_int(1)), ast_block(failure)));
    var cvar *u8 = lisp_tmp(bodynode);
    var pvec *u8 = ast_vec();
    ast_push(pvec, ast_param("__args", ast_type_i64()));
    var inner *u8 = lisp_lambda_binds(params, 0, count,
                                      ast_ident("__args"), lisp_expr(bodynode));
    ast_push(body_stmts, ast_return(inner));
    var lam *u8 = ast_lambda(pvec, ast_type_i64(), ast_block(body_stmts));
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(cvar, lisp_closure_type(), lam));
    return ast_block_expr(stmts, ast_call_named1("lisp_closure", ast_ident(cvar)));
}

// (list a b c) -> (cons a (cons b (cons c (nil))))
func lisp_list_from(node *PNode, i i64, count i64) *u8 {
    if i >= count {
        return ast_call_named0("lisp_nil");
    }
    return ast_call_named2("lisp_cons", lisp_expr(list_get(node, i)), lisp_list_from(node, i + 1, count));
}

// Quote: build a Lisp VALUE from the parse tree without evaluating. Numbers
// become boxed ints, symbols/operators become interned symbols, lists become
// cons chains. (quote (a (b 2))) -> (cons sym-a (cons (cons sym-b (cons 2 nil)) nil))
func lisp_quote(node *PNode) *u8 {
    if node == nil { return ast_call_named0("lisp_nil"); }
    if pnode_is(node, "num") {                                // number -> boxed int
        return ast_call_named1("lisp_int", ast_number(node.text));
    }
    if pnode_is(node, "sym") {
        if streq(node.text, "nil") { return ast_call_named0("lisp_nil"); }
        return ast_call_named1("lisp_sym", ast_string(node.text));
    }
    if pnode_is(node, "op") {                                 // operator symbol, e.g. '+
        return ast_call_named1("lisp_sym", ast_string(node.text));
    }
    if pnode_is(node, "list") {                               // list -> cons chain
        return lisp_quote_list(node, 0, list_len(node));
    }
    return ml_fail("unquotable form", node);
}

func lisp_quote_list(node *PNode, i i64, count i64) *u8 {
    if i >= count { return ast_call_named0("lisp_nil"); }
    return ast_call_named2("lisp_cons", lisp_quote(list_get(node, i)),
                           lisp_quote_list(node, i + 1, count));
}

// Emit a call to runtime function `fnname` with the node's args 1..count-1.
func lisp_runtime_call(fnname *u8, node *PNode, count i64) *u8 {
    if streq(fnname, "lisp_and") || streq(fnname, "lisp_or") {
        var t *u8 = lisp_tmp(node);
        var first *u8 = lisp_expr(list_get(node, 1));
        var second *u8 = lisp_expr(list_get(node, 2));
        var first_name *u8 = str_concat(t, "_first");
        var stmts *u8 = ast_vec();
        ast_push(stmts, ast_var(t, ast_type_i64(), ast_ident(first_name)));
        var update *u8 = ast_block1(ast_assign(ast_ident(t), second));
        var keep *u8 = ast_block1(ast_assign(ast_ident(t), ast_ident(t)));
        if streq(fnname, "lisp_and") {
            ast_push(stmts, ast_if(ast_call_named1("lisp_truthy", ast_ident(t)), update, keep));
        } else {
            ast_push(stmts, ast_if(ast_call_named1("lisp_truthy", ast_ident(t)), keep, update));
        }
        return ast_let(first_name, ast_type_i64(), first,
                       ast_block_expr(stmts, ast_ident(t)));
    }
    var args *u8 = ast_vec();
    var i i64 = 1;
    while i < count {
        ast_push(args, lisp_expr(list_get(node, i)));
        i = i + 1;
    }
    return ast_call_named(fnname, args);
}

// Emit a body in return (tail) position. A tail `if` becomes real control flow
// with a return in each branch, so recursive base cases actually stop.
func lisp_return(node *PNode) *u8 {
    if node == nil { return lisp_return_inner(node); }
    return ast_span(lisp_return_inner(node), node.start, node.end);
}

func lisp_return_inner(node *PNode) *u8 {
    if node != nil && pnode_is(node, "list") {
        var first *PNode = list_get(node, 0);
        if is_sym(first, "if") {
            if list_len(node) != 4 { return ml_fail("form arity", node); }
            return ast_if(ast_call_named1("lisp_truthy", lisp_expr(list_get(node, 1))),
                          ast_block1(lisp_return(list_get(node, 2))),
                          ast_block1(lisp_return(list_get(node, 3))));
        }
    }
    return ast_return(lisp_expr(node));
}

// Lower one minilisp node to lang AST. A top-level (defun ...) becomes a
// (program (func ...)); everything else lowers to an expression (an i64 that is
// really a *LispObj).
func lisp_expr(node *PNode) *u8 {
    if node == nil { return ast_call_named0("lisp_nil"); }

    if pnode_is(node, "num") {                       // number literal -> boxed int
        return ast_call_named1("lisp_int", ast_number(node.text));
    }
    if pnode_is(node, "sym") {
        if streq(node.text, "nil") { return ast_call_named0("lisp_nil"); }
        return ast_ident(node.text);
    }
    // Lisp-2: an operator names a function, so it is only meaningful at the head
    // of a call. Everything that is not an atom is a list.
    if pnode_is(node, "op") { return ml_fail("operator used as a value", node); }
    if !pnode_is(node, "list") { return ml_fail("unrecognized form", node); }

    var count i64 = list_len(node);
    if count == 0 { return ast_call_named0("lisp_nil"); }
    var first *PNode = list_get(node, 0);

    // Explicit read-time evaluation; ordinary forms retain runtime semantics.
    if is_sym(first, "stage") {
        if count != 2 { return ml_fail("stage arity", node); }
        var params *u8 = ast_vec();
        ast_push(params, ast_param("args", ast_type_ptr(ast_type("PhaseBuffer"))));
        var decls *u8 = ast_vec();
        ast_push(decls, ast_include("example/minilisp/lisp_runtime.lang"));
        ast_push(decls, ast_func("stage_entry", params, ast_type_ptr(ast_type("PhaseBuffer")),
            ast_block1(ast_return(ast_call1("phase_value_i64",
                ast_call1("lisp_to_int", lisp_expr(list_get(node, 1))))))));
        var result *PhaseBuffer = stage_run(ast_program(decls), phase_value_i64(0));
        var digits *u8 = alloc(24); var len i64 = itoa(phase_value_integer(result.data), digits);
        *(digits + len) = 0;
        return ast_call1("lisp_int", ast_number(digits));
    }

    // Operator-headed: arithmetic (foldable) or comparison (binary).
    if pnode_is(first, "op") {
        var op *u8 = first.text;
        var af *u8 = arith_fn(op);
        if af != nil {
            if count < 2 { return ml_fail("form arity", node); }
            if count == 2 {                          // unary, e.g. (- x) -> lisp_sub(0, x)
                return ast_call_named2(af, lisp_num_lit(0), lisp_expr(list_get(node, 1)));
            }
            return lisp_fold(af, node, count - 1);
        }
        var cf *u8 = cmp_fn(op);
        if cf != nil {
            if count != 3 { return ml_fail("form arity", node); }
            return ast_call_named2(cf, lisp_expr(list_get(node, 1)), lisp_expr(list_get(node, 2)));
        }
        return ml_fail("unknown operator", first);
    }

    // Validate fixed-arity forms before reading operands.
    if (is_sym(first, "if") || is_sym(first, "defun")) && count != 4 {
        return ml_fail("form arity", node);
    }
    if (is_sym(first, "quote") || is_sym(first, "not") || is_sym(first, "car") || is_sym(first, "cdr")) && count != 2 {
        return ml_fail("form arity", node);
    }
    if (is_sym(first, "let") || is_sym(first, "lambda") || is_sym(first, "apply") ||
        is_sym(first, "and") || is_sym(first, "or") || is_sym(first, "cons") || is_sym(first, "eq")) && count != 3 {
        return ml_fail("form arity", node);
    }
    if is_sym(first, "funcall") && count < 2 { return ml_fail("form arity", node); }

    // (defun name (params) body) -> (program (func name (params) i64 (block ...)))
    if is_sym(first, "defun") {
        var name *PNode = list_get(node, 1);
        var params *PNode = list_get(node, 2);
        var body *PNode = list_get(node, 3);
        if !pnode_is(name, "sym") || !pnode_is(params, "list") {
            return ml_fail("invalid defun", node);
        }
        var check_count i64 = list_len(params);
        var check_i i64 = 0;
        while check_i < check_count {
            var param *PNode = list_get(params, check_i);
            if !pnode_is(param, "sym") || is_sym(param, "nil") {
                return ml_fail("invalid defun", node);
            }
            var check_j i64 = 0;
            while check_j < check_i {
                var previous *PNode = list_get(params, check_j);
                if streq(param.text, previous.text) { return ml_fail("invalid defun", node); }
                check_j = check_j + 1;
            }
            check_i = check_i + 1;
        }
        var pvec *u8 = ast_vec();
        var pc i64 = list_len(params);
        var pi i64 = 0;
        while pi < pc {
            var pnode *PNode = vec_get(list_inner(params).children, pi);
            ast_push(pvec, ast_param(pnode.text, ast_type_i64()));
            pi = pi + 1;
        }
        return ast_program1(ast_span(ast_func(name.text, pvec, ast_type_i64(),
                                     ast_block1(lisp_return(body))), node.start, node.end));
    }

    // (if cond then else) -> value-returning block_expr; only the taken branch
    // runs. Condition goes through lisp_truthy (only nil is false).
    if is_sym(first, "if") {
        var t *u8 = lisp_tmp(node);
        var stmts *u8 = ast_vec();
        ast_push(stmts, ast_var(t, ast_type_i64(), ast_int(0)));
        ast_push(stmts, ast_if(ast_call_named1("lisp_truthy", lisp_expr(list_get(node, 1))),
                               ast_block1(ast_assign(ast_ident(t), lisp_expr(list_get(node, 2)))),
                               ast_block1(ast_assign(ast_ident(t), lisp_expr(list_get(node, 3))))));
        return ast_block_expr(stmts, ast_ident(t));
    }

    // (quote expr) -> the literal value (no evaluation)
    if is_sym(first, "quote") {
        return lisp_quote(list_get(node, 1));
    }

    // (let ((n v)...) body)
    if is_sym(first, "let") {
        var bindings *PNode = list_get(node, 1);
        if !pnode_is(bindings, "list") { return ml_fail("invalid let form", node); }
        var body *PNode = list_get(node, 2);
        return lisp_let(bindings, 0, list_len(bindings), body);
    }

    // (lambda (params) body) -> a first-class closure value
    if is_sym(first, "lambda") {
        return lisp_lambda(list_get(node, 1), list_get(node, 2));
    }

    // (funcall fexpr a b ...) -> apply a value-position function (Lisp-2 style)
    if is_sym(first, "funcall") {
        return ast_call_named2("lisp_apply", lisp_expr(list_get(node, 1)),
                               lisp_list_from(node, 2, count));
    }

    // (apply fexpr arglist) -> apply to an already-built argument list
    if is_sym(first, "apply") {
        return ast_call_named2("lisp_apply", lisp_expr(list_get(node, 1)),
                               lisp_expr(list_get(node, 2)));
    }

    // Logical + list builtins -> runtime calls.
    if is_sym(first, "not")  { return lisp_runtime_call("lisp_not", node, count); }
    if is_sym(first, "and")  { return lisp_runtime_call("lisp_and", node, count); }
    if is_sym(first, "or")   { return lisp_runtime_call("lisp_or", node, count); }
    if is_sym(first, "cons") { return lisp_runtime_call("lisp_cons", node, count); }
    if is_sym(first, "car")  { return lisp_runtime_call("lisp_car", node, count); }
    if is_sym(first, "cdr")  { return lisp_runtime_call("lisp_cdr", node, count); }
    if is_sym(first, "eq")   { return lisp_runtime_call("lisp_eq", node, count); }
    if is_sym(first, "list") { return lisp_list_from(node, 1, count); }

    // Head is itself an expression, e.g. ((lambda (x) ...) 5) -> apply its value.
    if pnode_is(first, "list") {
        return ast_call_named2("lisp_apply", lisp_expr(first), lisp_list_from(node, 1, count));
    }

    // Function call: (f a b) -> (call (ident f) a b)
    if pnode_is(first, "sym") {
        var args *u8 = ast_vec();
        var ai i64 = 1;
        while ai < count {
            ast_push(args, lisp_expr(list_get(node, ai)));
            ai = ai + 1;
        }
        return ast_span(ast_call_named(first.text, args), first.start, node.end);
    }

    return ml_fail("a call's head must be a symbol, an operator, or a list", first);
}

reader minilisp(text *u8) *u8 {
    ml_src = text;
    // Lisp's comment is `;`. Until a reader could say so, minilisp had none at
    // all - it inherited lang's `//`, which is not a thing anyone writes in a
    // Lisp, and `;` would have derailed the parse.
    var t *Tokenizer = tok_new_comments(text, ";", nil, nil);
    var node *PNode = parse_sexp(t);
    return lisp_expr(node);
}

example/minipy/minipy.lang:
// ============================================================
// minipy - a language whose block delimiter is whitespace
// ============================================================
//
// The fifth polyglot language, and the first one you cannot parse by reading
// characters in order. C, flow and minilisp bracket their blocks, and forth has
// no blocks at all; minipy's block structure lives in the space to the LEFT of
// each line, which is exactly the part every other reader throws away:
//
//   #minipy{
//       def collatz(n):
//           steps = 0
//           while n != 1:
//               if n % 2 == 0:
//                   n = n / 2
//               else:
//                   n = 3 * n + 1
//               steps += 1
//           return steps
//   }
//
// The shared tokenizer (std/tok.lang) is deliberately whitespace-blind - it
// skips runs of spaces and newlines without recording them, and every other
// reader depends on that. Layout does NOT need it to change. A token carries its
// byte offset into the source (`tok_start`), so the two facts the offside rule
// actually needs - "is this the first token on its line" and "at what column" -
// are still recoverable, and recovering them is the reader's business, not the
// tokenizer's. py_lex below rebuilds them and emits the synthetic NEWLINE /
// INDENT / DEDENT tokens a layout language wants, which is precisely what
// CPython's tokenizer hands to its parser. Nothing shared was touched, so
// nothing else could break: layout is a plugin too.
//
// What py_lex hands over is a TOKEN STREAM, not a private token array: the
// grammar below is an ordinary #parser{} grammar that names the layout tokens
// in angle brackets, and the generated parser reads the reader's tokens exactly
// as it would read a scan of the source. Until a reader could supply its own
// tokens, minipy had to hand-write its parser - which is why it carried its own
// copy of the precedence ladder and its own statement dispatch long after the
// toolkit had both.
//
// Two consequences of layout that the token stream then handles for free:
// a newline inside `( ... )` continues the line (bracket depth suppresses the
// rule), and a blank or comment-only line has no tokens at all, so it cannot
// affect indentation.
//
// Supported: def, if/elif/else, while, for-in-range, return, pass, break,
// continue, assignment and augmented assignment, `and`/`or`/`not`, the full
// Python precedence ladder down through the bitwise and shift operators,
// calls, `#` comments, and both quote styles. True/False/None are 1/0/0.
//
// Deliberate bounds (round 1): every value is an i64, so there are no lists,
// dicts, strings-as-values (a string literal may only be an argument to
// `print`), or floats; no classes, no lambdas, no nested defs or closures, no
// default/keyword arguments, no `import`, no exceptions, and only `def` at the
// top level. `for` iterates `range(...)` only. Chained comparisons (`a < b < c`)
// are rejected rather than silently mis-associated. Names are function-scoped as
// in Python (see py_def's hoist), NOT block-scoped as in lang.
//
// A call to a name minipy has never seen is emitted as an ordinary call, so
// minipy reaches C, minilisp, flow, forth and lang functions with no
// declaration of any kind - the i64 ABI is the whole interface.
//
// Converter helpers are py_-prefixed so minipy composes with the other readers
// in one binary (no symbol collisions), and so are its token kinds.

include "std/core.lang"
include "std/ast.lang"
include "std/parser_reader.lang"
include "std/prec.lang"

// Synthetic token kinds, above anything std/tok.lang produces. These are the
// layout algorithm's entire output: the structure of the program. The grammar
// names them <newline>, <indent> and <dedent>, and a generated parser puts that
// spelling straight into "expected ..." - so these are named for how they should
// read in a diagnostic, not with minipy's usual py_ prefix. A second layout
// reader in the same binary would collide, loudly, at compile time.
var TOK_NEWLINE i64 = 200;
var TOK_INDENT i64 = 201;
var TOK_DEDENT i64 = 202;

// ============================================================
// The offside rule
// ============================================================

// Offset of the first byte of the line containing `off`.
func py_line_start(text *u8, off i64) i64 {
    while off > 0 {
        if *(text + off - 1) == 10 { return off; }
        off = off - 1;
    }
    return 0;
}

func py_top(indents *u8) i64 {
    return vec_get(indents, vec_len(indents) - 1);
}

// The source the reader was handed, for diagnostics that carry a parse node
// rather than a tokenizer.
var py_src *u8 = nil;

// Walks the ordinary token stream and inserts NEWLINE where a logical line ends
// and INDENT/DEDENT where the left margin moves.
//
// The base indent is taken from the FIRST token rather than assumed to be
// column 0, so a `#minipy{ ... }` block may sit at whatever indentation the
// host file uses - only the columns relative to that first line matter.
//
// Every token keeps its real span into `text`, synthetic ones included, so a
// parse error reports the line and column a reader of the source would point
// at, and so does every AST node built from the tree.
func py_lex(text *u8) *u8 {
    // Python's comment is `#`, and `//` is floor division rather than the start
    // of one. Saying so is the whole of what minipy used to do by rewriting its
    // own source text before scanning it - a pass that had to be
    // length-preserving, because byte offsets ARE this language's blocks.
    var t *Tokenizer = tok_new_comments(text, "#", nil, nil);
    var toks *u8 = tok_stream_new();
    var indents *u8 = vec_new(16);
    vec_push(indents, 0);

    var depth i64 = 0;
    var prev_ls i64 = 0 - 1;
    var started i64 = 0;
    var last i64 = 0;

    while tok_kind(t) != TOK_EOF {
        var start i64 = t.tok_start;
        var ls i64 = py_line_start(text, start);
        var col i64 = start - ls;

        // Bracketed newlines are continuations, not statement ends.
        if depth == 0 && ls != prev_ls {
            if started == 0 {
                vec_set(indents, 0, col);
            } else {
                // A NEWLINE stands at the END of the line it terminates, which
                // is where a reader of the source would point at a statement
                // that never finished; INDENT/DEDENT describe the NEXT line's
                // column and stand there.
                tok_stream_push(toks, TOK_NEWLINE, last, 0, "end of line");
                if col > py_top(indents) {
                    vec_push(indents, col);
                    tok_stream_push(toks, TOK_INDENT, start, 0, "an indented block");
                } else {
                    while col < py_top(indents) {
                        vec_pop(indents);
                        tok_stream_push(toks, TOK_DEDENT, start, 0, "a dedent");
                    }
                    if col != py_top(indents) {
                        py_fail("dedent does not match any enclosing block",
                                pnode_atom_span(PNODE_TOKEN, nil, start, start + t.tok_len));
                    }
                }
            }
        }
        prev_ls = ls;
        started = 1;

        var k i64 = tok_kind(t);
        if k == TOK_LPAREN || k == TOK_LBRACKET || k == TOK_LBRACE {
            depth = depth + 1;
        }
        if k == TOK_RPAREN || k == TOK_RBRACKET || k == TOK_RBRACE {
            if depth > 0 { depth = depth - 1; }
        }
        var used i64 = t.tok_len;
        if k == TOK_STRING {
            // A string's text is its VALUE (unquoted, unescaped); the kind is
            // what says it was quoted, so nothing downstream re-parses it. The
            // span still covers the quotes, so errors point at the literal.
            tok_stream_push(toks, k, start, t.tok_len, tok_string_value(t));
        } else if k == TOK_SLASH && *(text + start + 1) == 47 {
            // Floor division arrives as two slashes, since minipy told the
            // scanner `//` is not a comment. Every value here is an i64, so one
            // `/` already means what `//` means.
            tok_stream_push(toks, TOK_SLASH, start, 2, nil);
            tok_next(t);
            used = 2;
        } else if k == TOK_NUMBER && *(text + start) == 45 {
            // The shared tokenizer folds a `-` straight into a following digit,
            // so `n -1` arrives as `n` and the single number `-1`. Every infix
            // reader used to have to undo that downstream; owning the stream,
            // minipy splits the token back apart here and nothing after this
            // line ever hears about it. `-1` at the head of an expression is
            // then an ordinary unary minus, which the grammar already has.
            tok_stream_push(toks, TOK_MINUS, start, 1, nil);
            tok_stream_push(toks, TOK_NUMBER, start + 1, t.tok_len - 1, nil);
        } else {
            tok_stream_push(toks, k, start, t.tok_len, nil);
        }
        last = start + used;
        tok_next(t);
    }

    if started == 1 { tok_stream_push(toks, TOK_NEWLINE, last, 0, "end of line"); }
    while vec_len(indents) > 1 {
        vec_pop(indents);
        tok_stream_push(toks, TOK_DEDENT, last, 0, "a dedent");
    }
    return toks;
}

// ============================================================
// Grammar
// ============================================================
//
// The whole of Python's expression ladder - `or`, `and`, `not`, comparison,
// bitwise, shift, additive, multiplicative - is one flat operand/operator list
// and one table. `not` is a PREFIX operator sitting between `and` and the
// comparisons, which a flat list can say because an operator pushed where an
// operand was expected is a prefix operator: the position is the declaration.

#parser{
    py_program   = defs:py_def*

    py_def       = 'def' name:symbol '(' params:py_param* ')' body:py_suite
    py_param     = name:symbol ','?

    py_suite     = ':' body:py_suitebody
    py_suitebody = block:py_indented | inline:py_line
    py_indented  = <newline> <indent> stmts:py_stmt* <dedent>
    py_line      = first:py_simple rest:py_moreline* <newline>
    py_moreline  = ';' stmt:py_simple

    py_stmt      = nested:py_def | bad:py_badword | if:py_if | while:py_while
                 | for:py_for | line:py_line
    py_badword   = 'class' | 'import' | 'from' | 'lambda' | 'try' | 'with'
                 | 'yield' | 'global' | 'nonlocal' | 'assert' | 'del'
                 | 'raise' | 'def'

    py_if        = 'if' cond:py_expr then:py_suite tail:py_iftail?
    py_iftail    = elif:py_elif | else:py_else
    py_elif      = 'elif' cond:py_expr then:py_suite tail:py_iftail?
    py_else      = 'else' body:py_suite
    py_while     = 'while' cond:py_expr body:py_suite
    py_for       = 'for' name:symbol 'in' 'range' '(' args:py_rangearg* ')'
                   body:py_suite
    py_rangearg  = value:py_expr ','?

    py_simple    = pass:'pass' | brk:'break' | cont:'continue' | ret:py_return
                 | show:py_print | aug:py_augassign | set:py_assign
                 | expr:py_expr
    py_return    = 'return' value:py_expr?
    py_print     = 'print' '(' args:py_printarg* ')'
    py_printarg  = str:py_printstr | val:py_printval
    py_printstr  = text:string ','?
    py_printval  = value:py_expr ','?
    py_assign    = name:symbol '=' value:py_expr
    py_augassign = name:symbol op:py_augop value:py_expr
    py_augop     = '+=' | '-=' | '*=' | '/=' | '%='

    py_expr      = pre:py_notop* first:py_unary rest:py_oprest*
    py_oprest    = op:py_binop pre:py_notop* right:py_unary
    py_binop     = operator | 'and' | 'or'
    py_notop     = 'not'

    py_unary     = neg:py_neg | pos:py_pos | inv:py_inv | py_postfix
    py_neg       = '-' value:py_unary
    py_pos       = '+' value:py_unary
    py_inv       = '~' value:py_unary
    py_postfix   = call:py_call | py_primary
    py_call      = name:symbol '(' args:py_callarg* ')'
    py_callarg   = value:py_expr ','?
    py_primary   = num:number | str:string | name:symbol | paren:py_paren
    py_paren     = '(' value:py_expr ')'
}

// Python's whole ladder, loosest level first. `not` is the prefix level, so it
// wraps the comparison to its right instead of one operand of it.
func py_table() *PrecTable {
    var t *PrecTable = prec_new();
    prec_left(t, "||");
    prec_left(t, "&&");
    prec_prefix(t, "!");
    prec_left(t, "== != < <= > >=");
    prec_left(t, "|");
    prec_left(t, "^");
    prec_left(t, "&");
    prec_left(t, "<< >>");
    prec_left(t, "+ -");
    prec_left(t, "* / %");
    return t;
}

// ============================================================
// Diagnostics
// ============================================================

// A reader that reports a syntax error and then hands back a program anyway is
// how a bad parse turns into a mystery further down the pipeline - most often a
// function that simply isn't there. Every error here is fatal.
func py_fail(msg *u8, node *PNode) void {
    pnode_print_error(node, py_src, "minipy", msg);
    exit(1);
}

// An alternative the grammar can produce and lowering forgot. Names the branch
// rather than guessing, so a grammar edit cannot silently lose a case.
func py_unhandled(what *u8, node *PNode) void {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "internal: unhandled ");
    sb_str(sb, what);
    sb_str(sb, " branch '");
    var b *u8 = pnode_branch(node);
    if b == nil { sb_str(sb, "<none>"); } else { sb_str(sb, b); }
    sb_str(sb, "'");
    py_fail(sb_finish(sb), node);
}

// ============================================================
// Expressions
// ============================================================

// Python spells four of its operators differently from the kernel. Only the AST
// sees the kernel's spelling - the parse tree and every diagnostic keep the one
// the source used. `//` is floor division, and every value here is an i64, so
// `/` already means it.
func py_op_ast(op *u8) *u8 {
    if streq(op, "or") { return "||"; }
    if streq(op, "and") { return "&&"; }
    if streq(op, "not") { return "!"; }
    if streq(op, "//") { return "/"; }
    return op;
}

// `not` is an operator pushed where an operand belongs, which is what tells the
// table it is a prefix. Any number may stack up: `not not x`.
func py_push_prefix(e *PrecExpr, pre *PNode) void {
    var n i64 = vec_len(pre.children);
    var i i64 = 0;
    while i < n {
        var op *PNode = vec_get(pre.children, i);
        prec_op(e, py_op_ast(op.text));
        i = i + 1;
    }
}

// One flat operand/operator list for the whole ladder, resolved by the table.
//
// Python's `a < b < c` means `a < b and b < c`, not `(a < b) < c`. Rather than
// quietly compile the wrong program, refuse it - and count per chain, since any
// operator looser than a comparison ends one: `a < b or c < d` is two chains.
// Reader-local Pratt climb keeps source operator nodes alongside the flat items.
// Avoid every spelling present in the reader input, including locals and parameters.
func arli_py_floor_mod_name(part *u8, offset i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "arli_py_floor_mod_");
    sb_str(sb, part);
    sb_str(sb, "_");
    sb_int(sb, offset);
    var name *u8 = sb_finish(sb);
    while arli_py_floor_mod_contains(py_src, name) {
        var next *StringBuilder = sb_new();
        sb_str(next, name);
        sb_str(next, "_");
        name = sb_finish(next);
    }
    return name;
}

func arli_py_floor_mod_contains(source *u8, name *u8) bool {
    var i i64 = 0;
    while *(source + i) != 0 {
        var j i64 = 0;
        while *(name + j) != 0 && *(source + i + j) == *(name + j) {
            j = j + 1;
        }
        if *(name + j) == 0 { return true; }
        i = i + 1;
    }
    return false;
}

func arli_py_floor_mod_binary(op *u8, node *PNode, left *u8, right *u8) *u8 {
    if !streq(op, "//") && !streq(op, "%") {
        return ast_binop(py_op_ast(op), left, right);
    }
    var a *u8 = arli_py_floor_mod_name("a", node.start);
    var b *u8 = arli_py_floor_mod_name("b", node.start);
    var q *u8 = arli_py_floor_mod_name("q", node.start);
    var r *u8 = arli_py_floor_mod_name("r", node.start);
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(a, ast_type_i64(), left));
    ast_push(stmts, ast_var(b, ast_type_i64(), right));
    ast_push(stmts, ast_var(q, ast_type_i64(), ast_binop("/", ast_ident(a), ast_ident(b))));
    ast_push(stmts, ast_var(r, ast_type_i64(), ast_binop("%", ast_ident(a), ast_ident(b))));
    var differs *u8 = ast_binop("!=", ast_binop("<", ast_ident(a), ast_int(0)),
                               ast_binop("<", ast_ident(b), ast_int(0)));
    var cond *u8 = ast_binop("&&", ast_binop("!=", ast_ident(r), ast_int(0)), differs);
    var target *u8 = q;
    var adjustment *u8 = ast_binop("-", ast_ident(q), ast_int(1));
    if streq(op, "%") {
        target = r;
        adjustment = ast_binop("+", ast_ident(r), ast_ident(b));
    }
    ast_push(stmts, ast_if(cond, ast_block1(ast_assign(ast_ident(target), adjustment)), nil));
    return ast_block_expr(stmts, ast_ident(target));
}

func arli_py_floor_mod_parse(e *PrecExpr, nodes *u8, pos *i64, minlevel i64) *u8 {
    var n i64 = vec_len(e.items);
    if *pos >= n { return nil; }
    var left *u8 = nil;
    if vec_get(e.kinds, *pos) == PREC_OP {
        var raw *u8 = vec_get(e.items, *pos);
        var pre *PrecOp = prec_find_prefix(e.table, py_op_ast(raw));
        if pre == nil { return nil; }
        if pre.level < minlevel {
            eprint("reader lowering error: operator '");
            eprint(py_op_ast(raw));
            eprintln("' binds too loosely to be an operand here");
            return nil;
        }
        *pos = *pos + 1;
        var operand *u8 = arli_py_floor_mod_parse(e, nodes, pos, pre.level);
        if operand == nil { return nil; }
        left = ast_unop(py_op_ast(raw), operand);
    } else {
        left = vec_get(e.items, *pos);
        *pos = *pos + 1;
    }
    while *pos < n {
        if vec_get(e.kinds, *pos) != PREC_OP { return nil; }
        var op *u8 = vec_get(e.items, *pos);
        var level i64 = prec_of(e.table, py_op_ast(op));
        if level == 0 { return nil; }
        if level < minlevel { return left; }
        var opnode *PNode = vec_get(nodes, *pos);
        *pos = *pos + 1;
        var right *u8 = arli_py_floor_mod_parse(e, nodes, pos, level + 1);
        if right == nil { return nil; }
        left = arli_py_floor_mod_binary(op, opnode, left, right);
    }
    return left;
}

func py_expr_of(node *PNode) *u8 {
    var t *PrecTable = py_table();
    var cmp_level i64 = prec_of(t, "==");
    var e *PrecExpr = prec_expr(t);
    var nodes *u8 = vec_new(8);
    py_push_prefix(e, pnode_require(node, "pre"));
    prec_operand(e, py_unary_of(pnode_require(node, "first")));
    while vec_len(nodes) < vec_len(e.items) { vec_push(nodes, nil); }

    var rest *PNode = pnode_require(node, "rest");
    var n i64 = vec_len(rest.children);
    var cmps i64 = 0;
    var i i64 = 0;
    while i < n {
        var item *PNode = vec_get(rest.children, i);
        var op *PNode = pnode_require(item, "op");
        var spelled *u8 = py_op_ast(op.text);
        var level i64 = prec_of(t, spelled);
        if level == cmp_level {
            cmps = cmps + 1;
            if cmps > 1 {
                py_fail("chained comparison (a < b < c) is not supported", op);
            }
        } else if level < cmp_level {
            cmps = 0;
        }
        prec_op(e, op.text);
        vec_push(nodes, op);
        py_push_prefix(e, pnode_require(item, "pre"));
        prec_operand(e, py_unary_of(pnode_require(item, "right")));
        while vec_len(nodes) < vec_len(e.items) { vec_push(nodes, nil); }
        i = i + 1;
    }
    var pos i64 = 0;
    var built *u8 = arli_py_floor_mod_parse(e, nodes, &pos, 1);
    if built == nil { py_fail("this operator is not in the minipy subset", node); }
    return built;
}

func py_unary_of(node *PNode) *u8 {
    if pnode_is(node, "neg") {
        return ast_neg(py_unary_of(pnode_require(node, "value")));
    }
    if pnode_is(node, "pos") {
        return py_unary_of(pnode_require(node, "value"));
    }
    if pnode_is(node, "inv") {
        return ast_binop("^", py_unary_of(pnode_require(node, "value")),
                         ast_neg(ast_int(1)));
    }
    // py_unary's last alternative is left unlabeled: py_postfix labels its own,
    // and one node carries one branch name.
    return py_postfix_of(node);
}

func py_postfix_of(node *PNode) *u8 {
    if pnode_is(node, "call") {
        var name *PNode = pnode_require(node, "name");
        var args *PNode = pnode_require(node, "args");
        var out *u8 = ast_vec();
        var n i64 = vec_len(args.children);
        var i i64 = 0;
        while i < n {
            var arg *PNode = vec_get(args.children, i);
            ast_push(out, py_expr_of(pnode_require(arg, "value")));
            i = i + 1;
        }
        // Any name, defined here or in any other language in the binary.
        return ast_span(ast_call_named(name.text, out), name.start, node.end);
    }
    return py_primary_of(node);
}

func py_primary_of(node *PNode) *u8 {
    if pnode_is(node, "num") { return ast_number(node.text); }
    if pnode_is(node, "str") {
        py_fail("a string may only be an argument to print in this subset", node);
    }
    if pnode_is(node, "name") {
        if streq(node.text, "True")  { return ast_int(1); }
        if streq(node.text, "False") { return ast_int(0); }
        if streq(node.text, "None")  { return ast_int(0); }
        return ast_ident(node.text);
    }
    if pnode_is(node, "paren") {
        return py_expr_of(pnode_require(node, "value"));
    }
    py_unhandled("py_primary", node);
    return nil;
}

// ============================================================
// Statements
// ============================================================

func py_name_in(names *u8, name *u8) i64 {
    var n i64 = vec_len(names);
    var i i64 = 0;
    while i < n {
        var s *u8 = vec_get(names, i);
        if streq(s, name) { return 1; }
        i = i + 1;
    }
    return 0;
}

func py_note_local(locals *u8, name *u8) void {
    if py_name_in(locals, name) == 0 { vec_push(locals, name); }
}

// A per-node-unique name for a compiler-introduced temp.
func py_gensym(prefix *u8, idx i64) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    sb_int(sb, idx);
    return sb_finish(sb);
}

// `print(a, "b", c)` -> py_int(a); py_space(); py_str("b"); ... ; py_nl().
// Which call an argument becomes is decided from its syntax right here, which
// is how a variadic polymorphic builtin survives lowering into a language that
// has neither.
func py_print_into(node *PNode, stmts *u8) void {
    var args *PNode = pnode_require(node, "args");
    var n i64 = vec_len(args.children);
    var i i64 = 0;
    while i < n {
        if i > 0 { ast_push(stmts, ast_expr_stmt(ast_call_named0("py_space"))); }
        var arg *PNode = vec_get(args.children, i);
        if pnode_is(arg, "str") {
            var text *PNode = pnode_require(arg, "text");
            ast_push(stmts, ast_expr_stmt(
                ast_call_named1("py_str", ast_string(text.text))));
        } else if pnode_is(arg, "val") {
            ast_push(stmts, ast_expr_stmt(ast_call_named1(
                "py_int", py_expr_of(pnode_require(arg, "value")))));
        } else {
            py_unhandled("py_printarg", arg);
        }
        i = i + 1;
    }
    ast_push(stmts, ast_expr_stmt(ast_call_named0("py_nl")));
}

// Statements that cannot contain a block.
func py_simple_into(node *PNode, stmts *u8, locals *u8) void {
    var start i64 = ast_vec_len(stmts);
    py_simple_into_inner(node, stmts, locals);
    while start < ast_vec_len(stmts) {
        vec_set(stmts, start, ast_span(ast_vec_get(stmts, start), node.start, node.end));
        start = start + 1;
    }
}

func py_simple_into_inner(node *PNode, stmts *u8, locals *u8) void {
    if pnode_is(node, "pass") { return; }
    if pnode_is(node, "brk") { ast_push(stmts, ast_break(nil)); return; }
    if pnode_is(node, "cont") { ast_push(stmts, ast_continue(nil)); return; }
    if pnode_is(node, "ret") {
        var value *PNode = pnode_get(node, "value");
        if value == nil { ast_push(stmts, ast_return(ast_int(0))); }
        else { ast_push(stmts, ast_return(py_expr_of(value))); }
        return;
    }
    if pnode_is(node, "show") { py_print_into(node, stmts); return; }
    if pnode_is(node, "aug") {
        var name *PNode = pnode_require(node, "name");
        var op *PNode = pnode_require(node, "op");
        py_note_local(locals, name.text);
        // `+=` is one token; the lang operator is its first character.
        var optext *u8 = op.text;
        var bin *u8 = alloc(2);
        *bin = *optext;
        *(bin + 1) = 0;
        ast_push(stmts, ast_assign(ast_ident(name.text),
            ast_binop(bin, ast_ident(name.text),
                      py_expr_of(pnode_require(node, "value")))));
        return;
    }
    if pnode_is(node, "set") {
        var name *PNode = pnode_require(node, "name");
        py_note_local(locals, name.text);
        ast_push(stmts, ast_assign(ast_ident(name.text),
                                   py_expr_of(pnode_require(node, "value"))));
        return;
    }
    if pnode_is(node, "expr") {
        ast_push(stmts, ast_expr_stmt(py_expr_of(node)));
        return;
    }
    py_unhandled("py_simple", node);
}

func py_line_into(node *PNode, stmts *u8, locals *u8) void {
    py_simple_into(pnode_require(node, "first"), stmts, locals);
    var rest *PNode = pnode_require(node, "rest");
    var n i64 = vec_len(rest.children);
    var i i64 = 0;
    while i < n {
        var item *PNode = vec_get(rest.children, i);
        py_simple_into(pnode_require(item, "stmt"), stmts, locals);
        i = i + 1;
    }
}

// `:` followed by either an indented block or a one-line suite. Statements are
// appended to the caller's vec so a desugaring can wrap them (see py_for_into).
func py_suite_into(node *PNode, stmts *u8, locals *u8) void {
    var body *PNode = pnode_require(node, "body");
    if pnode_is(body, "inline") { py_line_into(body, stmts, locals); return; }
    if pnode_is(body, "block") {
        var lines *PNode = pnode_require(body, "stmts");
        var n i64 = vec_len(lines.children);
        var i i64 = 0;
        while i < n {
            py_stmt_into(vec_get(lines.children, i), stmts, locals);
            i = i + 1;
        }
        return;
    }
    py_unhandled("py_suitebody", body);
}

func py_suite_block(node *PNode, locals *u8) *u8 {
    var stmts *u8 = ast_vec();
    py_suite_into(node, stmts, locals);
    return ast_block(stmts);
}

// `elif` is just an `if` in the else branch, so both spellings lower here.
func py_if_into(node *PNode, stmts *u8, locals *u8) void {
    var cond *u8 = py_expr_of(pnode_require(node, "cond"));
    var then_b *u8 = py_suite_block(pnode_require(node, "then"), locals);
    var else_b *u8 = nil;
    var tail *PNode = pnode_get(node, "tail");
    if tail != nil {
        if pnode_is(tail, "elif") {
            var eb *u8 = ast_vec();
            py_if_into(tail, eb, locals);
            else_b = ast_block(eb);
        } else if pnode_is(tail, "else") {
            else_b = py_suite_block(pnode_require(tail, "body"), locals);
        } else {
            py_unhandled("py_iftail", tail);
        }
    }
    ast_push(stmts, ast_if(cond, then_b, else_b));
}

func py_while_into(node *PNode, stmts *u8, locals *u8) void {
    var cond *u8 = py_expr_of(pnode_require(node, "cond"));
    ast_push(stmts, ast_while(cond,
        py_suite_block(pnode_require(node, "body"), locals)));
}

// A literal integer, optionally negated - the only form `range`'s step may
// take, because the direction of the loop test has to be known at read time.
func py_no_step(node *PNode) void {
    py_fail("range's step must be an integer literal", node);
}

func py_step_literal(node *PNode) i64 {
    if vec_len(pnode_require(node, "pre").children) != 0 { py_no_step(node); }
    if vec_len(pnode_require(node, "rest").children) != 0 { py_no_step(node); }
    var unary *PNode = pnode_require(node, "first");
    var neg i64 = 0;
    if pnode_is(unary, "neg") {
        neg = 1;
        unary = pnode_require(unary, "value");
    }
    if !pnode_is(unary, "num") { py_no_step(node); }
    var v i64 = py_str_to_int(unary.text);
    if neg == 1 { return 0 - v; }
    return v;
}

func py_str_to_int(s *u8) i64 {
    var neg i64 = 0;
    if *s == 45 {
        neg = 1;
        s = s + 1;
    }
    var n i64 = 0;
    while *s != 0 {
        n = n * 10 + (*s - 48);
        s = s + 1;
    }
    if neg == 1 { return 0 - n; }
    return n;
}

// Mark every decimal prefix following a matching base. A source of N bytes
// cannot contain all N+1 distinct candidates, so a free slot always exists.
func arli_py_range_order_mark(src *u8, base *u8, used *u8, size i64) void {
    if !py_starts(src, base) { return; }
    *used = 1;
    var p *u8 = src + strlen(base);
    if *p != 95 { return; }
    p = p + 1;
    var n i64 = 0;
    while *p >= 48 && *p <= 57 {
        var digit i64 = *p - 48;
        if n > (size - digit) / 10 { return; }
        n = n * 10 + digit;
        if n > size { return; }
        *(used + n) = 1;
        p = p + 1;
    }
}

// `for v in range(start, limit, step): body`
//
//     __lim = limit
//     v = start - step
//     while 1:
//         v = v + step
//         if v >= __lim: break
//         body
//
// The step happens at the TOP of the body, not the bottom, so that `continue`
// still advances the loop - lang's `continue` jumps to the loop condition, and a
// bottom increment would be skipped, turning a Python `continue` into a hang.
// Biasing the initial value by one step is what buys that placement. Both range
// bounds are evaluated exactly once, as in Python.
func py_for_into(node *PNode, stmts *u8, locals *u8) void {
    var vnode *PNode = pnode_require(node, "name");
    var vname *u8 = vnode.text;
    py_note_local(locals, vname);

    var args *PNode = pnode_require(node, "args");
    var nargs i64 = vec_len(args.children);
    if nargs < 1 || nargs > 3 {
        py_fail("range takes one, two or three arguments", node);
    }
    var start *u8 = ast_int(0);
    var limit *u8 = nil;
    var step i64 = 1;
    var first *PNode = pnode_require(vec_get(args.children, 0), "value");
    if nargs == 1 {
        limit = py_expr_of(first);
    } else {
        start = py_expr_of(first);
        limit = py_expr_of(pnode_require(vec_get(args.children, 1), "value"));
        if nargs == 3 {
            step = py_step_literal(pnode_require(vec_get(args.children, 2), "value"));
        }
    }
    if step == 0 { py_fail("range's step may not be zero", node); }

    // The offset distinguishes loops; a decimal retry distinguishes source
    // collisions. Both are nonnegative i64 values, so the longest name is
    // 11 + 19 + 1 + 19 = 50 bytes, below LLVM's 64-byte storage.
    var start_base *u8 = py_gensym("__py_start", node.start);
    var lim_base *u8 = py_gensym("__py_lim", node.start);
    var cursor_base *u8 = py_gensym("__py_cursor", node.start);
    var size i64 = strlen(py_src);
    var used *u8 = malloc(size + 1);
    var scan i64 = 0;
    while scan <= size { *(used + scan) = 0; scan = scan + 1; }
    scan = 0;
    while scan < size {
        arli_py_range_order_mark(py_src + scan, start_base, used, size);
        arli_py_range_order_mark(py_src + scan, lim_base, used, size);
        arli_py_range_order_mark(py_src + scan, cursor_base, used, size);
        scan = scan + 1;
    }
    var retry i64 = 0;
    while retry <= size && *(used + retry) != 0 { retry = retry + 1; }
    if retry > size { py_fail("range temporary names exhausted", node); }
    var start_name *u8 = start_base;
    var lim_name *u8 = lim_base;
    var cursor_name *u8 = cursor_base;
    if retry != 0 {
        start_name = py_gensym(str_concat(start_base, "_"), retry);
        lim_name = py_gensym(str_concat(lim_base, "_"), retry);
        cursor_name = py_gensym(str_concat(cursor_base, "_"), retry);
    }
    ast_push(stmts, ast_var(start_name, ast_type_i64(), start));
    ast_push(stmts, ast_var(lim_name, ast_type_i64(), limit));
    ast_push(stmts, ast_var(cursor_name, ast_type_i64(), ast_ident(start_name)));

    var body *u8 = ast_vec();
    ast_push(body, ast_assign(ast_ident(vname), ast_ident(cursor_name)));
    ast_push(body, ast_assign(ast_ident(cursor_name),
                              ast_binop("+", ast_ident(cursor_name), ast_int(step))));
    py_suite_into(pnode_require(node, "body"), body, locals);
    var cmp *u8 = "<";
    if step < 0 { cmp = ">"; }
    ast_push(stmts, ast_while(ast_binop(cmp, ast_ident(cursor_name), ast_ident(lim_name)),
                              ast_block(body)));
}

func py_stmt_into(node *PNode, stmts *u8, locals *u8) void {
    if pnode_is(node, "nested") {
        py_fail("nested functions are not supported", node);
    }
    if pnode_is(node, "bad") {
        py_fail("this statement is not in the minipy subset", node);
    }
    if pnode_is(node, "if") { py_if_into(node, stmts, locals); return; }
    if pnode_is(node, "while") { py_while_into(node, stmts, locals); return; }
    if pnode_is(node, "for") { py_for_into(node, stmts, locals); return; }
    if pnode_is(node, "line") { py_line_into(node, stmts, locals); return; }
    py_unhandled("py_stmt", node);
}

func py_starts(s *u8, p *u8) i64 {
    while *p != 0 {
        if *s == 0 { return 0; }
        if *s != *p { return 0; }
        s = s + 1;
        p = p + 1;
    }
    return 1;
}

// ============================================================
// Definitions
// ============================================================

// `def f(a, b): body` -> func f(a i64, b i64) i64 { ... }
//
// Python scopes a name to the whole function no matter which branch assigns it;
// lang scopes a `var` to its enclosing block. Every assigned name is therefore
// collected while the body is lowered and declared once at the top, so an
// assignment inside an `if` is still visible after it - which is exactly the
// mismatch that would otherwise make a faithful-looking program fail to compile.
func py_def_of(node *PNode) *u8 {
    var name *PNode = pnode_require(node, "name");
    var params *u8 = ast_vec();
    var pnames *u8 = vec_new(8);
    var plist *PNode = pnode_require(node, "params");
    var np i64 = vec_len(plist.children);
    var i i64 = 0;
    while i < np {
        var item *PNode = vec_get(plist.children, i);
        var p *PNode = pnode_require(item, "name");
        if i + 1 < np {
            if vec_len(item.children) < 2 || pnode_child(item, 1) == nil {
                py_fail("parameter separator required", p);
            }
        }
        if streq(p.text, "True") || streq(p.text, "False") || streq(p.text, "None") {
            py_fail("reserved parameter", p);
        }
        if py_name_in(pnames, p.text) != 0 { py_fail("duplicate parameter", p); }
        ast_push(params, ast_param(p.text, ast_type_i64()));
        vec_push(pnames, p.text);
        i = i + 1;
    }

    var locals *u8 = vec_new(16);
    var body *u8 = ast_vec();
    py_suite_into(pnode_require(node, "body"), body, locals);

    var all *u8 = ast_vec();
    var nl i64 = vec_len(locals);
    i = 0;
    while i < nl {
        var ln *u8 = vec_get(locals, i);
        if py_name_in(pnames, ln) == 0 {
            ast_push(all, ast_var(ln, ast_type_i64(), ast_int(0)));
        }
        i = i + 1;
    }
    var nb i64 = ast_vec_len(body);
    i = 0;
    while i < nb {
        ast_push(all, ast_vec_get(body, i));
        i = i + 1;
    }
    // A Python function that runs off the end returns None; here that is 0.
    var tail_returns i64 = 0;
    if nb > 0 {
        if py_starts(ast_vec_get(body, nb - 1), "(return") == 1 { tail_returns = 1; }
    }
    if tail_returns == 0 { ast_push(all, ast_return(ast_int(0))); }

    return ast_span(ast_func(name.text, params, ast_type_i64(), ast_block(all)), node.start, node.end);
}

reader minipy(text *u8) *u8 {
    py_src = text;
    var t *Tokenizer = tok_new_stream(text, py_lex(text));
    var tree *PNode = parse_py_program(t);
    var complete bool = false;
    if tree != nil { complete = tok_expect_end(t); }
    if !complete {
        tok_print_error(t, "minipy");
        exit(1);
    }
    var decls *u8 = ast_vec();
    var defs *PNode = pnode_require(tree, "defs");
    var n i64 = vec_len(defs.children);
    var i i64 = 0;
    while i < n {
        ast_push(decls, py_def_of(vec_get(defs.children, i)));
        i = i + 1;
    }
    return ast_program(decls);
}

example/flow/flow.lang:
// ============================================================
// flow - a tiny generator/coroutine language (the effects DSL)
// ============================================================
//
// The third polyglot language. Where C is imperative and minilisp is functional,
// flow is about CONTROL: generators that suspend and resume. It lowers to lang's
// algebraic effects (perform/handle/resume) - something neither C nor our Lisp
// can express. Built with #parser{} (Level 3) + the std/ast.lang builder (L1).
//
//   #flow{
//     gen fib(n) {                 // a stateful generator
//       var a = 0; var b = 1; var i = 0;
//       while i < n { yield a; var t = a + b; a = b; b = t; i = i + 1; }
//     }
//     func sum_fib(n) {            // a driver: runs the generator, sums the values
//       var total = 0;
//       for x in fib(n) { total = total + x; }
//       return total;
//     }
//   }
//
// `yield e` performs Yield(e); `for x in g(...) {body}` lowers to a handle that
// binds each yielded value to x, runs body, and resumes the generator. Both
// `gen` and `func` become ordinary i64 functions, callable from lang and C.
//
// Conditions are unparenthesized (`if c {}`, `while c {}`) - flow is its own
// little language, not C. Everything is i64. Requires:
//   include "example/flow/flow_runtime.lang"   (declares `effect Yield`)
//
// Converter helpers are fl_-prefixed so flow composes with the C and minilisp
// readers in one binary (no symbol collisions).

include "std/core.lang"
include "std/tok.lang"
include "std/parser_reader.lang"
include "std/ast.lang"
include "std/prec.lang"

#parser{
    flow_program  = flow_decl+
    flow_decl     = gen:flow_gendecl | func:flow_funcdecl
    flow_gendecl  = 'gen' name:symbol '(' params:flow_params ')' body:flow_block
    flow_funcdecl = 'func' name:symbol '(' params:flow_params ')' body:flow_block
    flow_params   = flow_paramitem*
    flow_paramitem = name:symbol | ','
    flow_block    = '{' stmts:flow_stmt* '}'
    flow_stmt     = var:flow_var | yield:flow_yield | send:flow_send | return:flow_return | if:flow_if | while:flow_while | for:flow_forin | expr:flow_exprstmt
    flow_var      = 'var' name:symbol '=' value:flow_expr ';'
    flow_yield    = 'yield' value:flow_expr ';'
    flow_send     = 'send' value:flow_expr ';'
    flow_return   = 'return' value:flow_expr ';'
    flow_if       = 'if' cond:flow_expr then:flow_block elses:flow_elses
    flow_elses    = flow_elsepart*
    flow_elsepart = 'else' body:flow_block
    flow_while    = 'while' cond:flow_expr body:flow_block
    flow_forin    = 'for' name:symbol 'in' call:flow_call body:flow_block
    flow_call     = name:symbol '(' args:flow_args ')'
    flow_exprstmt = value:flow_expr ';'
    flow_expr     = first:flow_unary rest:flow_oprest*
    flow_oprest   = op:operator right:flow_unary
    flow_unary    = neg:flow_neg | postfix:flow_postfix
    flow_neg      = op:operator operand:flow_postfix
    flow_postfix  = primary:flow_primary calls:flow_callopt*
    flow_callopt  = '(' args:flow_args ')'
    flow_args     = flow_argitem*
    flow_argitem  = arg:flow_expr | ','
    flow_primary  = yieldexpr:flow_yieldexpr | num:number | sym:symbol | paren:flow_paren
    flow_yieldexpr = 'yield' value:flow_expr
    flow_paren    = '(' inner:flow_expr ')'
}

// PNode kinds: 1=number, 2=symbol, 4=list/seq, 5=operator, 0=literal marker

var fl_src *u8 = nil;

// ============================================================
// Expressions (a flat operand/op list resolved by std/prec.lang)
// ============================================================

// Loosest level first. `=` leads, because assignment binds looser than every
// operator and associates to the right; prec_build refuses it outside statement
// position, which is what makes `f(a = b)` an error rather than a tree the
// kernel cannot lower.
func fl_table() *PrecTable {
    var t *PrecTable = prec_new();
    prec_assign(t, "=");
    prec_left(t, "||");
    prec_left(t, "&&");
    prec_left(t, "== !=");
    prec_left(t, "< > <= >=");
    prec_left(t, "+ -");
    prec_left(t, "* / %");
    return t;
}

// flow_expr = first:flow_unary rest:flow_oprest*. Push operands and operators
// in source order; the table decides the shape of the tree.
func fl_push_flat(expr *PrecExpr, e *PNode) void {
    prec_operand(expr, fl_emit_operand(pnode_require(e, "first")));

    var rest *PNode = pnode_require(e, "rest");
    var n i64 = vec_len(rest.children);
    var i i64 = 0;
    while i < n {
        var item *PNode = vec_get(rest.children, i);   // op:operator right:flow_unary
        var op *PNode = pnode_require(item, "op");
        prec_op(expr, op.text);
        prec_operand(expr, fl_emit_operand(pnode_require(item, "right")));
        i = i + 1;
    }
}

// std/prec.lang already named the operator it refused; a reader that carried on
// would turn that into a mystery further down the pipeline.
func fl_checked(value *u8, node *PNode) *u8 {
    if value == nil {
        pnode_print_error(node, fl_src, "flow", "this expression is not in the flow subset");
        exit(1);
    }
    return value;
}

func fl_emit_expr(e *PNode) *u8 {
    var expr *PrecExpr = prec_expr(fl_table());
    fl_push_flat(expr, e);
    return fl_checked(prec_build(expr), e);
}

// A branch the grammar can produce but this converter does not handle is a
// reader bug. Name it and stop - emitting a placeholder is how a reader turns
// its own gap into a mystery in the generated program.
func fl_unhandled(what *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, "unhandled ");
    sb_str(sb, what);
    var label *u8 = pnode_branch(node);
    if label == nil {
        sb_str(sb, " (the grammar left this alternative unlabeled)");
    } else {
        sb_str(sb, " branch '");
        sb_str(sb, label);
        sb_str(sb, "'");
    }
    pnode_print_error(node, fl_src, "flow", sb_finish(sb));
    exit(1);
    return nil;
}

// flow_unary = neg:flow_neg | postfix:flow_postfix. The grammar says which
// alternative matched, so lowering never has to sniff kinds or child order.
func fl_emit_operand(node *PNode) *u8 {
    if pnode_is(node, "neg") {
        var op *PNode = pnode_require(node, "op");
        return ast_unop(op.text, fl_emit_postfix(pnode_require(node, "operand")));
    }
    if pnode_is(node, "postfix") { return fl_emit_postfix(node); }
    return fl_unhandled("operand", node);
}

// flow_postfix = flow_primary flow_callopt*  ->  fold calls left-to-right.
func fl_emit_postfix(pf *PNode) *u8 {
    var primary *PNode = pnode_require(pf, "primary");
    var base *u8 = fl_emit_primary(primary);
    var ops *PNode = pnode_require(pf, "calls");
    var n i64 = vec_len(ops.children);
    var i i64 = 0;
    while i < n {
        var op *PNode = vec_get(ops.children, i);
        base = ast_span(ast_call(base, fl_emit_args(pnode_require(op, "args"))),
                        primary.start, op.end);
        i = i + 1;
    }
    return base;
}

func fl_emit_primary(p *PNode) *u8 {
    if pnode_is(p, "num") { return ast_number(p.text); }
    if pnode_is(p, "sym") { return ast_ident(fl_resolve(p.text)); }
    if pnode_is(p, "yieldexpr") {
        // yield as an expression: its value is what the driver resumed with.
        if fl_portable { fl_portable_error(p, "yield expressions require the native effects reader; portable flow supports statement yields"); }
        return ast_perform1("Yield", fl_emit_expr(pnode_require(p, "value")));
    }
    if pnode_is(p, "paren") {
        return fl_emit_expr(pnode_require(p, "inner"));
    }
    return fl_unhandled("expression", p);
}

// flow_args = flow_argitem* ; argitem = arg:flow_expr | ','. Build an arg vec.
func fl_emit_args(args *PNode) *u8 {
    var av *u8 = ast_vec();
    var items *u8 = args.children;
    var n i64 = vec_len(items);
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if pnode_is(it, "arg") { ast_push(av, fl_emit_expr(it)); }
        i = i + 1;
    }
    return av;
}

// ============================================================
// Statements
// ============================================================

// Per-node-unique name (handler bindings + block vars; derive from the stable source byte offset).
func fl_gensym(prefix *u8, node *PNode) *u8 {
    var sb *StringBuilder = sb_new();
    sb_str(sb, prefix);
    var offset i64 = node.start;
    sb_int(sb, offset);
    return sb_finish(sb);
}

// send_target = the enclosing for-in's send-register name (nil if none), so a
// `send` nested inside an if/while still targets the right driver's resume value.
func fl_emit_block(block *PNode, send_target *u8) *u8 {
    var saved *u8 = fl_bindings;
    var stmts *u8 = ast_vec();
    var sl *PNode = pnode_require(block, "stmts");
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(stmts, fl_emit_stmt(vec_get(sl.children, i), send_target));
        i = i + 1;
    }
    fl_bindings = saved;
    return ast_block(stmts);
}

func fl_emit_stmt(s *PNode, send_target *u8) *u8 {
    return ast_span(fl_emit_stmt_inner(s, send_target), s.start, s.end);
}

func fl_emit_stmt_inner(s *PNode, send_target *u8) *u8 {
    if pnode_is(s, "var") {
        var name *PNode = pnode_require(s, "name");
        var value *u8 = fl_emit_expr(pnode_require(s, "value"));
        var target *u8 = name.text;
        if fl_portable { target = fl_bind(name.text); }
        return ast_var(target, ast_type_i64(), value);
    }
    if pnode_is(s, "yield") {        // perform Yield(expr)
        if fl_portable { return fl_fused_yield(s); }
        return ast_expr_stmt(ast_perform1("Yield", fl_emit_expr(pnode_require(s, "value"))));
    }
    if pnode_is(s, "send") {         // set the resume value
        var sexpr *u8 = fl_emit_expr(pnode_require(s, "value"));
        if send_target == nil {
            return ast_expr_stmt(sexpr);   // defensive: `send` outside a for-in body
        }
        return ast_assign(ast_ident(send_target), sexpr);
    }
    if pnode_is(s, "return") {
        if fl_portable && fl_driver != nil {
            var stmts *u8 = ast_vec();
            ast_push(stmts, ast_expr_stmt(fl_emit_expr(pnode_require(s, "value"))));
            ast_push(stmts, ast_break(fl_driver.end));
            return ast_block(stmts);
        }
        return ast_return(fl_emit_expr(pnode_require(s, "value")));
    }
    if pnode_is(s, "if") {
        var cond *u8 = fl_emit_expr(pnode_require(s, "cond"));
        var then_b *u8 = fl_emit_block(pnode_require(s, "then"), send_target);
        var elses *PNode = pnode_require(s, "elses");
        var else_b *u8 = nil;
        if vec_len(elses.children) > 0 {
            var ep *PNode = vec_get(elses.children, 0);
            else_b = fl_emit_block(pnode_require(ep, "body"), send_target);
        }
        return ast_if(cond, then_b, else_b);
    }
    if pnode_is(s, "while") {
        return ast_while(fl_emit_expr(pnode_require(s, "cond")),
                         fl_emit_block(pnode_require(s, "body"), send_target));
    }
    if pnode_is(s, "for") { return fl_emit_forin(s); }
    if pnode_is(s, "expr") { return fl_emit_exprstmt(pnode_require(s, "value")); }
    return fl_unhandled("statement", s);
}

// A bare expression statement is the one place assignment is legal, so it is
// the one place that builds the same flat list as a statement.
func fl_emit_exprstmt(e *PNode) *u8 {
    var expr *PrecExpr = prec_expr(fl_table());
    fl_push_flat(expr, e);
    return fl_checked(prec_build_stmt(expr), e);
}

// for X in GEN(args) { body }  ->  drive the generator with a handle:
//   handle { GEN(args); } with {
//     return(__rv) => 0,
//     Yield(X, __k) => { var __send = 0; body; resume __k(__send); }
//   }
// The handler binds the yielded value to X and the continuation to __k; resuming
// runs the generator on to its next yield (carrying its locals across the gap).
// __send starts at 0 each value and is overwritten by any `send E;` in the body,
// so it flows back as the result of the generator's `yield` expression - making
// the channel bidirectional (a one-way generator simply never sends, resuming 0).
func fl_emit_forin(s *PNode) *u8 {
    if fl_portable { return fl_fused_forin(s); }
    var xvar *PNode = pnode_require(s, "name");
    var call *PNode = pnode_require(s, "call");
    var block *PNode = pnode_require(s, "body");

    var gname *PNode = pnode_require(call, "name");
    var gcall *u8 = ast_span(ast_call_named(gname.text, fl_emit_args(pnode_require(call, "args"))),
                             gname.start, call.end);

    var kname *u8 = fl_gensym("__k", s);
    var rvname *u8 = fl_gensym("__rv", s);
    var sname *u8 = fl_gensym("__send", s);

    // handler body = init send register, the for-body statements (with `send`
    // targeting this loop's register), then resume the generator with it.
    var hstmts *u8 = ast_vec();
    ast_push(hstmts, ast_var(sname, ast_type_i64(), ast_int(0)));
    var sl *PNode = pnode_require(block, "stmts");
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(hstmts, fl_emit_stmt(vec_get(sl.children, i), sname));
        i = i + 1;
    }
    ast_push(hstmts, ast_expr_stmt(ast_resume(ast_ident(kname), ast_ident(sname))));

    var eh *u8 = ast_effect_handler("Yield", xvar.text, kname, ast_block(hstmts));
    var ehs *u8 = ast_vec();
    ast_push(ehs, eh);
    var body *u8 = ast_block1(ast_expr_stmt(gcall));
    return ast_expr_stmt(ast_handle(body, ast_return_handler(rvname, ast_int(0)), ehs));
}

// ============================================================
// Declarations
// ============================================================

// flow_params = paramitem* ; paramitem = name:symbol | ','. All params are i64.
func fl_emit_params(params *PNode) *u8 {
    var pv *u8 = ast_vec();
    var items *u8 = params.children;
    var n i64 = vec_len(items);
    var i i64 = 0;
    while i < n {
        var it *PNode = vec_get(items, i);
        if pnode_is(it, "name") {
            var target *u8 = it.text;
            // An inlined generator's free names must still resolve to globals.
            if fl_portable { target = fl_bind(it.text); }
            ast_push(pv, ast_param(target, ast_type_i64()));
        }
        i = i + 1;
    }
    return pv;
}

// Does the statement list end in a `return`? (If not, the function needs an
// implicit one - generators fall off the end and an i64 fn must terminate.)
func fl_ends_in_return(sl *PNode) i64 {
    var n i64 = vec_len(sl.children);
    if n == 0 { return 0; }
    var last *PNode = vec_get(sl.children, n - 1);
    if pnode_is(last, "return") { return 1; }
    return 0;
}

// gen/func decl = [KW, name, '(', params, ')', block]. Both become (func name
// (params) i64 block) - the only difference is that a `gen` body uses `yield`
// and a `func` body uses `for-in`, but the lowering is identical. A trailing
// `return 0` is appended when the body doesn't end in a return (a generator just
// yields and falls off the end; its return value is the handle's ignored result).
// `gen` and `func` declare the same shape, so one lowering serves both: the two
// rules name their parts identically and flow_decl leaves them unlabeled.
func fl_emit_func(d *PNode) *u8 {
    var name *PNode = pnode_require(d, "name");
    var params *u8 = fl_emit_params(pnode_require(d, "params"));
    var sl *PNode = pnode_require(pnode_require(d, "body"), "stmts");
    var stmts *u8 = ast_vec();
    var n i64 = vec_len(sl.children);
    var i i64 = 0;
    while i < n {
        ast_push(stmts, fl_emit_stmt(vec_get(sl.children, i), nil));
        i = i + 1;
    }
    if fl_ends_in_return(sl) == 0 {
        ast_push(stmts, ast_return(ast_int(0)));
    }
    return ast_span(ast_func(name.text, params, ast_type_i64(), ast_block(stmts)), d.start, d.end);
}

func fl_emit_program(prog *PNode) *u8 {
    var decls *u8 = ast_vec();
    var dl *u8 = prog.children;
    var n i64 = vec_len(dl);
    var i i64 = 0;
    while i < n {
        ast_push(decls, fl_emit_func(vec_get(dl, i)));
        i = i + 1;
    }
    return ast_program(decls);
}

reader flow(text *u8) *u8 {
    fl_portable = 0;
    fl_bindings = nil;
    fl_src = text;
    var t *Tokenizer = tok_new(text);
    var prog *PNode = parse_flow_program(t);
    return fl_emit_program(prog);
}

// The portable reader specializes a generator at each synchronous for-in site.
// Each yield runs the driver's body inline, then continues the generator's
// structured loops with their locals intact. No continuation escapes and no
// target-specific effect machinery is needed. The effects reader above remains
// available for first-class native generator calls.
struct FlBinding { name *u8; target *u8; parent *FlBinding; }
struct FlExpansion { generator *PNode; parent *FlExpansion; }
struct FlDriver { node *PNode; bindings *u8; active *FlExpansion; end *u8; parent *FlDriver; }
var fl_portable i64 = 0;
var fl_bindings *u8 = nil;
var fl_decls *PNode = nil;
var fl_driver *FlDriver = nil;
var fl_active *FlExpansion = nil;
var fl_serial i64 = 0;

func fl_fresh() *u8 {
    fl_serial = fl_serial + 1;
    var sb *StringBuilder = sb_new();
    sb_str(sb, "__flow_portable_");
    sb_int(sb, fl_serial);
    var name *u8 = sb_finish(sb);
    // Avoid capturing identifiers supplied by this block, including names
    // that happen to use our generated prefix.
    var i i64 = 0;
    while *(fl_src + i) != 0 {
        var j i64 = 0;
        while *(name + j) != 0 && *(fl_src + i + j) == *(name + j) { j = j + 1; }
        if *(name + j) == 0 { return fl_fresh(); }
        i = i + 1;
    }
    return name;
}

func fl_resolve(name *u8) *u8 {
    var b *FlBinding = fl_bindings;
    while b != nil {
        if streq(b.name, name) { return b.target; }
        b = b.parent;
    }
    return name;
}

func fl_bind(name *u8) *u8 {
    var b *FlBinding = alloc(24);
    b.name = name;
    b.target = fl_fresh();
    b.parent = fl_bindings;
    fl_bindings = b;
    return b.target;
}

func fl_portable_error(node *PNode, message *u8) void {
    pnode_print_error(node, fl_src, "flow_portable", message);
    exit(1);
}

func fl_fused_yield(node *PNode) *u8 {
    if fl_driver == nil { fl_portable_error(node, "yield requires a statically driven generator"); }
    // Evaluate the value in the generator environment, then emit the driver
    // in its original environment. Neither side can capture the other's locals.
    var value *u8 = fl_emit_expr(pnode_require(node, "value"));
    var generator_bindings *u8 = fl_bindings;
    var driver *FlDriver = fl_driver;
    var active *FlExpansion = fl_active;
    fl_active = driver.active;
    fl_bindings = driver.bindings;
    // A driver body belongs to its lexical generator, which may itself be
    // driven. Keep that context for returns and yields in nested driver bodies.
    fl_driver = driver.parent;
    var x *u8 = fl_bind(pnode_require(driver.node, "name").text);
    var send *u8 = fl_fresh();
    var stmts *u8 = ast_vec();
    ast_push(stmts, ast_var(x, ast_type_i64(), value));
    ast_push(stmts, ast_var(send, ast_type_i64(), ast_int(0)));
    ast_push(stmts, fl_emit_block(pnode_require(driver.node, "body"), send));
    fl_bindings = generator_bindings;
    fl_driver = driver;
    fl_active = active;
    return ast_block(stmts);
}

func fl_fused_forin(node *PNode) *u8 {
    var call *PNode = pnode_require(node, "call");
    var name *PNode = pnode_require(call, "name");
    var generator *PNode = nil;
    var i i64 = 0;
    while i < vec_len(fl_decls.children) {
        var d *PNode = vec_get(fl_decls.children, i);
        if pnode_is(d, "gen") && streq(pnode_require(d, "name").text, name.text) { generator = d; }
        i = i + 1;
    }
    if generator == nil { fl_portable_error(call, "for-in requires a generator declared in this portable block"); }
    var active *FlExpansion = fl_active;
    while active != nil {
        if active.generator == generator { fl_portable_error(call, "recursive generator specialization is unsupported"); }
        active = active.parent;
    }
    // Arguments are evaluated once, left to right, before parameter binding.
    var args *u8 = fl_emit_args(pnode_require(call, "args"));
    var params *PNode = pnode_require(generator, "params");
    var stmts *u8 = ast_vec();
    var temps *u8 = ast_vec();
    i = 0;
    while i < vec_len(args) {
        var temp *u8 = fl_fresh();
        ast_push(stmts, ast_var(temp, ast_type_i64(), vec_get(args, i)));
        ast_push(temps, temp);
        i = i + 1;
    }
    var saved_bindings *u8 = fl_bindings;
    var saved_driver *FlDriver = fl_driver;
    var saved_active *FlExpansion = fl_active;
    fl_bindings = nil;
    var count i64 = 0;
    i = 0;
    while i < vec_len(params.children) {
        var p *PNode = vec_get(params.children, i);
        if pnode_is(p, "name") {
            if count >= vec_len(temps) { fl_portable_error(call, "generator argument count mismatch"); }
            ast_push(stmts, ast_var(fl_bind(p.text), ast_type_i64(), ast_ident(vec_get(temps, count))));
            count = count + 1;
        }
        i = i + 1;
    }
    if count != vec_len(temps) { fl_portable_error(call, "generator argument count mismatch"); }
    var driver *FlDriver = alloc(40);
    driver.node = node;
    driver.bindings = saved_bindings;
    driver.active = saved_active;
    driver.end = fl_fresh();
    driver.parent = saved_driver;
    fl_driver = driver;
    var expansion *FlExpansion = alloc(16);
    expansion.generator = generator;
    expansion.parent = saved_active;
    fl_active = expansion;
    var body *u8 = ast_vec();
    ast_push(body, fl_emit_block(pnode_require(generator, "body"), nil));
    ast_push(body, ast_break(driver.end));
    ast_push(stmts, ast_while_labeled(ast_int(1), ast_block(body), driver.end));
    fl_active = saved_active;
    fl_bindings = saved_bindings;
    fl_driver = saved_driver;
    return ast_block(stmts);
}

reader flow_portable(text *u8) *u8 {
    fl_src = text;
    fl_portable = 1;
    fl_serial = 0;
    fl_bindings = nil;
    fl_driver = nil;
    fl_active = nil;
    fl_decls = parse_flow_program(tok_new(text));
    var decls *u8 = ast_vec();
    var i i64 = 0;
    while i < vec_len(fl_decls.children) {
        var d *PNode = vec_get(fl_decls.children, i);
        if pnode_is(d, "func") {
            fl_bindings = nil;
            ast_push(decls, fl_emit_func(d));
        }
        i = i + 1;
    }
    return ast_program(decls);
}

example/minilisp/lisp_runtime.lang:
// ============================================================
// lisp_runtime - boxed-value runtime for the minilisp reader
// ============================================================
//
// Every Lisp value is an i64 that is really a *LispObj pointer. The kernel
// treats pointers as i64, so the code the #minilisp{} reader emits stays
// uniformly i64 and just calls these helpers. Include this ONCE in any program
// that uses #minilisp{} (include-dedup gives a single shared copy).
//
//   tag 0 = int    a = value
//   tag 1 = nil
//   tag 2 = cons   a = car, b = cdr
//   tag 3 = symbol a = char* name (interned: one object per distinct name)
//   tag 4 = closure a = kernel closure ptr ([tag][fn_ptr][captures])

include "std/core.lang"

struct LispObj {
    tag i64;
    a i64;
    b i64;
}

// Canonical nil, lazily allocated. A global in this INCLUDED file is fine - the
// reader-build path only drops globals declared in the reader's OWN source file.
var lisp_nil_obj i64 = 0;

func lisp_nil() i64 {
    if lisp_nil_obj == 0 {
        var o *LispObj = alloc(24);
        o.tag = 1; o.a = 0; o.b = 0;
        lisp_nil_obj = o;
    }
    return lisp_nil_obj;
}

func lisp_int(n i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 0; o.a = n; o.b = 0;
    return o;
}

func lisp_cons(car i64, cdr i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 2; o.a = car; o.b = cdr;
    return o;
}

// Interned symbols: a Lisp list of every symbol made so far (0 = not yet inited).
// Interning means same name -> same object, so symbols compare by identity (eq).
var lisp_symtab i64 = 0;

func lisp_sym(name *u8) i64 {
    if lisp_symtab == 0 { lisp_symtab = lisp_nil(); }
    var cur i64 = lisp_symtab;
    while lisp_tag(cur) == 2 {
        var s i64 = lisp_car(cur);
        var so *LispObj = s;
        var sname *u8 = so.a;
        if streq(sname, name) { return s; }
        cur = lisp_cdr(cur);
    }
    var o *LispObj = alloc(24);
    o.tag = 3; o.a = name; o.b = 0;
    var sym i64 = o;
    lisp_symtab = lisp_cons(sym, lisp_symtab);
    return sym;
}

func lisp_is_sym(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 3 { return 1; }
    return 0;
}

func lisp_sym_name(x i64) *u8 {
    var o *LispObj = x;
    return o.a;
}

func lisp_tag(x i64) i64 {
    var o *LispObj = x;
    return o.tag;
}

func lisp_is_nil(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 1 { return 1; }
    return 0;
}

// Box a kernel closure pointer as a first-class Lisp value (so lambdas can be
// stored in lists, returned, passed around). The reader wraps the lambda in a
// closure-typed binding first, so `c` is always a [tag][fn_ptr][captures] struct.
func lisp_closure(c i64) i64 {
    var o *LispObj = alloc(24);
    o.tag = 4; o.a = c; o.b = 0;
    return o;
}

func lisp_is_closure(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 4 { return 1; }
    return 0;
}

// Apply a boxed closure to an already-built Lisp argument list. Routing the
// kernel closure pointer through a closure-typed local hands the call to the
// kernel's tag-aware closure-call path (works for tag=0 and tag=1).
func lisp_apply(f i64, args i64) i64 {
    var o *LispObj = f;
    var c closure(i64) i64 = o.a;
    return c(args);
}

// Lisp truthiness: only nil is false (Common-Lisp style; 0 is truthy).
func lisp_truthy(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 1 { return 0; }
    return 1;
}

func lisp_car(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 2 { return o.a; }
    return lisp_nil();
}

func lisp_cdr(x i64) i64 {
    var o *LispObj = x;
    if o.tag == 2 { return o.b; }
    return lisp_nil();
}

func lisp_int_val(x i64) i64 {
    var o *LispObj = x;
    return o.a;
}

// Interop: extract a raw integer to call lang/C functions across syntaxes.
func lisp_to_int(x i64) i64 {
    var o *LispObj = x;
    return o.a;
}

func lisp_add(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) + lisp_int_val(y)); }
func lisp_sub(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) - lisp_int_val(y)); }
func lisp_mul(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) * lisp_int_val(y)); }
func lisp_div(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) / lisp_int_val(y)); }
func lisp_mod(x i64, y i64) i64 { return lisp_int(lisp_int_val(x) % lisp_int_val(y)); }

// Comparisons return canonical true (int 1) or nil.
func lisp_bool(b i64) i64 {
    if b != 0 { return lisp_int(1); }
    return lisp_nil();
}
func lisp_lt(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) < lisp_int_val(y)); }
func lisp_gt(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) > lisp_int_val(y)); }
func lisp_le(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) <= lisp_int_val(y)); }
func lisp_ge(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) >= lisp_int_val(y)); }
func lisp_num_eq(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) == lisp_int_val(y)); }
func lisp_ne(x i64, y i64) i64 { return lisp_bool(lisp_int_val(x) != lisp_int_val(y)); }

// Logical ops. Eager (args already evaluated) - fine for pure code; short-circuit
// would need a block_expr desugar (a refinement for when side effects land).
func lisp_not(x i64) i64 { return lisp_bool(lisp_truthy(x) == 0); }
func lisp_and(x i64, y i64) i64 { if lisp_truthy(x) != 0 { return y; } return x; }
func lisp_or(x i64, y i64) i64 { if lisp_truthy(x) != 0 { return x; } return y; }

// eq: ints compare by value, everything else by identity.
func lisp_eq(x i64, y i64) i64 {
    var ox *LispObj = x;
    var oy *LispObj = y;
    if ox.tag != oy.tag { return lisp_nil(); }
    if ox.tag == 0 { return lisp_bool(ox.a == oy.a); }
    return lisp_bool(x == y);
}

// Print a value: int, nil, or (a b c ...).
func lisp_print(x i64) void {
    var o *LispObj = x;
    if o.tag == 0 { print_int(o.a); return; }
    if o.tag == 1 { print("nil"); return; }
    if o.tag == 3 { var nm *u8 = o.a; print(nm); return; }
    if o.tag == 4 { print("<closure>"); return; }
    if o.tag == 2 {
        print("(");
        var cur i64 = x;
        var first i64 = 1;
        while lisp_tag(cur) == 2 {
            if first == 0 { print(" "); }
            first = 0;
            lisp_print(lisp_car(cur));
            cur = lisp_cdr(cur);
        }
        if lisp_is_nil(cur) == 0 {     // improper tail
            print(" . ");
            lisp_print(cur);
        }
        print(")");
        return;
    }
    print("?");
}

